import Foundation

struct Ayah: Identifiable, Decodable {
    let number: Int
    let arabic: String
    let transliteration: String
    let english: String
    var id: Int { number }
}

struct Surah: Identifiable, Decodable {
    let number: Int
    let name: String          // English name
    let arabicName: String
    let meaning: String
    /// Rough recitation time at an average pace, for sorting and display.
    let minutes: Double
    let ayahs: [Ayah]
    var id: Int { number }
}

/// Every surah that takes about 10 minutes or less to recite (66 of 114):
/// Al-Fatihah first, then from An-Nas backwards, the order kids usually learn
/// them. Recitation time is estimated from the length of the Arabic text at an
/// average pace (Ya-Sin is about 16 minutes).
/// Text: Uthmani script (quranenc.com), transliteration (tanzil.net) and the
/// Saheeh International English translation, via the quran-json package.
/// Stored in the app, so it works offline. Please check against your family's
/// preferred mushaf before giving the watch to your child.
enum QuranContent {
    static let surahs: [Surah] = {
        (try? JSONDecoder().decode([Surah].self, from: Data(json.utf8))) ?? []
    }()

    private static let json = #"""
[{"number":1,"name":"Al-Fatihah","arabicName":"الفاتحة","meaning":"The Opener","minutes":0.7,"ayahs":[{"number":1,"arabic":"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","transliteration":"Bismi Allahi alrrahmani alrraheemi","english":"In the name of Allah, the Entirely Merciful, the Especially Merciful"},{"number":2,"arabic":"ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","transliteration":"Alhamdu lillahi rabbi alAAalameena","english":"[All] praise is [due] to Allah, Lord of the worlds"},{"number":3,"arabic":"ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","transliteration":"Alrrahmani alrraheemi","english":"The Entirely Merciful, the Especially Merciful"},{"number":4,"arabic":"مَٰلِكِ يَوۡمِ ٱلدِّينِ","transliteration":"Maliki yawmi alddeeni","english":"Sovereign of the Day of Recompense"},{"number":5,"arabic":"إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ","transliteration":"Iyyaka naAAbudu waiyyaka nastaAAeenu","english":"It is You we worship and You we ask for help"},{"number":6,"arabic":"ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ","transliteration":"Ihdina alssirata almustaqeema","english":"Guide us to the straight path"},{"number":7,"arabic":"صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ","transliteration":"Sirata allatheena anAAamta AAalayhim ghayri almaghdoobi AAalayhim wala alddalleena","english":"The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray"}]},{"number":114,"name":"An-Nas","arabicName":"الناس","meaning":"Mankind","minutes":0.4,"ayahs":[{"number":1,"arabic":"قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ","transliteration":"Qul aAAoothu birabbi alnnasi","english":"Say, \"I seek refuge in the Lord of mankind"},{"number":2,"arabic":"مَلِكِ ٱلنَّاسِ","transliteration":"Maliki alnnasi","english":"The Sovereign of mankind"},{"number":3,"arabic":"إِلَٰهِ ٱلنَّاسِ","transliteration":"Ilahi alnnasi","english":"The God of mankind"},{"number":4,"arabic":"مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ","transliteration":"Min sharri alwaswasi alkhannasi","english":"From the evil of the retreating whisperer"},{"number":5,"arabic":"ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ","transliteration":"Allathee yuwaswisu fee sudoori alnnasi","english":"Who whispers [evil] into the breasts of mankind"},{"number":6,"arabic":"مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ","transliteration":"Mina aljinnati wa alnnasm","english":"From among the jinn and mankind"}]},{"number":113,"name":"Al-Falaq","arabicName":"الفلق","meaning":"The Daybreak","minutes":0.4,"ayahs":[{"number":1,"arabic":"قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ","transliteration":"Qul aAAoothu birabbi alfalaqi","english":"Say, \"I seek refuge in the Lord of daybreak"},{"number":2,"arabic":"مِن شَرِّ مَا خَلَقَ","transliteration":"Min sharri ma khalaqa","english":"From the evil of that which He created"},{"number":3,"arabic":"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","transliteration":"Wamin sharri ghasiqin itha waqaba","english":"And from the evil of darkness when it settles"},{"number":4,"arabic":"وَمِن شَرِّ ٱلنَّفَّـٰثَٰتِ فِي ٱلۡعُقَدِ","transliteration":"Wamin sharri alnnaffathati fee alAAuqadi","english":"And from the evil of the blowers in knots"},{"number":5,"arabic":"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","transliteration":"Wamin sharri hasidin itha hasada","english":"And from the evil of an envier when he envies"}]},{"number":112,"name":"Al-Ikhlas","arabicName":"الإخلاص","meaning":"The Sincerity","minutes":0.2,"ayahs":[{"number":1,"arabic":"قُلۡ هُوَ ٱللَّهُ أَحَدٌ","transliteration":"Qul huwa Allahu ahadun","english":"Say, \"He is Allah, [who is] One"},{"number":2,"arabic":"ٱللَّهُ ٱلصَّمَدُ","transliteration":"Allahu alssamadu","english":"Allah, the Eternal Refuge"},{"number":3,"arabic":"لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ","transliteration":"Lam yalid walam yooladu","english":"He neither begets nor is born"},{"number":4,"arabic":"وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ","transliteration":"Walam yakun lahu kufuwan ahadun","english":"Nor is there to Him any equivalent"}]},{"number":111,"name":"Al-Masad","arabicName":"المسد","meaning":"The Palm Fiber","minutes":0.4,"ayahs":[{"number":1,"arabic":"تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ","transliteration":"Tabbat yada abee lahabin watabba","english":"May the hands of Abu Lahab be ruined, and ruined is he"},{"number":2,"arabic":"مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ","transliteration":"Ma aghna AAanhu maluhu wama kasaba","english":"His wealth will not avail him or that which he gained"},{"number":3,"arabic":"سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ","transliteration":"Sayasla naran thata lahabin","english":"He will [enter to] burn in a Fire of [blazing] flame"},{"number":4,"arabic":"وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ","transliteration":"Waimraatuhu hammalata alhatabi","english":"And his wife [as well] - the carrier of firewood"},{"number":5,"arabic":"فِي جِيدِهَا حَبۡلٞ مِّن مَّسَدِۭ","transliteration":"Fee jeediha hablun min masadin","english":"Around her neck is a rope of [twisted] fiber"}]},{"number":110,"name":"An-Nasr","arabicName":"النصر","meaning":"The Divine Support","minutes":0.4,"ayahs":[{"number":1,"arabic":"إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ","transliteration":"Itha jaa nasru Allahi waalfathu","english":"When the victory of Allah has come and the conquest"},{"number":2,"arabic":"وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا","transliteration":"Waraayta alnnasa yadkhuloona fee deeni Allahi afwajan","english":"And you see the people entering into the religion of Allah in multitudes"},{"number":3,"arabic":"فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا","transliteration":"Fasabbih bihamdi rabbika waistaghfirhu innahu kana tawwaban","english":"Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance"}]},{"number":109,"name":"Al-Kafirun","arabicName":"الكافرون","meaning":"The Disbelievers","minutes":0.5,"ayahs":[{"number":1,"arabic":"قُلۡ يَـٰٓأَيُّهَا ٱلۡكَٰفِرُونَ","transliteration":"Qul ya ayyuha alkafiroona","english":"Say, \"O disbelievers"},{"number":2,"arabic":"لَآ أَعۡبُدُ مَا تَعۡبُدُونَ","transliteration":"La aAAbudu ma taAAbudoona","english":"I do not worship what you worship"},{"number":3,"arabic":"وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ","transliteration":"Wala antum AAabidoona ma aAAbudu","english":"Nor are you worshippers of what I worship"},{"number":4,"arabic":"وَلَآ أَنَا۠ عَابِدٞ مَّا عَبَدتُّمۡ","transliteration":"Wala ana AAabidun ma AAabadtum","english":"Nor will I be a worshipper of what you worship"},{"number":5,"arabic":"وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ","transliteration":"Wala antum AAabidoona ma aAAbudu","english":"Nor will you be worshippers of what I worship"},{"number":6,"arabic":"لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ","transliteration":"Lakum deenukum waliya deeni","english":"For you is your religion, and for me is my religion"}]},{"number":108,"name":"Al-Kawthar","arabicName":"الكوثر","meaning":"The Abundance","minutes":0.2,"ayahs":[{"number":1,"arabic":"إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ","transliteration":"Inna aAAtaynaka alkawthara","english":"Indeed, We have granted you, [O Muhammad], al-Kawthar"},{"number":2,"arabic":"فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ","transliteration":"Fasalli lirabbika wainhar","english":"So pray to your Lord and sacrifice [to Him alone]"},{"number":3,"arabic":"إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ","transliteration":"Inna shaniaka huwa alabtaru","english":"Indeed, your enemy is the one cut off"}]},{"number":107,"name":"Al-Ma'un","arabicName":"الماعون","meaning":"The Small kindnesses","minutes":0.6,"ayahs":[{"number":1,"arabic":"أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ","transliteration":"Araayta allathee yukaththibu bialddeeni","english":"Have you seen the one who denies the Recompense"},{"number":2,"arabic":"فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","transliteration":"Fathalika allathee yaduAAAAu alyateema","english":"For that is the one who drives away the orphan"},{"number":3,"arabic":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","transliteration":"Wala yahuddu AAala taAAami almiskeeni","english":"And does not encourage the feeding of the poor"},{"number":4,"arabic":"فَوَيۡلٞ لِّلۡمُصَلِّينَ","transliteration":"Fawaylun lilmusalleena","english":"So woe to those who pray"},{"number":5,"arabic":"ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ","transliteration":"Allatheena hum AAan salatihim sahoona","english":"[But] who are heedless of their prayer"},{"number":6,"arabic":"ٱلَّذِينَ هُمۡ يُرَآءُونَ","transliteration":"Allatheena hum yuraoona","english":"Those who make show [of their deeds]"},{"number":7,"arabic":"وَيَمۡنَعُونَ ٱلۡمَاعُونَ","transliteration":"WayamnaAAoona almaAAoona","english":"And withhold [simple] assistance"}]},{"number":106,"name":"Quraysh","arabicName":"قريش","meaning":"Quraysh","minutes":0.4,"ayahs":[{"number":1,"arabic":"لِإِيلَٰفِ قُرَيۡشٍ","transliteration":"Lieelafi qurayshin","english":"For the accustomed security of the Quraysh"},{"number":2,"arabic":"إِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ","transliteration":"Eelafihim rihlata alshshitai waalssayfi","english":"Their accustomed security [in] the caravan of winter and summer"},{"number":3,"arabic":"فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ","transliteration":"FalyaAAbudoo rabba hatha albayti","english":"Let them worship the Lord of this House"},{"number":4,"arabic":"ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ","transliteration":"Allathee atAAamahum min jooAAin waamanahum min khawfin","english":"Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear"}]},{"number":105,"name":"Al-Fil","arabicName":"الفيل","meaning":"The Elephant","minutes":0.5,"ayahs":[{"number":1,"arabic":"أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ","transliteration":"Alam tara kayfa faAAala rabbuka biashabi alfeeli","english":"Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant"},{"number":2,"arabic":"أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ","transliteration":"Alam yajAAal kaydahum fee tadleelin","english":"Did He not make their plan into misguidance"},{"number":3,"arabic":"وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ","transliteration":"Waarsala AAalayhim tayran ababeela","english":"And He sent against them birds in flocks"},{"number":4,"arabic":"تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ","transliteration":"Tarmeehim bihijaratin min sijjeelin","english":"Striking them with stones of hard clay"},{"number":5,"arabic":"فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ","transliteration":"FajaAAalahum kaAAasfin makoolin","english":"And He made them like eaten straw"}]},{"number":104,"name":"Al-Humazah","arabicName":"الهمزة","meaning":"The Traducer","minutes":0.7,"ayahs":[{"number":1,"arabic":"وَيۡلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ","transliteration":"Waylun likulli humazatin lumazatin","english":"Woe to every scorner and mocker"},{"number":2,"arabic":"ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ","transliteration":"Allathee jamaAAa malan waAAaddadahu","english":"Who collects wealth and [continuously] counts it"},{"number":3,"arabic":"يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ","transliteration":"Yahsabu anna malahu akhladahu","english":"He thinks that his wealth will make him immortal"},{"number":4,"arabic":"كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ","transliteration":"Kalla layunbathanna fee alhutamati","english":"No! He will surely be thrown into the Crusher"},{"number":5,"arabic":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ","transliteration":"Wama adraka ma alhutamatu","english":"And what can make you know what is the Crusher"},{"number":6,"arabic":"نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ","transliteration":"Naru Allahi almooqadatu","english":"It is the fire of Allah, [eternally] fueled"},{"number":7,"arabic":"ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ","transliteration":"Allatee tattaliAAu AAala alafidati","english":"Which mounts directed at the hearts"},{"number":8,"arabic":"إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةٞ","transliteration":"lnnaha AAalayhim musadatun","english":"Indeed, Hellfire will be closed down upon them"},{"number":9,"arabic":"فِي عَمَدٖ مُّمَدَّدَةِۭ","transliteration":"Fee AAamadin mumaddadatin","english":"In extended columns"}]},{"number":103,"name":"Al-'Asr","arabicName":"العصر","meaning":"The Declining Day","minutes":0.4,"ayahs":[{"number":1,"arabic":"وَٱلۡعَصۡرِ","transliteration":"WaalAAasri","english":"By time"},{"number":2,"arabic":"إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ","transliteration":"Inna alinsana lafee khusrin","english":"Indeed, mankind is in loss"},{"number":3,"arabic":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ","transliteration":"Illa allatheena amanoo waAAamiloo alssalihati watawasaw bialhaqqi watawasaw bialssabri","english":"Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience"}]},{"number":102,"name":"At-Takathur","arabicName":"التكاثر","meaning":"The Rivalry in world increase","minutes":0.7,"ayahs":[{"number":1,"arabic":"أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ","transliteration":"Alhakumu alttakathuru","english":"Competition in [worldly] increase diverts you"},{"number":2,"arabic":"حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ","transliteration":"Hatta zurtumu almaqabira","english":"Until you visit the graveyards"},{"number":3,"arabic":"كَلَّا سَوۡفَ تَعۡلَمُونَ","transliteration":"Kalla sawfa taAAlamoona","english":"No! You are going to know"},{"number":4,"arabic":"ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ","transliteration":"Thumma kalla sawfa taAAlamoona","english":"Then no! You are going to know"},{"number":5,"arabic":"كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ","transliteration":"Kalla law taAAlamoona AAilma alyaqeeni","english":"No! If you only knew with knowledge of certainty"},{"number":6,"arabic":"لَتَرَوُنَّ ٱلۡجَحِيمَ","transliteration":"Latarawunna aljaheema","english":"You will surely see the Hellfire"},{"number":7,"arabic":"ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ","transliteration":"Thumma latarawunnaha AAayna alyaqeeni","english":"Then you will surely see it with the eye of certainty"},{"number":8,"arabic":"ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ","transliteration":"Thumma latusalunna yawmaithin AAani alnnaAAeemi","english":"Then you will surely be asked that Day about pleasure"}]},{"number":101,"name":"Al-Qari'ah","arabicName":"القارعة","meaning":"The Calamity","minutes":0.8,"ayahs":[{"number":1,"arabic":"ٱلۡقَارِعَةُ","transliteration":"AlqariAAatu","english":"The Striking Calamity"},{"number":2,"arabic":"مَا ٱلۡقَارِعَةُ","transliteration":"Ma alqariAAatu","english":"What is the Striking Calamity"},{"number":3,"arabic":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ","transliteration":"Wama adraka ma alqariAAatu","english":"And what can make you know what is the Striking Calamity"},{"number":4,"arabic":"يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ","transliteration":"Yawma yakoonu alnnasu kaalfarashi almabthoothi","english":"It is the Day when people will be like moths, dispersed"},{"number":5,"arabic":"وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ","transliteration":"Watakoonu aljibalu kaalAAihni almanfooshi","english":"And the mountains will be like wool, fluffed up"},{"number":6,"arabic":"فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ","transliteration":"Faamma man thaqulat mawazeenuhu","english":"Then as for one whose scales are heavy [with good deeds]"},{"number":7,"arabic":"فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ","transliteration":"Fahuwa fee AAeeshatin radiyatin","english":"He will be in a pleasant life"},{"number":8,"arabic":"وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ","transliteration":"Waamma man khaffat mawazeenuhu","english":"But as for one whose scales are light"},{"number":9,"arabic":"فَأُمُّهُۥ هَاوِيَةٞ","transliteration":"Faommuhu hawiyatun","english":"His refuge will be an abyss"},{"number":10,"arabic":"وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ","transliteration":"Wama adraka ma hiyah","english":"And what can make you know what that is"},{"number":11,"arabic":"نَارٌ حَامِيَةُۢ","transliteration":"Narun hamiyatun","english":"It is a Fire, intensely hot"}]},{"number":100,"name":"Al-'Adiyat","arabicName":"العاديات","meaning":"The Courser","minutes":0.9,"ayahs":[{"number":1,"arabic":"وَٱلۡعَٰدِيَٰتِ ضَبۡحٗا","transliteration":"WaalAAadiyati dabhan","english":"By the racers, panting"},{"number":2,"arabic":"فَٱلۡمُورِيَٰتِ قَدۡحٗا","transliteration":"Faalmooriyati qadhan","english":"And the producers of sparks [when] striking"},{"number":3,"arabic":"فَٱلۡمُغِيرَٰتِ صُبۡحٗا","transliteration":"Faalmugheerati subhan","english":"And the chargers at dawn"},{"number":4,"arabic":"فَأَثَرۡنَ بِهِۦ نَقۡعٗا","transliteration":"Faatharna bihi naqAAan","english":"Stirring up thereby [clouds of] dust"},{"number":5,"arabic":"فَوَسَطۡنَ بِهِۦ جَمۡعًا","transliteration":"Fawasatna bihi jamAAan","english":"Arriving thereby in the center collectively"},{"number":6,"arabic":"إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ","transliteration":"Inna alinsana lirabbihi lakanoodun","english":"Indeed mankind, to his Lord, is ungrateful"},{"number":7,"arabic":"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٞ","transliteration":"Wainnahu AAala thalika lashaheedun","english":"And indeed, he is to that a witness"},{"number":8,"arabic":"وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ","transliteration":"Wainnahu lihubbi alkhayri lashadeedun","english":"And indeed he is, in love of wealth, intense"},{"number":9,"arabic":"۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ","transliteration":"Afala yaAAlamu itha buAAthira ma fee alquboori","english":"But does he not know that when the contents of the graves are scattered"},{"number":10,"arabic":"وَحُصِّلَ مَا فِي ٱلصُّدُورِ","transliteration":"Wahussila ma fee alssudoori","english":"And that within the breasts is obtained"},{"number":11,"arabic":"إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذٖ لَّخَبِيرُۢ","transliteration":"Inna rabbahum bihim yawmaithin lakhabeerun","english":"Indeed, their Lord with them, that Day, is [fully] Acquainted"}]},{"number":99,"name":"Az-Zalzalah","arabicName":"الزلزلة","meaning":"The Earthquake","minutes":0.8,"ayahs":[{"number":1,"arabic":"إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا","transliteration":"Itha zulzilati alardu zilzalaha","english":"When the earth is shaken with its [final] earthquake"},{"number":2,"arabic":"وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا","transliteration":"Waakhrajati alardu athqalaha","english":"And the earth discharges its burdens"},{"number":3,"arabic":"وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا","transliteration":"Waqala alinsanu ma laha","english":"And man says, \"What is [wrong] with it"},{"number":4,"arabic":"يَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا","transliteration":"Yawmaithin tuhaddithu akhbaraha","english":"That Day, it will report its news"},{"number":5,"arabic":"بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا","transliteration":"Bianna rabbaka awha laha","english":"Because your Lord has commanded it"},{"number":6,"arabic":"يَوۡمَئِذٖ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتٗا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ","transliteration":"Yawmaithin yasduru alnnasu ashtatan liyuraw aAAmalahum","english":"That Day, the people will depart separated [into categories] to be shown [the result of] their deeds"},{"number":7,"arabic":"فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ","transliteration":"Faman yaAAmal mithqala tharratin khayran yarahu","english":"So whoever does an atom's weight of good will see it"},{"number":8,"arabic":"وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ","transliteration":"Waman yaAAmal mithqala tharratin sharran yarahu","english":"And whoever does an atom's weight of evil will see it"}]},{"number":98,"name":"Al-Bayyinah","arabicName":"البينة","meaning":"The Clear Proof","minutes":2.1,"ayahs":[{"number":1,"arabic":"لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ","transliteration":"Lam yakuni allatheena kafaroo min ahli alkitabi waalmushrikeena munfakkeena hatta tatiyahumu albayyinatu","english":"Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence"},{"number":2,"arabic":"رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ","transliteration":"Rasoolun mina Allahi yatloo suhufan mutahharatan","english":"A Messenger from Allah, reciting purified scriptures"},{"number":3,"arabic":"فِيهَا كُتُبٞ قَيِّمَةٞ","transliteration":"Feeha kutubun qayyimatun","english":"Within which are correct writings"},{"number":4,"arabic":"وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ","transliteration":"Wama tafarraqa allatheena ootoo alkitaba illa min baAAdi ma jaathumu albayyinatu","english":"Nor did those who were given the Scripture become divided until after there had come to them clear evidence"},{"number":5,"arabic":"وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ","transliteration":"Wama omiroo illa liyaAAbudoo Allaha mukhliseena lahu alddeena hunafaa wayuqeemoo alssalata wayutoo alzzakata wathalika deenu alqayyimati","english":"And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion"},{"number":6,"arabic":"إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَـٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ","transliteration":"Inna allatheena kafaroo min ahli alkitabi waalmushrikeena fee nari jahannama khalideena feeha olaika hum sharru albariyyati","english":"Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures"},{"number":7,"arabic":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ","transliteration":"Inna allatheena amanoo waAAamiloo alssalihati olaika hum khayru albariyyati","english":"Indeed, they who have believed and done righteous deeds - those are the best of creatures"},{"number":8,"arabic":"جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ","transliteration":"Jazaohum AAinda rabbihim jannatu AAadnin tajree min tahtiha alanharu khalideena feeha abadan radiya Allahu AAanhum waradoo AAanhu thalika liman khashiya rabbahu","english":"Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord"}]},{"number":97,"name":"Al-Qadr","arabicName":"القدر","meaning":"The Power","minutes":0.6,"ayahs":[{"number":1,"arabic":"إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ","transliteration":"Inna anzalnahu fee laylati alqadri","english":"Indeed, We sent the Qur'an down during the Night of Decree"},{"number":2,"arabic":"وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ","transliteration":"Wama adraka ma laylatu alqadri","english":"And what can make you know what is the Night of Decree"},{"number":3,"arabic":"لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٞ مِّنۡ أَلۡفِ شَهۡرٖ","transliteration":"Laylatu alqadri khayrun min alfi shahrin","english":"The Night of Decree is better than a thousand months"},{"number":4,"arabic":"تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ","transliteration":"Tanazzalu almalaikatu waalrroohu feeha biithni rabbihim min kulli amrin","english":"The angels and the Spirit descend therein by permission of their Lord for every matter"},{"number":5,"arabic":"سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ","transliteration":"Salamun hiya hatta matlaAAi alfajri","english":"Peace it is until the emergence of dawn"}]},{"number":96,"name":"Al-'Alaq","arabicName":"العلق","meaning":"The Clot","minutes":1.5,"ayahs":[{"number":1,"arabic":"ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ","transliteration":"Iqra biismi rabbika allathee khalaqa","english":"Recite in the name of your Lord who created"},{"number":2,"arabic":"خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ","transliteration":"Khalaqa alinsana min AAalaqin","english":"Created man from a clinging substance"},{"number":3,"arabic":"ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ","transliteration":"Iqra warabbuka alakramu","english":"Recite, and your Lord is the most Generous"},{"number":4,"arabic":"ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ","transliteration":"Allathee AAallama bialqalami","english":"Who taught by the pen"},{"number":5,"arabic":"عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ","transliteration":"AAallama alinsana ma lam yaAAlam","english":"Taught man that which he knew not"},{"number":6,"arabic":"كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ","transliteration":"Kalla inna alinsana layatgha","english":"No! [But] indeed, man transgresses"},{"number":7,"arabic":"أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ","transliteration":"An raahu istaghna","english":"Because he sees himself self-sufficient"},{"number":8,"arabic":"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ","transliteration":"Inna ila rabbika alrrujAAa","english":"Indeed, to your Lord is the return"},{"number":9,"arabic":"أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ","transliteration":"Araayta allathee yanha","english":"Have you seen the one who forbids"},{"number":10,"arabic":"عَبۡدًا إِذَا صَلَّىٰٓ","transliteration":"AAabdan itha salla","english":"A servant when he prays"},{"number":11,"arabic":"أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ","transliteration":"Araayta in kana AAala alhuda","english":"Have you seen if he is upon guidance"},{"number":12,"arabic":"أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ","transliteration":"Aw amara bialttaqwa","english":"Or enjoins righteousness"},{"number":13,"arabic":"أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","transliteration":"Araayta in kaththaba watawalla","english":"Have you seen if he denies and turns away"},{"number":14,"arabic":"أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ","transliteration":"Alam yaAAlam bianna Allaha yara","english":"Does he not know that Allah sees"},{"number":15,"arabic":"كَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ","transliteration":"Kalla lain lam yantahi lanasfaAAan bialnnasiyati","english":"No! If he does not desist, We will surely drag him by the forelock"},{"number":16,"arabic":"نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ","transliteration":"Nasiyatin kathibatin khatiatin","english":"A lying, sinning forelock"},{"number":17,"arabic":"فَلۡيَدۡعُ نَادِيَهُۥ","transliteration":"FalyadAAu nadiyahu","english":"Then let him call his associates"},{"number":18,"arabic":"سَنَدۡعُ ٱلزَّبَانِيَةَ","transliteration":"SanadAAu alzzabaniyata","english":"We will call the angels of Hell"},{"number":19,"arabic":"كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩","transliteration":"Kalla la tutiAAhu waosjud waiqtarib","english":"No! Do not obey him. But prostrate and draw near [to Allah]"}]},{"number":95,"name":"At-Tin","arabicName":"التين","meaning":"The Fig","minutes":0.8,"ayahs":[{"number":1,"arabic":"وَٱلتِّينِ وَٱلزَّيۡتُونِ","transliteration":"Waaltteeni waalzzaytooni","english":"By the fig and the olive"},{"number":2,"arabic":"وَطُورِ سِينِينَ","transliteration":"Watoori seeneena","english":"And [by] Mount Sinai"},{"number":3,"arabic":"وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ","transliteration":"Wahatha albaladi alameeni","english":"And [by] this secure city [Makkah]"},{"number":4,"arabic":"لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ","transliteration":"Laqad khalaqna alinsana fee ahsani taqweemin","english":"We have certainly created man in the best of stature"},{"number":5,"arabic":"ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ","transliteration":"Thumma radadnahu asfala safileena","english":"Then We return him to the lowest of the low"},{"number":6,"arabic":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ","transliteration":"Illa allatheena amanoo waAAamiloo alssalihati falahum ajrun ghayru mamnoonin","english":"Except for those who believe and do righteous deeds, for they will have a reward uninterrupted"},{"number":7,"arabic":"فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ","transliteration":"Fama yukaththibuka baAAdu bialddeeni","english":"So what yet causes you to deny the Recompense"},{"number":8,"arabic":"أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ","transliteration":"Alaysa Allahu biahkami alhakimeena","english":"Is not Allah the most just of judges"}]},{"number":94,"name":"Ash-Sharh","arabicName":"الشرح","meaning":"The Relief","minutes":0.5,"ayahs":[{"number":1,"arabic":"أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ","transliteration":"Alam nashrah laka sadraka","english":"Did We not expand for you, [O Muhammad], your breast"},{"number":2,"arabic":"وَوَضَعۡنَا عَنكَ وِزۡرَكَ","transliteration":"WawadaAAna AAanka wizraka","english":"And We removed from you your burden"},{"number":3,"arabic":"ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ","transliteration":"Allathee anqada thahraka","english":"Which had weighed upon your back"},{"number":4,"arabic":"وَرَفَعۡنَا لَكَ ذِكۡرَكَ","transliteration":"WarafaAAna laka thikraka","english":"And raised high for you your repute"},{"number":5,"arabic":"فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا","transliteration":"Fainna maAAa alAAusri yusran","english":"For indeed, with hardship [will be] ease"},{"number":6,"arabic":"إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا","transliteration":"Inna maAAa alAAusri yusran","english":"Indeed, with hardship [will be] ease"},{"number":7,"arabic":"فَإِذَا فَرَغۡتَ فَٱنصَبۡ","transliteration":"Faitha faraghta fainsab","english":"So when you have finished [your duties], then stand up [for worship]"},{"number":8,"arabic":"وَإِلَىٰ رَبِّكَ فَٱرۡغَب","transliteration":"Waila rabbika fairghab","english":"And to your Lord direct [your] longing"}]},{"number":93,"name":"Ad-Duhaa","arabicName":"الضحى","meaning":"The Morning Hours","minutes":0.9,"ayahs":[{"number":1,"arabic":"وَٱلضُّحَىٰ","transliteration":"Waaldduha","english":"By the morning brightness"},{"number":2,"arabic":"وَٱلَّيۡلِ إِذَا سَجَىٰ","transliteration":"Waallayli itha saja","english":"And [by] the night when it covers with darkness"},{"number":3,"arabic":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","transliteration":"Ma waddaAAaka rabbuka wama qala","english":"Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you]"},{"number":4,"arabic":"وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ","transliteration":"Walalakhiratu khayrun laka mina aloola","english":"And the Hereafter is better for you than the first [life]"},{"number":5,"arabic":"وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ","transliteration":"Walasawfa yuAAteeka rabbuka fatarda","english":"And your Lord is going to give you, and you will be satisfied"},{"number":6,"arabic":"أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ","transliteration":"Alam yajidka yateeman faawa","english":"Did He not find you an orphan and give [you] refuge"},{"number":7,"arabic":"وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ","transliteration":"Wawajadaka dallan fahada","english":"And He found you lost and guided [you]"},{"number":8,"arabic":"وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ","transliteration":"Wawajadaka AAailan faaghna","english":"And He found you poor and made [you] self-sufficient"},{"number":9,"arabic":"فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ","transliteration":"Faamma alyateema fala taqhar","english":"So as for the orphan, do not oppress [him]"},{"number":10,"arabic":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ","transliteration":"Waamma alssaila fala tanhar","english":"And as for the petitioner, do not repel [him]"},{"number":11,"arabic":"وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ","transliteration":"Waamma biniAAmati rabbika fahaddith","english":"But as for the favor of your Lord, report [it]"}]},{"number":92,"name":"Al-Layl","arabicName":"الليل","meaning":"The Night","minutes":1.7,"ayahs":[{"number":1,"arabic":"وَٱلَّيۡلِ إِذَا يَغۡشَىٰ","transliteration":"Waallayli itha yaghsha","english":"By the night when it covers"},{"number":2,"arabic":"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","transliteration":"Waalnnahari itha tajalla","english":"And [by] the day when it appears"},{"number":3,"arabic":"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ","transliteration":"Wama khalaqa alththakara waalontha","english":"And [by] He who created the male and female"},{"number":4,"arabic":"إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ","transliteration":"Inna saAAyakum lashatta","english":"Indeed, your efforts are diverse"},{"number":5,"arabic":"فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ","transliteration":"Faamma man aAAta waittaqa","english":"As for he who gives and fears Allah"},{"number":6,"arabic":"وَصَدَّقَ بِٱلۡحُسۡنَىٰ","transliteration":"Wasaddaqa bialhusna","english":"And believes in the best [reward]"},{"number":7,"arabic":"فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ","transliteration":"Fasanuyassiruhu lilyusra","english":"We will ease him toward ease"},{"number":8,"arabic":"وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ","transliteration":"Waamma man bakhila waistaghna","english":"But as for he who withholds and considers himself free of need"},{"number":9,"arabic":"وَكَذَّبَ بِٱلۡحُسۡنَىٰ","transliteration":"Wakaththaba bialhusna","english":"And denies the best [reward]"},{"number":10,"arabic":"فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ","transliteration":"Fasanuyassiruhu lilAAusra","english":"We will ease him toward difficulty"},{"number":11,"arabic":"وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","transliteration":"Wama yughnee AAanhu maluhu itha taradda","english":"And what will his wealth avail him when he falls"},{"number":12,"arabic":"إِنَّ عَلَيۡنَا لَلۡهُدَىٰ","transliteration":"Inna AAalayna lalhuda","english":"Indeed, [incumbent] upon Us is guidance"},{"number":13,"arabic":"وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ","transliteration":"Wainna lana lalakhirata waaloola","english":"And indeed, to Us belongs the Hereafter and the first [life]"},{"number":14,"arabic":"فَأَنذَرۡتُكُمۡ نَارٗا تَلَظَّىٰ","transliteration":"Faanthartukum naran talaththa","english":"So I have warned you of a Fire which is blazing"},{"number":15,"arabic":"لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى","transliteration":"La yaslaha illa alashqa","english":"None will [enter to] burn therein except the most wretched one"},{"number":16,"arabic":"ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ","transliteration":"Allathee kaththaba watawalla","english":"Who had denied and turned away"},{"number":17,"arabic":"وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى","transliteration":"Wasayujannabuha alatqa","english":"But the righteous one will avoid it"},{"number":18,"arabic":"ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ","transliteration":"Allathee yutee malahu yatazakka","english":"[He] who gives [from] his wealth to purify himself"},{"number":19,"arabic":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ","transliteration":"Wama liahadin AAindahu min niAAmatin tujza","english":"And not [giving] for anyone who has [done him] a favor to be rewarded"},{"number":20,"arabic":"إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ","transliteration":"Illa ibtighaa wajhi rabbihi alaAAla","english":"But only seeking the countenance of his Lord, Most High"},{"number":21,"arabic":"وَلَسَوۡفَ يَرۡضَىٰ","transliteration":"Walasawfa yarda","english":"And he is going to be satisfied"}]},{"number":91,"name":"Ash-Shams","arabicName":"الشمس","meaning":"The Sun","minutes":1.3,"ayahs":[{"number":1,"arabic":"وَٱلشَّمۡسِ وَضُحَىٰهَا","transliteration":"Waalshshamsi waduhaha","english":"By the sun and its brightness"},{"number":2,"arabic":"وَٱلۡقَمَرِ إِذَا تَلَىٰهَا","transliteration":"Waalqamari itha talaha","english":"And [by] the moon when it follows it"},{"number":3,"arabic":"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","transliteration":"Waalnnahari itha jallaha","english":"And [by] the day when it displays it"},{"number":4,"arabic":"وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا","transliteration":"Waallayli itha yaghshaha","english":"And [by] the night when it covers it"},{"number":5,"arabic":"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","transliteration":"Waalssamai wama banaha","english":"And [by] the sky and He who constructed it"},{"number":6,"arabic":"وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا","transliteration":"Waalardi wama tahaha","english":"And [by] the earth and He who spread it"},{"number":7,"arabic":"وَنَفۡسٖ وَمَا سَوَّىٰهَا","transliteration":"Wanafsin wama sawwaha","english":"And [by] the soul and He who proportioned it"},{"number":8,"arabic":"فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا","transliteration":"Faalhamaha fujooraha wataqwaha","english":"And inspired it [with discernment of] its wickedness and its righteousness"},{"number":9,"arabic":"قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا","transliteration":"Qad aflaha man zakkaha","english":"He has succeeded who purifies it"},{"number":10,"arabic":"وَقَدۡ خَابَ مَن دَسَّىٰهَا","transliteration":"Waqad khaba man dassaha","english":"And he has failed who instills it [with corruption]"},{"number":11,"arabic":"كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ","transliteration":"Kaththabat thamoodu bitaghwaha","english":"Thamud denied [their prophet] by reason of their transgression"},{"number":12,"arabic":"إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا","transliteration":"Ithi inbaAAatha ashqaha","english":"When the most wretched of them was sent forth"},{"number":13,"arabic":"فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا","transliteration":"Faqala lahum rasoolu Allahi naqata Allahi wasuqyaha","english":"And the messenger of Allah [Salih] said to them, \"[Do not harm] the she-camel of Allah or [prevent her from] her drink"},{"number":14,"arabic":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا","transliteration":"Fakaththaboohu faAAaqarooha fadamdama AAalayhim rabbuhum bithanbihim fasawwaha","english":"But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them]"},{"number":15,"arabic":"وَلَا يَخَافُ عُقۡبَٰهَا","transliteration":"Wala yakhafu AAuqbaha","english":"And He does not fear the consequence thereof"}]},{"number":90,"name":"Al-Balad","arabicName":"البلد","meaning":"The City","minutes":1.8,"ayahs":[{"number":1,"arabic":"لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ","transliteration":"La oqsimu bihatha albaladi","english":"I swear by this city, Makkah"},{"number":2,"arabic":"وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ","transliteration":"Waanta hillun bihatha albaladi","english":"And you, [O Muhammad], are free of restriction in this city"},{"number":3,"arabic":"وَوَالِدٖ وَمَا وَلَدَ","transliteration":"Wawalidin wama walada","english":"And [by] the father and that which was born [of him]"},{"number":4,"arabic":"لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ","transliteration":"Laqad khalaqna alinsana fee kabadin","english":"We have certainly created man into hardship"},{"number":5,"arabic":"أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدٞ","transliteration":"Ayahsabu an lan yaqdira AAalayhi ahadun","english":"Does he think that never will anyone overcome him"},{"number":6,"arabic":"يَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا","transliteration":"Yaqoolu ahlaktu malan lubadan","english":"He says, \"I have spent wealth in abundance"},{"number":7,"arabic":"أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ","transliteration":"Ayahsabu an lam yarahu ahadun","english":"Does he think that no one has seen him"},{"number":8,"arabic":"أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ","transliteration":"Alam najAAal lahu AAaynayni","english":"Have We not made for him two eyes"},{"number":9,"arabic":"وَلِسَانٗا وَشَفَتَيۡنِ","transliteration":"Walisanan washafatayni","english":"And a tongue and two lips"},{"number":10,"arabic":"وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ","transliteration":"Wahadaynahu alnnajdayni","english":"And have shown him the two ways"},{"number":11,"arabic":"فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ","transliteration":"Fala iqtahama alAAaqabata","english":"But he has not broken through the difficult pass"},{"number":12,"arabic":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ","transliteration":"Wama adraka ma alAAaqabatu","english":"And what can make you know what is [breaking through] the difficult pass"},{"number":13,"arabic":"فَكُّ رَقَبَةٍ","transliteration":"Fakku raqabatin","english":"It is the freeing of a slave"},{"number":14,"arabic":"أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ","transliteration":"Aw itAAamun fee yawmin thee masghabatin","english":"Or feeding on a day of severe hunger"},{"number":15,"arabic":"يَتِيمٗا ذَا مَقۡرَبَةٍ","transliteration":"Yateeman tha maqrabatin","english":"An orphan of near relationship"},{"number":16,"arabic":"أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ","transliteration":"Aw miskeenan tha matrabatin","english":"Or a needy person in misery"},{"number":17,"arabic":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","transliteration":"Thumma kana mina allatheena amanoo watawasaw bialssabri watawasaw bialmarhamati","english":"And then being among those who believed and advised one another to patience and advised one another to compassion"},{"number":18,"arabic":"أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ","transliteration":"Olaika ashabu almaymanati","english":"Those are the companions of the right"},{"number":19,"arabic":"وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ","transliteration":"Waallatheena kafaroo biayatina hum ashabu almashamati","english":"But they who disbelieved in Our signs - those are the companions of the left"},{"number":20,"arabic":"عَلَيۡهِمۡ نَارٞ مُّؤۡصَدَةُۢ","transliteration":"AAalayhim narun musadatun","english":"Over them will be fire closed in"}]},{"number":89,"name":"Al-Fajr","arabicName":"الفجر","meaning":"The Dawn","minutes":3.1,"ayahs":[{"number":1,"arabic":"وَٱلۡفَجۡرِ","transliteration":"Waalfajri","english":"By the dawn"},{"number":2,"arabic":"وَلَيَالٍ عَشۡرٖ","transliteration":"Walayalin AAashrin","english":"And [by] ten nights"},{"number":3,"arabic":"وَٱلشَّفۡعِ وَٱلۡوَتۡرِ","transliteration":"WaalshshafAAi waalwatri","english":"And [by] the even [number] and the odd"},{"number":4,"arabic":"وَٱلَّيۡلِ إِذَا يَسۡرِ","transliteration":"Waallayli itha yasri","english":"And [by] the night when it passes"},{"number":5,"arabic":"هَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ","transliteration":"Hal fee thalika qasamun lithee hijrin","english":"Is there [not] in [all] that an oath [sufficient] for one of perception"},{"number":6,"arabic":"أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ","transliteration":"Alam tara kayfa faAAala rabbuka biAAadin","english":"Have you not considered how your Lord dealt with 'Aad"},{"number":7,"arabic":"إِرَمَ ذَاتِ ٱلۡعِمَادِ","transliteration":"Irama thati alAAimadi","english":"[With] Iram - who had lofty pillars"},{"number":8,"arabic":"ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ","transliteration":"Allatee lam yukhlaq mithluha fee albiladi","english":"The likes of whom had never been created in the land"},{"number":9,"arabic":"وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ","transliteration":"Wathamooda allatheena jaboo alssakhra bialwadi","english":"And [with] Thamud, who carved out the rocks in the valley"},{"number":10,"arabic":"وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ","transliteration":"WafirAAawna thee alawtadi","english":"And [with] Pharaoh, owner of the stakes"},{"number":11,"arabic":"ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ","transliteration":"Allatheena taghaw fee albiladi","english":"[All of] whom oppressed within the lands"},{"number":12,"arabic":"فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ","transliteration":"Faaktharoo feeha alfasada","english":"And increased therein the corruption"},{"number":13,"arabic":"فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ","transliteration":"Fasabba AAalayhim rabbuka sawta AAathabin","english":"So your Lord poured upon them a scourge of punishment"},{"number":14,"arabic":"إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ","transliteration":"Inna rabbaka labialmirsadi","english":"Indeed, your Lord is in observation"},{"number":15,"arabic":"فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ","transliteration":"Faamma alinsanu itha ma ibtalahu rabbuhu faakramahu wanaAAAAamahu fayaqoolu rabbee akramani","english":"And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, \"My Lord has honored me"},{"number":16,"arabic":"وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ","transliteration":"Waamma itha ma ibtalahu faqadara AAalayhi rizqahu fayaqoolu rabbee ahanani","english":"But when He tries him and restricts his provision, he says, \"My Lord has humiliated me"},{"number":17,"arabic":"كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","transliteration":"Kalla bal la tukrimoona alyateema","english":"No! But you do not honor the orphan"},{"number":18,"arabic":"وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","transliteration":"Wala tahaddoona AAala taAAami almiskeeni","english":"And you do not encourage one another to feed the poor"},{"number":19,"arabic":"وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا","transliteration":"Watakuloona altturatha aklan lamman","english":"And you consume inheritance, devouring [it] altogether"},{"number":20,"arabic":"وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا","transliteration":"Watuhibboona almala hubban jamman","english":"And you love wealth with immense love"},{"number":21,"arabic":"كَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا","transliteration":"Kalla itha dukkati alardu dakkan dakkan","english":"No! When the earth has been leveled - pounded and crushed"},{"number":22,"arabic":"وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا","transliteration":"Wajaa rabbuka waalmalaku saffan saffan","english":"And your Lord has come and the angels, rank upon rank"},{"number":23,"arabic":"وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ","transliteration":"Wajeea yawmaithin bijahannama yawmaithin yatathakkaru alinsanu waanna lahu alththikra","english":"And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance"},{"number":24,"arabic":"يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي","transliteration":"Yaqoolu ya laytanee qaddamtu lihayatee","english":"He will say, \"Oh, I wish I had sent ahead [some good] for my life"},{"number":25,"arabic":"فَيَوۡمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٞ","transliteration":"Fayawmaithin la yuAAaththibu AAathabahu ahadun","english":"So on that Day, none will punish [as severely] as His punishment"},{"number":26,"arabic":"وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٞ","transliteration":"Wala yoothiqu wathaqahu ahadun","english":"And none will bind [as severely] as His binding [of the evildoers]"},{"number":27,"arabic":"يَـٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ","transliteration":"Ya ayyatuha alnnafsu almutmainnatu","english":"[To the righteous it will be said], \"O reassured soul"},{"number":28,"arabic":"ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ","transliteration":"IrjiAAee ila rabbiki radiyatan mardiyyatan","english":"Return to your Lord, well-pleased and pleasing [to Him]"},{"number":29,"arabic":"فَٱدۡخُلِي فِي عِبَٰدِي","transliteration":"Faodkhulee fee AAibadee","english":"And enter among My [righteous] servants"},{"number":30,"arabic":"وَٱدۡخُلِي جَنَّتِي","transliteration":"Waodkhulee jannatee","english":"And enter My Paradise"}]},{"number":88,"name":"Al-Ghashiyah","arabicName":"الغاشية","meaning":"The Overwhelming","minutes":2.0,"ayahs":[{"number":1,"arabic":"هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ","transliteration":"Hal ataka hadeethu alghashiyati","english":"Has there reached you the report of the Overwhelming [event]"},{"number":2,"arabic":"وُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ","transliteration":"Wujoohun yawmaithin khashiAAatun","english":"[Some] faces, that Day, will be humbled"},{"number":3,"arabic":"عَامِلَةٞ نَّاصِبَةٞ","transliteration":"AAamilatun nasibatun","english":"Working [hard] and exhausted"},{"number":4,"arabic":"تَصۡلَىٰ نَارًا حَامِيَةٗ","transliteration":"Tasla naran hamiyatan","english":"They will [enter to] burn in an intensely hot Fire"},{"number":5,"arabic":"تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةٖ","transliteration":"Tusqa min AAaynin aniyatin","english":"They will be given drink from a boiling spring"},{"number":6,"arabic":"لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ","transliteration":"Laysa lahum taAAamun illa min dareeAAin","english":"For them there will be no food except from a poisonous, thorny plant"},{"number":7,"arabic":"لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ","transliteration":"La yusminu wala yughnee min jooAAin","english":"Which neither nourishes nor avails against hunger"},{"number":8,"arabic":"وُجُوهٞ يَوۡمَئِذٖ نَّاعِمَةٞ","transliteration":"Wujoohun yawmaithin naAAimatun","english":"[Other] faces, that Day, will show pleasure"},{"number":9,"arabic":"لِّسَعۡيِهَا رَاضِيَةٞ","transliteration":"LisaAAyiha radiyatun","english":"With their effort [they are] satisfied"},{"number":10,"arabic":"فِي جَنَّةٍ عَالِيَةٖ","transliteration":"Fee jannatin AAaliyatin","english":"In an elevated garden"},{"number":11,"arabic":"لَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ","transliteration":"La tasmaAAu feeha laghiyatan","english":"Wherein they will hear no unsuitable speech"},{"number":12,"arabic":"فِيهَا عَيۡنٞ جَارِيَةٞ","transliteration":"Feeha AAaynun jariyatun","english":"Within it is a flowing spring"},{"number":13,"arabic":"فِيهَا سُرُرٞ مَّرۡفُوعَةٞ","transliteration":"Feeha sururun marfooAAatun","english":"Within it are couches raised high"},{"number":14,"arabic":"وَأَكۡوَابٞ مَّوۡضُوعَةٞ","transliteration":"Waakwabun mawdooAAatun","english":"And cups put in place"},{"number":15,"arabic":"وَنَمَارِقُ مَصۡفُوفَةٞ","transliteration":"Wanamariqu masfoofatun","english":"And cushions lined up"},{"number":16,"arabic":"وَزَرَابِيُّ مَبۡثُوثَةٌ","transliteration":"Wazarabiyyu mabthoothatun","english":"And carpets spread around"},{"number":17,"arabic":"أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ","transliteration":"Afala yanthuroona ila alibili kayfa khuliqat","english":"Then do they not look at the camels - how they are created"},{"number":18,"arabic":"وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ","transliteration":"Waila alssamai kayfa rufiAAat","english":"And at the sky - how it is raised"},{"number":19,"arabic":"وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ","transliteration":"Waila aljibali kayfa nusibat","english":"And at the mountains - how they are erected"},{"number":20,"arabic":"وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ","transliteration":"Waila alardi kayfa sutihat","english":"And at the earth - how it is spread out"},{"number":21,"arabic":"فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرٞ","transliteration":"Fathakkir innama anta muthakkirun","english":"So remind, [O Muhammad]; you are only a reminder"},{"number":22,"arabic":"لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ","transliteration":"Lasta AAalayhim bimusaytirin","english":"You are not over them a controller"},{"number":23,"arabic":"إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","transliteration":"Illa man tawalla wakafara","english":"However, he who turns away and disbelieves"},{"number":24,"arabic":"فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ","transliteration":"FayuAAaththibuhu Allahu alAAathaba alakbara","english":"Then Allah will punish him with the greatest punishment"},{"number":25,"arabic":"إِنَّ إِلَيۡنَآ إِيَابَهُمۡ","transliteration":"Inna ilayna iyabahum","english":"Indeed, to Us is their return"},{"number":26,"arabic":"ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم","transliteration":"Thumma inna AAalayna hisabahum","english":"Then indeed, upon Us is their account"}]},{"number":87,"name":"Al-A'la","arabicName":"الأعلى","meaning":"The Most High","minutes":1.6,"ayahs":[{"number":1,"arabic":"سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى","transliteration":"Sabbihi isma rabbika alaAAla","english":"Exalt the name of your Lord, the Most High"},{"number":2,"arabic":"ٱلَّذِي خَلَقَ فَسَوَّىٰ","transliteration":"Allathee khalaqa fasawwa","english":"Who created and proportioned"},{"number":3,"arabic":"وَٱلَّذِي قَدَّرَ فَهَدَىٰ","transliteration":"Waallathee qaddara fahada","english":"And who destined and [then] guided"},{"number":4,"arabic":"وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ","transliteration":"Waallathee akhraja almarAAa","english":"And who brings out the pasture"},{"number":5,"arabic":"فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ","transliteration":"FajaAAalahu ghuthaan ahwa","english":"And [then] makes it black stubble"},{"number":6,"arabic":"سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ","transliteration":"Sanuqrioka fala tansa","english":"We will make you recite, [O Muhammad], and you will not forget"},{"number":7,"arabic":"إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ","transliteration":"Illa ma shaa Allahu innahu yaAAlamu aljahra wama yakhfa","english":"Except what Allah should will. Indeed, He knows what is declared and what is hidden"},{"number":8,"arabic":"وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ","transliteration":"Wanuyassiruka lilyusra","english":"And We will ease you toward ease"},{"number":9,"arabic":"فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ","transliteration":"Fathakkir in nafaAAati alththikra","english":"So remind, if the reminder should benefit"},{"number":10,"arabic":"سَيَذَّكَّرُ مَن يَخۡشَىٰ","transliteration":"Sayaththakkaru man yakhsha","english":"He who fears [Allah] will be reminded"},{"number":11,"arabic":"وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى","transliteration":"Wayatajannabuha alashqa","english":"But the wretched one will avoid it"},{"number":12,"arabic":"ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ","transliteration":"Allathee yasla alnnara alkubra","english":"[He] who will [enter and] burn in the greatest Fire"},{"number":13,"arabic":"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ","transliteration":"Thumma la yamootu feeha wala yahya","english":"Neither dying therein nor living"},{"number":14,"arabic":"قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ","transliteration":"Qad aflaha man tazakka","english":"He has certainly succeeded who purifies himself"},{"number":15,"arabic":"وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ","transliteration":"Wathakara isma rabbihi fasalla","english":"And mentions the name of his Lord and prays"},{"number":16,"arabic":"بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","transliteration":"Bal tuthiroona alhayata alddunya","english":"But you prefer the worldly life"},{"number":17,"arabic":"وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ","transliteration":"Waalakhiratu khayrun waabqa","english":"While the Hereafter is better and more enduring"},{"number":18,"arabic":"إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ","transliteration":"Inna hatha lafee alssuhufi aloola","english":"Indeed, this is in the former scriptures"},{"number":19,"arabic":"صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ","transliteration":"Suhufi ibraheema wamoosa","english":"The scriptures of Abraham and Moses"}]},{"number":86,"name":"At-Tariq","arabicName":"الطارق","meaning":"The Nightcommer","minutes":1.3,"ayahs":[{"number":1,"arabic":"وَٱلسَّمَآءِ وَٱلطَّارِقِ","transliteration":"Waalssamai waalttariqi","english":"By the sky and the night comer"},{"number":2,"arabic":"وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ","transliteration":"Wama adraka ma alttariqu","english":"And what can make you know what is the night comer"},{"number":3,"arabic":"ٱلنَّجۡمُ ٱلثَّاقِبُ","transliteration":"Alnnajmu alththaqibu","english":"It is the piercing star"},{"number":4,"arabic":"إِن كُلُّ نَفۡسٖ لَّمَّا عَلَيۡهَا حَافِظٞ","transliteration":"In kullu nafsin lamma AAalayha hafithun","english":"There is no soul but that it has over it a protector"},{"number":5,"arabic":"فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ","transliteration":"Falyanthuri alinsanu mimma khuliqa","english":"So let man observe from what he was created"},{"number":6,"arabic":"خُلِقَ مِن مَّآءٖ دَافِقٖ","transliteration":"Khuliqa min main dafiqin","english":"He was created from a fluid, ejected"},{"number":7,"arabic":"يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ","transliteration":"Yakhruju min bayni alssulbi waalttaraibi","english":"Emerging from between the backbone and the ribs"},{"number":8,"arabic":"إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرٞ","transliteration":"Innahu AAala rajAAihi laqadirun","english":"Indeed, Allah, to return him [to life], is Able"},{"number":9,"arabic":"يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ","transliteration":"Yawma tubla alssarairu","english":"The Day when secrets will be put on trial"},{"number":10,"arabic":"فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ","transliteration":"Fama lahu min quwwatin wala nasirin","english":"Then man will have no power or any helper"},{"number":11,"arabic":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ","transliteration":"Waalssamai thati alrrajAAi","english":"By the sky which returns [rain]"},{"number":12,"arabic":"وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ","transliteration":"Waalardi thati alssadAAi","english":"And [by] the earth which cracks open"},{"number":13,"arabic":"إِنَّهُۥ لَقَوۡلٞ فَصۡلٞ","transliteration":"Innahu laqawlun faslun","english":"Indeed, the Qur'an is a decisive statement"},{"number":14,"arabic":"وَمَا هُوَ بِٱلۡهَزۡلِ","transliteration":"Wama huwa bialhazli","english":"And it is not amusement"},{"number":15,"arabic":"إِنَّهُمۡ يَكِيدُونَ كَيۡدٗا","transliteration":"Innahum yakeedoona kaydan","english":"Indeed, they are planning a plan"},{"number":16,"arabic":"وَأَكِيدُ كَيۡدٗا","transliteration":"Waakeedu kaydan","english":"But I am planning a plan"},{"number":17,"arabic":"فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا","transliteration":"Famahhili alkafireena amhilhum ruwaydan","english":"So allow time for the disbelievers. Leave them awhile"}]},{"number":85,"name":"Al-Buruj","arabicName":"البروج","meaning":"The Mansions of the Stars","minutes":2.5,"ayahs":[{"number":1,"arabic":"وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ","transliteration":"Waalssamai thati alburooji","english":"By the sky containing great stars"},{"number":2,"arabic":"وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ","transliteration":"Waalyawmi almawAAoodi","english":"And [by] the promised Day"},{"number":3,"arabic":"وَشَاهِدٖ وَمَشۡهُودٖ","transliteration":"Washahidin wamashhoodin","english":"And [by] the witness and what is witnessed"},{"number":4,"arabic":"قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ","transliteration":"Qutila ashabu alukhdoodi","english":"Cursed were the companions of the trench"},{"number":5,"arabic":"ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ","transliteration":"Alnnari thati alwaqoodi","english":"[Containing] the fire full of fuel"},{"number":6,"arabic":"إِذۡ هُمۡ عَلَيۡهَا قُعُودٞ","transliteration":"Ith hum AAalayha quAAoodun","english":"When they were sitting near it"},{"number":7,"arabic":"وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٞ","transliteration":"Wahum AAala ma yafAAaloona bialmumineena shuhoodun","english":"And they, to what they were doing against the believers, were witnesses"},{"number":8,"arabic":"وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ","transliteration":"Wama naqamoo minhum illa an yuminoo biAllahi alAAazeezi alhameedi","english":"And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy"},{"number":9,"arabic":"ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","transliteration":"Allathee lahu mulku alssamawati waalardi waAllahu AAala kulli shayin shaheedun","english":"To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness"},{"number":10,"arabic":"إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ","transliteration":"Inna allatheena fatanoo almumineena waalmuminati thumma lam yatooboo falahum AAathabu jahannama walahum AAathabu alhareeqi","english":"Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire"},{"number":11,"arabic":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ","transliteration":"Inna allatheena amanoo waAAamiloo alssalihati lahum jannatun tajree min tahtiha alanharu thalika alfawzu alkabeeru","english":"Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment"},{"number":12,"arabic":"إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ","transliteration":"Inna batsha rabbika lashadeedun","english":"Indeed, the vengeance of your Lord is severe"},{"number":13,"arabic":"إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ","transliteration":"Innahu huwa yubdio wayuAAeedu","english":"Indeed, it is He who originates [creation] and repeats"},{"number":14,"arabic":"وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ","transliteration":"Wahuwa alghafooru alwadoodu","english":"And He is the Forgiving, the Affectionate"},{"number":15,"arabic":"ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ","transliteration":"Thoo alAAarshi almajeedi","english":"Honorable Owner of the Throne"},{"number":16,"arabic":"فَعَّالٞ لِّمَا يُرِيدُ","transliteration":"FaAAAAalun lima yureedu","english":"Effecter of what He intends"},{"number":17,"arabic":"هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ","transliteration":"Hal ataka hadeethu aljunoodi","english":"Has there reached you the story of the soldiers"},{"number":18,"arabic":"فِرۡعَوۡنَ وَثَمُودَ","transliteration":"FirAAawna wathamooda","english":"[Those of] Pharaoh and Thamud"},{"number":19,"arabic":"بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ","transliteration":"Bali allatheena kafaroo fee taktheebin","english":"But they who disbelieve are in [persistent] denial"},{"number":20,"arabic":"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ","transliteration":"WaAllahu min waraihim muheetun","english":"While Allah encompasses them from behind"},{"number":21,"arabic":"بَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ","transliteration":"Bal huwa quranun majeedun","english":"But this is an honored Qur'an"},{"number":22,"arabic":"فِي لَوۡحٖ مَّحۡفُوظِۭ","transliteration":"Fee lawhin mahfoothin","english":"[Inscribed] in a Preserved Slate"}]},{"number":84,"name":"Al-Inshiqaq","arabicName":"الإنشقاق","meaning":"The Sundering","minutes":2.3,"ayahs":[{"number":1,"arabic":"إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ","transliteration":"Itha alssamao inshaqqat","english":"When the sky has split [open]"},{"number":2,"arabic":"وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ","transliteration":"Waathinat lirabbiha wahuqqat","english":"And has responded to its Lord and was obligated [to do so]"},{"number":3,"arabic":"وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ","transliteration":"Waitha alardu muddat","english":"And when the earth has been extended"},{"number":4,"arabic":"وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ","transliteration":"Waalqat ma feeha watakhallat","english":"And has cast out that within it and relinquished [it]"},{"number":5,"arabic":"وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ","transliteration":"Waathinat lirabbiha wahuqqat","english":"And has responded to its Lord and was obligated [to do so]"},{"number":6,"arabic":"يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ","transliteration":"Ya ayyuha alinsanu innaka kadihun ila rabbika kadhan famulaqeehi","english":"O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it"},{"number":7,"arabic":"فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ","transliteration":"Faama man ootiya kitabahu biyameenihi","english":"Then as for he who is given his record in his right hand"},{"number":8,"arabic":"فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا","transliteration":"Fasawfa yuhasabu hisaban yaseeran","english":"He will be judged with an easy account"},{"number":9,"arabic":"وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا","transliteration":"Wayanqalibu ila ahlihi masrooran","english":"And return to his people in happiness"},{"number":10,"arabic":"وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ","transliteration":"Waamma man ootiya kitabahu waraa thahrihi","english":"But as for he who is given his record behind his back"},{"number":11,"arabic":"فَسَوۡفَ يَدۡعُواْ ثُبُورٗا","transliteration":"Fasawfa yadAAoo thubooran","english":"He will cry out for destruction"},{"number":12,"arabic":"وَيَصۡلَىٰ سَعِيرًا","transliteration":"Wayasla saAAeeran","english":"And [enter to] burn in a Blaze"},{"number":13,"arabic":"إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا","transliteration":"Innahu kana fee ahlihi masrooran","english":"Indeed, he had [once] been among his people in happiness"},{"number":14,"arabic":"إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","transliteration":"Innahu thanna an lan yahoora","english":"Indeed, he had thought he would never return [to Allah]"},{"number":15,"arabic":"بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا","transliteration":"Bala inna rabbahu kana bihi baseeran","english":"But yes! Indeed, his Lord was ever of him, Seeing"},{"number":16,"arabic":"فَلَآ أُقۡسِمُ بِٱلشَّفَقِ","transliteration":"Fala oqsimu bialshshafaqi","english":"So I swear by the twilight glow"},{"number":17,"arabic":"وَٱلَّيۡلِ وَمَا وَسَقَ","transliteration":"Waallayli wama wasaqa","english":"And [by] the night and what it envelops"},{"number":18,"arabic":"وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ","transliteration":"Waalqamari itha ittasaqa","english":"And [by] the moon when it becomes full"},{"number":19,"arabic":"لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقٖ","transliteration":"Latarkabunna tabaqan AAan tabaqin","english":"[That] you will surely experience state after state"},{"number":20,"arabic":"فَمَا لَهُمۡ لَا يُؤۡمِنُونَ","transliteration":"Fama lahum la yuminoona","english":"So what is [the matter] with them [that] they do not believe"},{"number":21,"arabic":"وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩","transliteration":"Waitha quria AAalayhimu alquranu la yasjudoona","english":"And when the Qur'an is recited to them, they do not prostrate [to Allah]"},{"number":22,"arabic":"بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ","transliteration":"Bali allatheena kafaroo yukaththiboona","english":"But those who have disbelieved deny"},{"number":23,"arabic":"وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ","transliteration":"WaAllahu aAAlamu bima yooAAoona","english":"And Allah is most knowing of what they keep within themselves"},{"number":24,"arabic":"فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ","transliteration":"Fabashshirhum biAAathabin aleemin","english":"So give them tidings of a painful punishment"},{"number":25,"arabic":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ","transliteration":"Illa allatheena amanoo waAAamiloo alssalihati lahum ajrun ghayru mamnoonin","english":"Except for those who believe and do righteous deeds. For them is a reward uninterrupted"}]},{"number":83,"name":"Al-Mutaffifin","arabicName":"المطففين","meaning":"The Defrauding","minutes":3.9,"ayahs":[{"number":1,"arabic":"وَيۡلٞ لِّلۡمُطَفِّفِينَ","transliteration":"Waylun lilmutaffifeena","english":"Woe to those who give less [than due]"},{"number":2,"arabic":"ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ","transliteration":"Allatheena itha iktaloo AAala alnnasi yastawfoona","english":"Who, when they take a measure from people, take in full"},{"number":3,"arabic":"وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ","transliteration":"Waitha kaloohum aw wazanoohum yukhsiroona","english":"But if they give by measure or by weight to them, they cause loss"},{"number":4,"arabic":"أَلَا يَظُنُّ أُوْلَـٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ","transliteration":"Ala yathunnu olaika annahum mabAAoothoona","english":"Do they not think that they will be resurrected"},{"number":5,"arabic":"لِيَوۡمٍ عَظِيمٖ","transliteration":"Liyawmin AAatheemin","english":"For a tremendous Day"},{"number":6,"arabic":"يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ","transliteration":"Yawma yaqoomu alnnasu lirabbi alAAalameena","english":"The Day when mankind will stand before the Lord of the worlds"},{"number":7,"arabic":"كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينٖ","transliteration":"Kalla inna kitaba alfujjari lafee sijjeenin","english":"No! Indeed, the record of the wicked is in sijjeen"},{"number":8,"arabic":"وَمَآ أَدۡرَىٰكَ مَا سِجِّينٞ","transliteration":"Wama adraka ma sijjeenun","english":"And what can make you know what is sijjeen"},{"number":9,"arabic":"كِتَٰبٞ مَّرۡقُومٞ","transliteration":"Kitabun marqoomun","english":"It is [their destination recorded in] a register inscribed"},{"number":10,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":11,"arabic":"ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ","transliteration":"Allatheena yukaththiboona biyawmi alddeeni","english":"Who deny the Day of Recompense"},{"number":12,"arabic":"وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ","transliteration":"Wama yukaththibu bihi illa kullu muAAtadin atheemin","english":"And none deny it except every sinful transgressor"},{"number":13,"arabic":"إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","transliteration":"Itha tutla AAalayhi ayatuna qala asateeru alawwaleena","english":"When Our verses are recited to him, he says, \"Legends of the former peoples"},{"number":14,"arabic":"كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ","transliteration":"Kalla bal rana AAala quloobihim ma kanoo yaksiboona","english":"No! Rather, the stain has covered their hearts of that which they were earning"},{"number":15,"arabic":"كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ","transliteration":"Kalla innahum AAan rabbihim yawmaithin lamahjooboona","english":"No! Indeed, from their Lord, that Day, they will be partitioned"},{"number":16,"arabic":"ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ","transliteration":"Thumma innahum lasaloo aljaheemi","english":"Then indeed, they will [enter and] burn in Hellfire"},{"number":17,"arabic":"ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ","transliteration":"Thumma yuqalu hatha allathee kuntum bihi tukaththiboona","english":"Then it will be said [to them], \"This is what you used to deny"},{"number":18,"arabic":"كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ","transliteration":"Kalla inna kitaba alabrari lafee AAilliyyeena","english":"No! Indeed, the record of the righteous is in 'illiyyun"},{"number":19,"arabic":"وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ","transliteration":"Wama adraka ma AAilliyyoona","english":"And what can make you know what is 'illiyyun"},{"number":20,"arabic":"كِتَٰبٞ مَّرۡقُومٞ","transliteration":"Kitabun marqoomun","english":"It is [their destination recorded in] a register inscribed"},{"number":21,"arabic":"يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ","transliteration":"Yashhaduhu almuqarraboona","english":"Which is witnessed by those brought near [to Allah]"},{"number":22,"arabic":"إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ","transliteration":"Inna alabrara lafee naAAeemin","english":"Indeed, the righteous will be in pleasure"},{"number":23,"arabic":"عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","transliteration":"AAala alaraiki yanthuroona","english":"On adorned couches, observing"},{"number":24,"arabic":"تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ","transliteration":"TaAArifu fee wujoohihim nadrata alnnaAAeemi","english":"You will recognize in their faces the radiance of pleasure"},{"number":25,"arabic":"يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ","transliteration":"Yusqawna min raheeqin makhtoomin","english":"They will be given to drink [pure] wine [which was] sealed"},{"number":26,"arabic":"خِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ","transliteration":"Khitamuhu miskun wafee thalika falyatanafasi almutanafisoona","english":"The last of it is musk. So for this let the competitors compete"},{"number":27,"arabic":"وَمِزَاجُهُۥ مِن تَسۡنِيمٍ","transliteration":"Wamizajuhu min tasneemin","english":"And its mixture is of Tasneem"},{"number":28,"arabic":"عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ","transliteration":"AAaynan yashrabu biha almuqarraboona","english":"A spring from which those near [to Allah] drink"},{"number":29,"arabic":"إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ","transliteration":"Inna allatheena ajramoo kanoo mina allatheena amanoo yadhakoona","english":"Indeed, those who committed crimes used to laugh at those who believed"},{"number":30,"arabic":"وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ","transliteration":"Waitha marroo bihim yataghamazoona","english":"And when they passed by them, they would exchange derisive glances"},{"number":31,"arabic":"وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ","transliteration":"Waitha inqalaboo ila ahlihimu inqalaboo fakiheena","english":"And when they returned to their people, they would return jesting"},{"number":32,"arabic":"وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ","transliteration":"Waitha raawhum qaloo inna haolai ladalloona","english":"And when they saw them, they would say, \"Indeed, those are truly lost"},{"number":33,"arabic":"وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ","transliteration":"Wama orsiloo AAalayhim hafitheena","english":"But they had not been sent as guardians over them"},{"number":34,"arabic":"فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ","transliteration":"Faalyawma allatheena amanoo mina alkuffari yadhakoona","english":"So Today those who believed are laughing at the disbelievers"},{"number":35,"arabic":"عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ","transliteration":"AAala alaraiki yanthuroona","english":"On adorned couches, observing"},{"number":36,"arabic":"هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ","transliteration":"Hal thuwwiba alkuffaru ma kanoo yafAAaloona","english":"Have the disbelievers [not] been rewarded [this Day] for what they used to do"}]},{"number":82,"name":"Al-Infitar","arabicName":"الإنفطار","meaning":"The Cleaving","minutes":1.7,"ayahs":[{"number":1,"arabic":"إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ","transliteration":"Itha alssamao infatarat","english":"When the sky breaks apart"},{"number":2,"arabic":"وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ","transliteration":"Waitha alkawakibu intatharat","english":"And when the stars fall, scattering"},{"number":3,"arabic":"وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ","transliteration":"Waitha albiharu fujjirat","english":"And when the seas are erupted"},{"number":4,"arabic":"وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ","transliteration":"Waitha alqubooru buAAthirat","english":"And when the [contents of] graves are scattered"},{"number":5,"arabic":"عَلِمَتۡ نَفۡسٞ مَّا قَدَّمَتۡ وَأَخَّرَتۡ","transliteration":"AAalimat nafsun ma qaddamat waakhkharat","english":"A soul will [then] know what it has put forth and kept back"},{"number":6,"arabic":"يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ","transliteration":"Ya ayyuha alinsanu ma gharraka birabbika alkareemi","english":"O mankind, what has deceived you concerning your Lord, the Generous"},{"number":7,"arabic":"ٱلَّذِي خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","transliteration":"Allathee khalaqaka fasawwaka faAAadalaka","english":"Who created you, proportioned you, and balanced you"},{"number":8,"arabic":"فِيٓ أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَ","transliteration":"Fee ayyi sooratin ma shaa rakkabaka","english":"In whatever form He willed has He assembled you"},{"number":9,"arabic":"كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ","transliteration":"Kalla bal tukaththiboona bialddeeni","english":"No! But you deny the Recompense"},{"number":10,"arabic":"وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ","transliteration":"Wainna AAalaykum lahafitheena","english":"And indeed, [appointed] over you are keepers"},{"number":11,"arabic":"كِرَامٗا كَٰتِبِينَ","transliteration":"Kiraman katibeena","english":"Noble and recording"},{"number":12,"arabic":"يَعۡلَمُونَ مَا تَفۡعَلُونَ","transliteration":"YaAAlamoona ma tafAAaloona","english":"They know whatever you do"},{"number":13,"arabic":"إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ","transliteration":"Inna alabrara lafee naAAeemin","english":"Indeed, the righteous will be in pleasure"},{"number":14,"arabic":"وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ","transliteration":"Wainna alfujjara lafee jaheemin","english":"And indeed, the wicked will be in Hellfire"},{"number":15,"arabic":"يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ","transliteration":"Yaslawnaha yawma alddeeni","english":"They will [enter to] burn therein on the Day of Recompense"},{"number":16,"arabic":"وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ","transliteration":"Wama hum AAanha bighaibeena","english":"And never therefrom will they be absent"},{"number":17,"arabic":"وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ","transliteration":"Wama adraka ma yawmu alddeeni","english":"And what can make you know what is the Day of Recompense"},{"number":18,"arabic":"ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ","transliteration":"Thumma ma adraka ma yawmu alddeeni","english":"Then, what can make you know what is the Day of Recompense"},{"number":19,"arabic":"يَوۡمَ لَا تَمۡلِكُ نَفۡسٞ لِّنَفۡسٖ شَيۡـٔٗاۖ وَٱلۡأَمۡرُ يَوۡمَئِذٖ لِّلَّهِ","transliteration":"Yawma la tamliku nafsun linafsin shayan waalamru yawmaithin lillahi","english":"It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah"}]},{"number":81,"name":"At-Takwir","arabicName":"التكوير","meaning":"The Overthrowing","minutes":2.3,"ayahs":[{"number":1,"arabic":"إِذَا ٱلشَّمۡسُ كُوِّرَتۡ","transliteration":"Itha alshshamsu kuwwirat","english":"When the sun is wrapped up [in darkness]"},{"number":2,"arabic":"وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ","transliteration":"Waitha alnnujoomu inkadarat","english":"And when the stars fall, dispersing"},{"number":3,"arabic":"وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ","transliteration":"Waitha aljibalu suyyirat","english":"And when the mountains are removed"},{"number":4,"arabic":"وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ","transliteration":"Waitha alAAisharu AAuttilat","english":"And when full-term she-camels are neglected"},{"number":5,"arabic":"وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ","transliteration":"Waitha alwuhooshu hushirat","english":"And when the wild beasts are gathered"},{"number":6,"arabic":"وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ","transliteration":"Waitha albiharu sujjirat","english":"And when the seas are filled with flame"},{"number":7,"arabic":"وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ","transliteration":"Waitha alnnufoosu zuwwijat","english":"And when the souls are paired"},{"number":8,"arabic":"وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ","transliteration":"Waitha almawoodatu suilat","english":"And when the girl [who was] buried alive is asked"},{"number":9,"arabic":"بِأَيِّ ذَنۢبٖ قُتِلَتۡ","transliteration":"Biayyi thanbin qutilat","english":"For what sin she was killed"},{"number":10,"arabic":"وَإِذَا ٱلصُّحُفُ نُشِرَتۡ","transliteration":"Waitha alssuhufu nushirat","english":"And when the pages are made public"},{"number":11,"arabic":"وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ","transliteration":"Waitha alssamao kushitat","english":"And when the sky is stripped away"},{"number":12,"arabic":"وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ","transliteration":"Waitha aljaheemu suAAAAirat","english":"And when Hellfire is set ablaze"},{"number":13,"arabic":"وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ","transliteration":"Waitha aljannatu ozlifat","english":"And when Paradise is brought near"},{"number":14,"arabic":"عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ","transliteration":"AAalimat nafsun ma ahdarat","english":"A soul will [then] know what it has brought [with it]"},{"number":15,"arabic":"فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ","transliteration":"Fala oqsimu bialkhunnasi","english":"So I swear by the retreating stars"},{"number":16,"arabic":"ٱلۡجَوَارِ ٱلۡكُنَّسِ","transliteration":"Aljawari alkunnasi","english":"Those that run [their courses] and disappear"},{"number":17,"arabic":"وَٱلَّيۡلِ إِذَا عَسۡعَسَ","transliteration":"Waallayli itha AAasAAasa","english":"And by the night as it closes in"},{"number":18,"arabic":"وَٱلصُّبۡحِ إِذَا تَنَفَّسَ","transliteration":"Waalssubhi itha tanaffasa","english":"And by the dawn when it breathes"},{"number":19,"arabic":"إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ","transliteration":"Innahu laqawlu rasoolin kareemin","english":"[That] indeed, the Qur'an is a word [conveyed by] a noble messenger"},{"number":20,"arabic":"ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ","transliteration":"Thee quwwatin AAinda thee alAAarshi makeenin","english":"[Who is] possessed of power and with the Owner of the Throne, secure [in position]"},{"number":21,"arabic":"مُّطَاعٖ ثَمَّ أَمِينٖ","transliteration":"MutaAAin thamma ameenin","english":"Obeyed there [in the heavens] and trustworthy"},{"number":22,"arabic":"وَمَا صَاحِبُكُم بِمَجۡنُونٖ","transliteration":"Wama sahibukum bimajnoonin","english":"And your companion is not [at all] mad"},{"number":23,"arabic":"وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ","transliteration":"Walaqad raahu bialofuqi almubeeni","english":"And he has already seen Gabriel in the clear horizon"},{"number":24,"arabic":"وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينٖ","transliteration":"Wama huwa AAala alghaybi bidaneenin","english":"And Muhammad is not a withholder of [knowledge of] the unseen"},{"number":25,"arabic":"وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ","transliteration":"Wama huwa biqawli shaytanin rajeemin","english":"And the Qur'an is not the word of a devil, expelled [from the heavens]"},{"number":26,"arabic":"فَأَيۡنَ تَذۡهَبُونَ","transliteration":"Faayna tathhaboona","english":"So where are you going"},{"number":27,"arabic":"إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ","transliteration":"In huwa illa thikrun lilAAalameena","english":"It is not except a reminder to the worlds"},{"number":28,"arabic":"لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ","transliteration":"Liman shaa minkum an yastaqeema","english":"For whoever wills among you to take a right course"},{"number":29,"arabic":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ","transliteration":"Wama tashaoona illa an yashaa Allahu rabbu alAAalameena","english":"And you do not will except that Allah wills - Lord of the worlds"}]},{"number":80,"name":"'Abasa","arabicName":"عبس","meaning":"He Frowned","minutes":2.9,"ayahs":[{"number":1,"arabic":"عَبَسَ وَتَوَلَّىٰٓ","transliteration":"AAabasa watawalla","english":"The Prophet frowned and turned away"},{"number":2,"arabic":"أَن جَآءَهُ ٱلۡأَعۡمَىٰ","transliteration":"An jaahu alaAAma","english":"Because there came to him the blind man, [interrupting]"},{"number":3,"arabic":"وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","transliteration":"Wama yudreeka laAAallahu yazzakka","english":"But what would make you perceive, [O Muhammad], that perhaps he might be purified"},{"number":4,"arabic":"أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ","transliteration":"Aw yaththakkaru fatanfaAAahu alththikra","english":"Or be reminded and the remembrance would benefit him"},{"number":5,"arabic":"أَمَّا مَنِ ٱسۡتَغۡنَىٰ","transliteration":"Amma mani istaghna","english":"As for he who thinks himself without need"},{"number":6,"arabic":"فَأَنتَ لَهُۥ تَصَدَّىٰ","transliteration":"Faanta lahu tasadda","english":"To him you give attention"},{"number":7,"arabic":"وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ","transliteration":"Wama AAalayka alla yazzakka","english":"And not upon you [is any blame] if he will not be purified"},{"number":8,"arabic":"وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ","transliteration":"Waamma man jaaka yasAAa","english":"But as for he who came to you striving [for knowledge]"},{"number":9,"arabic":"وَهُوَ يَخۡشَىٰ","transliteration":"Wahuwa yakhsha","english":"While he fears [Allah]"},{"number":10,"arabic":"فَأَنتَ عَنۡهُ تَلَهَّىٰ","transliteration":"Faanta AAanhu talahha","english":"From him you are distracted"},{"number":11,"arabic":"كَلَّآ إِنَّهَا تَذۡكِرَةٞ","transliteration":"Kalla innaha tathkiratun","english":"No! Indeed, these verses are a reminder"},{"number":12,"arabic":"فَمَن شَآءَ ذَكَرَهُۥ","transliteration":"Faman shaa thakarahu","english":"So whoever wills may remember it"},{"number":13,"arabic":"فِي صُحُفٖ مُّكَرَّمَةٖ","transliteration":"Fee suhufin mukarramatin","english":"[It is recorded] in honored sheets"},{"number":14,"arabic":"مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ","transliteration":"MarfooAAatin mutahharatin","english":"Exalted and purified"},{"number":15,"arabic":"بِأَيۡدِي سَفَرَةٖ","transliteration":"Biaydee safaratin","english":"[Carried] by the hands of messenger-angels"},{"number":16,"arabic":"كِرَامِۭ بَرَرَةٖ","transliteration":"Kiramin bararatin","english":"Noble and dutiful"},{"number":17,"arabic":"قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ","transliteration":"Qutila alinsanu ma akfarahu","english":"Cursed is man; how disbelieving is he"},{"number":18,"arabic":"مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ","transliteration":"Min ayyi shayin khalaqahu","english":"From what substance did He create him"},{"number":19,"arabic":"مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","transliteration":"Min nutfatin khalaqahu faqaddarahu","english":"From a sperm-drop He created him and destined for him"},{"number":20,"arabic":"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","transliteration":"Thumma alssabeela yassarahu","english":"Then He eased the way for him"},{"number":21,"arabic":"ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ","transliteration":"Thumma amatahu faaqbarahu","english":"Then He causes his death and provides a grave for him"},{"number":22,"arabic":"ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","transliteration":"Thumma itha shaa ansharahu","english":"Then when He wills, He will resurrect him"},{"number":23,"arabic":"كَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ","transliteration":"Kalla lamma yaqdi ma amarahu","english":"No! Man has not yet accomplished what He commanded him"},{"number":24,"arabic":"فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","transliteration":"Falyanthuri alinsanu ila taAAamihi","english":"Then let mankind look at his food"},{"number":25,"arabic":"أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا","transliteration":"Anna sababna almaa sabban","english":"How We poured down water in torrents"},{"number":26,"arabic":"ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا","transliteration":"Thumma shaqaqna alarda shaqqan","english":"Then We broke open the earth, splitting [it with sprouts]"},{"number":27,"arabic":"فَأَنۢبَتۡنَا فِيهَا حَبّٗا","transliteration":"Faanbatna feeha habban","english":"And caused to grow within it grain"},{"number":28,"arabic":"وَعِنَبٗا وَقَضۡبٗا","transliteration":"WaAAinaban waqadban","english":"And grapes and herbage"},{"number":29,"arabic":"وَزَيۡتُونٗا وَنَخۡلٗا","transliteration":"Wazaytoonan wanakhlan","english":"And olive and palm trees"},{"number":30,"arabic":"وَحَدَآئِقَ غُلۡبٗا","transliteration":"Wahadaiqa ghulban","english":"And gardens of dense shrubbery"},{"number":31,"arabic":"وَفَٰكِهَةٗ وَأَبّٗا","transliteration":"Wafakihatan waabban","english":"And fruit and grass"},{"number":32,"arabic":"مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","transliteration":"MataAAan lakum walianAAamikum","english":"[As] enjoyment for you and your grazing livestock"},{"number":33,"arabic":"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","transliteration":"Faitha jaati alssakhkhatu","english":"But when there comes the Deafening Blast"},{"number":34,"arabic":"يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ","transliteration":"Yawma yafirru almaro min akheehi","english":"On the Day a man will flee from his brother"},{"number":35,"arabic":"وَأُمِّهِۦ وَأَبِيهِ","transliteration":"Waommihi waabeehi","english":"And his mother and his father"},{"number":36,"arabic":"وَصَٰحِبَتِهِۦ وَبَنِيهِ","transliteration":"Wasahibatihi wabaneehi","english":"And his wife and his children"},{"number":37,"arabic":"لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُمۡ يَوۡمَئِذٖ شَأۡنٞ يُغۡنِيهِ","transliteration":"Likulli imriin minhum yawmaithin shanun yughneehi","english":"For every man, that Day, will be a matter adequate for him"},{"number":38,"arabic":"وُجُوهٞ يَوۡمَئِذٖ مُّسۡفِرَةٞ","transliteration":"Wujoohun yawmaithin musfiratun","english":"[Some] faces, that Day, will be bright"},{"number":39,"arabic":"ضَاحِكَةٞ مُّسۡتَبۡشِرَةٞ","transliteration":"Dahikatun mustabshiratun","english":"Laughing, rejoicing at good news"},{"number":40,"arabic":"وَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ","transliteration":"Wawujoohun yawmaithin AAalayha ghabaratun","english":"And [other] faces, that Day, will have upon them dust"},{"number":41,"arabic":"تَرۡهَقُهَا قَتَرَةٌ","transliteration":"Tarhaquha qataratun","english":"Blackness will cover them"},{"number":42,"arabic":"أُوْلَـٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ","transliteration":"Olaika humu alkafaratu alfajaratu","english":"Those are the disbelievers, the wicked ones"}]},{"number":79,"name":"An-Nazi'at","arabicName":"النازعات","meaning":"Those who drag forth","minutes":4.1,"ayahs":[{"number":1,"arabic":"وَٱلنَّـٰزِعَٰتِ غَرۡقٗا","transliteration":"WaalnnaziAAati gharqan","english":"By those [angels] who extract with violence"},{"number":2,"arabic":"وَٱلنَّـٰشِطَٰتِ نَشۡطٗا","transliteration":"Waalnnashitati nashtan","english":"And [by] those who remove with ease"},{"number":3,"arabic":"وَٱلسَّـٰبِحَٰتِ سَبۡحٗا","transliteration":"Waalssabihati sabhan","english":"And [by] those who glide [as if] swimming"},{"number":4,"arabic":"فَٱلسَّـٰبِقَٰتِ سَبۡقٗا","transliteration":"Faalssabiqati sabqan","english":"And those who race each other in a race"},{"number":5,"arabic":"فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا","transliteration":"Faalmudabbirati amran","english":"And those who arrange [each] matter"},{"number":6,"arabic":"يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ","transliteration":"Yawma tarjufu alrrajifatu","english":"On the Day the blast [of the Horn] will convulse [creation]"},{"number":7,"arabic":"تَتۡبَعُهَا ٱلرَّادِفَةُ","transliteration":"TatbaAAuha alrradifatu","english":"There will follow it the subsequent [one]"},{"number":8,"arabic":"قُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ","transliteration":"Quloobun yawmaithin wajifatun","english":"Hearts, that Day, will tremble"},{"number":9,"arabic":"أَبۡصَٰرُهَا خَٰشِعَةٞ","transliteration":"Absaruha khashiAAatun","english":"Their eyes humbled"},{"number":10,"arabic":"يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ","transliteration":"Yaqooloona ainna lamardoodoona fee alhafirati","english":"They are [presently] saying, \"Will we indeed be returned to [our] former state [of life]"},{"number":11,"arabic":"أَءِذَا كُنَّا عِظَٰمٗا نَّخِرَةٗ","transliteration":"Aitha kunna AAithaman nakhiratan","english":"Even if we should be decayed bones"},{"number":12,"arabic":"قَالُواْ تِلۡكَ إِذٗا كَرَّةٌ خَاسِرَةٞ","transliteration":"Qaloo tilka ithan karratun khasiratun","english":"They say, \"That, then, would be a losing return"},{"number":13,"arabic":"فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ","transliteration":"Fainnama hiya zajratun wahidatun","english":"Indeed, it will be but one shout"},{"number":14,"arabic":"فَإِذَا هُم بِٱلسَّاهِرَةِ","transliteration":"Faitha hum bialssahirati","english":"And suddenly they will be [alert] upon the earth's surface"},{"number":15,"arabic":"هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","transliteration":"Hal ataka hadeethu moosa","english":"Has there reached you the story of Moses"},{"number":16,"arabic":"إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى","transliteration":"Ith nadahu rabbuhu bialwadi almuqaddasi tuwan","english":"When his Lord called to him in the sacred valley of Tuwa"},{"number":17,"arabic":"ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ","transliteration":"Ithhab ila firAAawna innahu tagha","english":"Go to Pharaoh. Indeed, he has transgressed"},{"number":18,"arabic":"فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","transliteration":"Faqul hal laka ila an tazakka","english":"And say to him, 'Would you [be willing to] purify yourself"},{"number":19,"arabic":"وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ","transliteration":"Waahdiyaka ila rabbika fatakhsha","english":"And let me guide you to your Lord so you would fear [Him]"},{"number":20,"arabic":"فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ","transliteration":"Faarahu alayata alkubra","english":"And he showed him the greatest sign"},{"number":21,"arabic":"فَكَذَّبَ وَعَصَىٰ","transliteration":"Fakaththaba waAAasa","english":"But Pharaoh denied and disobeyed"},{"number":22,"arabic":"ثُمَّ أَدۡبَرَ يَسۡعَىٰ","transliteration":"Thumma adbara yasAAa","english":"Then he turned his back, striving"},{"number":23,"arabic":"فَحَشَرَ فَنَادَىٰ","transliteration":"Fahashara fanada","english":"And he gathered [his people] and called out"},{"number":24,"arabic":"فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ","transliteration":"Faqala ana rabbukumu alaAAla","english":"And said, \"I am your most exalted lord"},{"number":25,"arabic":"فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ","transliteration":"Faakhathahu Allahu nakala alakhirati waaloola","english":"So Allah seized him in exemplary punishment for the last and the first [transgression]"},{"number":26,"arabic":"إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ","transliteration":"Inna fee thalika laAAibratan liman yakhsha","english":"Indeed in that is a warning for whoever would fear [Allah]"},{"number":27,"arabic":"ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا","transliteration":"Aantum ashaddu khalqan ami alssamao banaha","english":"Are you a more difficult creation or is the heaven? Allah constructed it"},{"number":28,"arabic":"رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا","transliteration":"RafaAAa samkaha fasawwaha","english":"He raised its ceiling and proportioned it"},{"number":29,"arabic":"وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا","transliteration":"Waaghtasha laylaha waakhraja duhaha","english":"And He darkened its night and extracted its brightness"},{"number":30,"arabic":"وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ","transliteration":"Waalarda baAAda thalika dahaha","english":"And after that He spread the earth"},{"number":31,"arabic":"أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا","transliteration":"Akhraja minha maaha wamarAAaha","english":"He extracted from it its water and its pasture"},{"number":32,"arabic":"وَٱلۡجِبَالَ أَرۡسَىٰهَا","transliteration":"Waaljibala arsaha","english":"And the mountains He set firmly"},{"number":33,"arabic":"مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ","transliteration":"MataAAan lakum walianAAamikum","english":"As provision for you and your grazing livestock"},{"number":34,"arabic":"فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ","transliteration":"Faitha jaati alttammatu alkubra","english":"But when there comes the greatest Overwhelming Calamity"},{"number":35,"arabic":"يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ","transliteration":"Yawma yatathakkaru alinsanu ma saAAa","english":"The Day when man will remember that for which he strove"},{"number":36,"arabic":"وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ","transliteration":"Waburrizati aljaheemu liman yara","english":"And Hellfire will be exposed for [all] those who see"},{"number":37,"arabic":"فَأَمَّا مَن طَغَىٰ","transliteration":"Faamma man tagha","english":"So as for he who transgressed"},{"number":38,"arabic":"وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","transliteration":"Waathara alhayata alddunya","english":"And preferred the life of the world"},{"number":39,"arabic":"فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ","transliteration":"Fainna aljaheema hiya almawa","english":"Then indeed, Hellfire will be [his] refuge"},{"number":40,"arabic":"وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ","transliteration":"Waama man khafa maqama rabbihi wanaha alnnafsa AAani alhawa","english":"But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination"},{"number":41,"arabic":"فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ","transliteration":"Fainna aljannata hiya almawa","english":"Then indeed, Paradise will be [his] refuge"},{"number":42,"arabic":"يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا","transliteration":"Yasaloonaka AAani alssaAAati ayyana mursaha","english":"They ask you, [O Muhammad], about the Hour: when is its arrival"},{"number":43,"arabic":"فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ","transliteration":"Feema anta min thikraha","english":"In what [position] are you that you should mention it"},{"number":44,"arabic":"إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","transliteration":"Ila rabbika muntahaha","english":"To your Lord is its finality"},{"number":45,"arabic":"إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا","transliteration":"Innama anta munthiru man yakhshaha","english":"You are only a warner for those who fear it"},{"number":46,"arabic":"كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا","transliteration":"Kaannahum yawma yarawnaha lam yalbathoo illa AAashiyyatan aw duhaha","english":"It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof"}]},{"number":78,"name":"An-Naba","arabicName":"النبإ","meaning":"The Tidings","minutes":4.1,"ayahs":[{"number":1,"arabic":"عَمَّ يَتَسَآءَلُونَ","transliteration":"AAamma yatasaaloona","english":"About what are they asking one another"},{"number":2,"arabic":"عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ","transliteration":"AAani alnnabai alAAatheemi","english":"About the great news"},{"number":3,"arabic":"ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ","transliteration":"Allathee hum feehi mukhtalifoona","english":"That over which they are in disagreement"},{"number":4,"arabic":"كَلَّا سَيَعۡلَمُونَ","transliteration":"Kalla sayaAAlamoona","english":"No! They are going to know"},{"number":5,"arabic":"ثُمَّ كَلَّا سَيَعۡلَمُونَ","transliteration":"Thumma kalla sayaAAlamoona","english":"Then, no! They are going to know"},{"number":6,"arabic":"أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا","transliteration":"Alam najAAali alarda mihadan","english":"Have We not made the earth a resting place"},{"number":7,"arabic":"وَٱلۡجِبَالَ أَوۡتَادٗا","transliteration":"Waaljibala awtadan","english":"And the mountains as stakes"},{"number":8,"arabic":"وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا","transliteration":"Wakhalaqnakum azwajan","english":"And We created you in pairs"},{"number":9,"arabic":"وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا","transliteration":"WajaAAalna nawmakum subatan","english":"And made your sleep [a means for] rest"},{"number":10,"arabic":"وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا","transliteration":"WajaAAalna allayla libasan","english":"And made the night as clothing"},{"number":11,"arabic":"وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا","transliteration":"WajaAAalna alnnahara maAAashan","english":"And made the day for livelihood"},{"number":12,"arabic":"وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا","transliteration":"Wabanayna fawqakum sabAAan shidadan","english":"And constructed above you seven strong [heavens]"},{"number":13,"arabic":"وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا","transliteration":"WajaAAalna sirajan wahhajan","english":"And made [therein] a burning lamp"},{"number":14,"arabic":"وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا","transliteration":"Waanzalna mina almuAAsirati maan thajjajan","english":"And sent down, from the rain clouds, pouring water"},{"number":15,"arabic":"لِّنُخۡرِجَ بِهِۦ حَبّٗا وَنَبَاتٗا","transliteration":"Linukhrija bihi habban wanabatan","english":"That We may bring forth thereby grain and vegetation"},{"number":16,"arabic":"وَجَنَّـٰتٍ أَلۡفَافًا","transliteration":"Wajannatin alfafan","english":"And gardens of entwined growth"},{"number":17,"arabic":"إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتٗا","transliteration":"Inna yawma alfasli kana meeqatan","english":"Indeed, the Day of Judgement is an appointed time"},{"number":18,"arabic":"يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجٗا","transliteration":"Yawma yunfakhu fee alssoori fatatoona afwajan","english":"The Day the Horn is blown and you will come forth in multitudes"},{"number":19,"arabic":"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبٗا","transliteration":"Wafutihati alssamao fakanat abwaban","english":"And the heaven is opened and will become gateways"},{"number":20,"arabic":"وَسُيِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا","transliteration":"Wasuyyirati aljibalu fakanat saraban","english":"And the mountains are removed and will be [but] a mirage"},{"number":21,"arabic":"إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا","transliteration":"Inna jahannama kanat mirsadan","english":"Indeed, Hell has been lying in wait"},{"number":22,"arabic":"لِّلطَّـٰغِينَ مَـَٔابٗا","transliteration":"Lilttagheena maaban","english":"For the transgressors, a place of return"},{"number":23,"arabic":"لَّـٰبِثِينَ فِيهَآ أَحۡقَابٗا","transliteration":"Labitheena feeha ahqaban","english":"In which they will remain for ages [unending]"},{"number":24,"arabic":"لَّا يَذُوقُونَ فِيهَا بَرۡدٗا وَلَا شَرَابًا","transliteration":"La yathooqoona feeha bardan wala sharaban","english":"They will not taste therein [any] coolness or drink"},{"number":25,"arabic":"إِلَّا حَمِيمٗا وَغَسَّاقٗا","transliteration":"Illa hameeman waghassaqan","english":"Except scalding water and [foul] purulence"},{"number":26,"arabic":"جَزَآءٗ وِفَاقًا","transliteration":"Jazaan wifaqan","english":"An appropriate recompense"},{"number":27,"arabic":"إِنَّهُمۡ كَانُواْ لَا يَرۡجُونَ حِسَابٗا","transliteration":"Innahum kanoo la yarjoona hisaban","english":"Indeed, they were not expecting an account"},{"number":28,"arabic":"وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابٗا","transliteration":"Wakaththaboo biayatina kiththaban","english":"And denied Our verses with [emphatic] denial"},{"number":29,"arabic":"وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا","transliteration":"Wakulla shayin ahsaynahu kitaban","english":"But all things We have enumerated in writing"},{"number":30,"arabic":"فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا","transliteration":"Fathooqoo falan nazeedakum illa AAathaban","english":"So taste [the penalty], and never will We increase you except in torment"},{"number":31,"arabic":"إِنَّ لِلۡمُتَّقِينَ مَفَازًا","transliteration":"Inna lilmuttaqeena mafazan","english":"Indeed, for the righteous is attainment"},{"number":32,"arabic":"حَدَآئِقَ وَأَعۡنَٰبٗا","transliteration":"Hadaiqa waaAAnaban","english":"Gardens and grapevines"},{"number":33,"arabic":"وَكَوَاعِبَ أَتۡرَابٗا","transliteration":"WakawaAAiba atraban","english":"And full-breasted [companions] of equal age"},{"number":34,"arabic":"وَكَأۡسٗا دِهَاقٗا","transliteration":"Wakasan dihaqan","english":"And a full cup"},{"number":35,"arabic":"لَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّـٰبٗا","transliteration":"La yasmaAAoona feeha laghwan wala kiththaban","english":"No ill speech will they hear therein or any falsehood"},{"number":36,"arabic":"جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَابٗا","transliteration":"Jazaan min rabbika AAataan hisaban","english":"[As] reward from your Lord, [a generous] gift [made due by] account"},{"number":37,"arabic":"رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابٗا","transliteration":"Rabbi alssamawati waalardi wama baynahuma alrrahmani la yamlikoona minhu khitaban","english":"[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech"},{"number":38,"arabic":"يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰٓئِكَةُ صَفّٗاۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابٗا","transliteration":"Yawma yaqoomu alrroohu waalmalaikatu saffan la yatakallamoona illa man athina lahu alrrahmanu waqala sawaban","english":"The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct"},{"number":39,"arabic":"ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","transliteration":"Thalika alyawmu alhaqqu faman shaa ittakhatha ila rabbihi maaban","english":"That is the True Day; so he who wills may take to his Lord a [way of] return"},{"number":40,"arabic":"إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا","transliteration":"Inna antharnakum AAathaban qareeban yawma yanthuru almaro ma qaddamat yadahu wayaqoolu alkafiru ya laytanee kuntu turaban","english":"Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, \"Oh, I wish that I were dust"}]},{"number":77,"name":"Al-Mursalat","arabicName":"المرسلات","meaning":"The Emissaries","minutes":4.3,"ayahs":[{"number":1,"arabic":"وَٱلۡمُرۡسَلَٰتِ عُرۡفٗا","transliteration":"Waalmursalati AAurfan","english":"By those [winds] sent forth in gusts"},{"number":2,"arabic":"فَٱلۡعَٰصِفَٰتِ عَصۡفٗا","transliteration":"FaalAAasifati AAasfan","english":"And the winds that blow violently"},{"number":3,"arabic":"وَٱلنَّـٰشِرَٰتِ نَشۡرٗا","transliteration":"Waalnnashirati nashran","english":"And [by] the winds that spread [clouds]"},{"number":4,"arabic":"فَٱلۡفَٰرِقَٰتِ فَرۡقٗا","transliteration":"Faalfariqati farqan","english":"And those [angels] who bring criterion"},{"number":5,"arabic":"فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا","transliteration":"Faalmulqiyati thikran","english":"And those [angels] who deliver a message"},{"number":6,"arabic":"عُذۡرًا أَوۡ نُذۡرًا","transliteration":"AAuthran aw nuthran","english":"As justification or warning"},{"number":7,"arabic":"إِنَّمَا تُوعَدُونَ لَوَٰقِعٞ","transliteration":"Innama tooAAadoona lawaqiAAun","english":"Indeed, what you are promised is to occur"},{"number":8,"arabic":"فَإِذَا ٱلنُّجُومُ طُمِسَتۡ","transliteration":"Faitha alnnujoomu tumisat","english":"So when the stars are obliterated"},{"number":9,"arabic":"وَإِذَا ٱلسَّمَآءُ فُرِجَتۡ","transliteration":"Waitha alssamao furijat","english":"And when the heaven is opened"},{"number":10,"arabic":"وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ","transliteration":"Waitha aljibalu nusifat","english":"And when the mountains are blown away"},{"number":11,"arabic":"وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ","transliteration":"Waitha alrrusulu oqqitat","english":"And when the messengers' time has come"},{"number":12,"arabic":"لِأَيِّ يَوۡمٍ أُجِّلَتۡ","transliteration":"Liayyi yawmin ojjilat","english":"For what Day was it postponed"},{"number":13,"arabic":"لِيَوۡمِ ٱلۡفَصۡلِ","transliteration":"Liyawmi alfasli","english":"For the Day of Judgement"},{"number":14,"arabic":"وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ","transliteration":"Wama adraka ma yawmu alfasli","english":"And what can make you know what is the Day of Judgement"},{"number":15,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":16,"arabic":"أَلَمۡ نُهۡلِكِ ٱلۡأَوَّلِينَ","transliteration":"Alam nuhliki alawwaleena","english":"Did We not destroy the former peoples"},{"number":17,"arabic":"ثُمَّ نُتۡبِعُهُمُ ٱلۡأٓخِرِينَ","transliteration":"Thumma nutbiAAuhumu alakhireena","english":"Then We will follow them with the later ones"},{"number":18,"arabic":"كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ","transliteration":"Kathalika nafAAalu bialmujrimeena","english":"Thus do We deal with the criminals"},{"number":19,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":20,"arabic":"أَلَمۡ نَخۡلُقكُّم مِّن مَّآءٖ مَّهِينٖ","transliteration":"Alam nakhluqkum min main maheenin","english":"Did We not create you from a liquid disdained"},{"number":21,"arabic":"فَجَعَلۡنَٰهُ فِي قَرَارٖ مَّكِينٍ","transliteration":"FajaAAalnahu fee qararin makeenin","english":"And We placed it in a firm lodging"},{"number":22,"arabic":"إِلَىٰ قَدَرٖ مَّعۡلُومٖ","transliteration":"Ila qadarin maAAloomin","english":"For a known extent"},{"number":23,"arabic":"فَقَدَرۡنَا فَنِعۡمَ ٱلۡقَٰدِرُونَ","transliteration":"Faqadarna faniAAma alqadiroona","english":"And We determined [it], and excellent [are We] to determine"},{"number":24,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":25,"arabic":"أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا","transliteration":"Alam najAAali alarda kifatan","english":"Have We not made the earth a container"},{"number":26,"arabic":"أَحۡيَآءٗ وَأَمۡوَٰتٗا","transliteration":"Ahyaan waamwatan","english":"Of the living and the dead"},{"number":27,"arabic":"وَجَعَلۡنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتٖ وَأَسۡقَيۡنَٰكُم مَّآءٗ فُرَاتٗا","transliteration":"WajaAAalna feeha rawasiya shamikhatin waasqaynakum maan furatan","english":"And We placed therein lofty, firmly set mountains and have given you to drink sweet water"},{"number":28,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":29,"arabic":"ٱنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ","transliteration":"Intaliqoo ila ma kuntum bihi tukaththiboona","english":"[They will be told], \"Proceed to that which you used to deny"},{"number":30,"arabic":"ٱنطَلِقُوٓاْ إِلَىٰ ظِلّٖ ذِي ثَلَٰثِ شُعَبٖ","transliteration":"Intaliqoo ila thillin thee thalathi shuAAabin","english":"Proceed to a shadow [of smoke] having three columns"},{"number":31,"arabic":"لَّا ظَلِيلٖ وَلَا يُغۡنِي مِنَ ٱللَّهَبِ","transliteration":"La thaleelin wala yughnee mina allahabi","english":"[But having] no cool shade and availing not against the flame"},{"number":32,"arabic":"إِنَّهَا تَرۡمِي بِشَرَرٖ كَٱلۡقَصۡرِ","transliteration":"Innaha tarmee bishararin kaalqasri","english":"Indeed, it throws sparks [as huge] as a fortress"},{"number":33,"arabic":"كَأَنَّهُۥ جِمَٰلَتٞ صُفۡرٞ","transliteration":"Kaannahu jimalatun sufrun","english":"As if they were yellowish [black] camels"},{"number":34,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":35,"arabic":"هَٰذَا يَوۡمُ لَا يَنطِقُونَ","transliteration":"Hatha yawmu la yantiqoona","english":"This is a Day they will not speak"},{"number":36,"arabic":"وَلَا يُؤۡذَنُ لَهُمۡ فَيَعۡتَذِرُونَ","transliteration":"Wala yuthanu lahum fayaAAtathiroona","english":"Nor will it be permitted for them to make an excuse"},{"number":37,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":38,"arabic":"هَٰذَا يَوۡمُ ٱلۡفَصۡلِۖ جَمَعۡنَٰكُمۡ وَٱلۡأَوَّلِينَ","transliteration":"Hatha yawmu alfasli jamaAAnakum waalawwaleena","english":"This is the Day of Judgement; We will have assembled you and the former peoples"},{"number":39,"arabic":"فَإِن كَانَ لَكُمۡ كَيۡدٞ فَكِيدُونِ","transliteration":"Fain kana lakum kaydun fakeedooni","english":"So if you have a plan, then plan against Me"},{"number":40,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":41,"arabic":"إِنَّ ٱلۡمُتَّقِينَ فِي ظِلَٰلٖ وَعُيُونٖ","transliteration":"Inna almuttaqeena fee thilalin waAAuyoonin","english":"Indeed, the righteous will be among shades and springs"},{"number":42,"arabic":"وَفَوَٰكِهَ مِمَّا يَشۡتَهُونَ","transliteration":"Wafawakiha mimma yashtahoona","english":"And fruits from whatever they desire"},{"number":43,"arabic":"كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ","transliteration":"Kuloo waishraboo haneean bima kuntum taAAmaloona","english":"[Being told], \"Eat and drink in satisfaction for what you used to do"},{"number":44,"arabic":"إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","transliteration":"Inna kathalika najzee almuhsineena","english":"Indeed, We thus reward the doers of good"},{"number":45,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":46,"arabic":"كُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ","transliteration":"Kuloo watamattaAAoo qaleelan innakum mujrimoona","english":"[O disbelievers], eat and enjoy yourselves a little; indeed, you are criminals"},{"number":47,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":48,"arabic":"وَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ","transliteration":"Waitha qeela lahumu irkaAAoo la yarkaAAoona","english":"And when it is said to them, \"Bow [in prayer],\" they do not bow"},{"number":49,"arabic":"وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Waylun yawmaithin lilmukaththibeena","english":"Woe, that Day, to the deniers"},{"number":50,"arabic":"فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ","transliteration":"Fabiayyi hadeethin baAAdahu yuminoona","english":"Then in what statement after the Qur'an will they believe"}]},{"number":76,"name":"Al-Insan","arabicName":"الانسان","meaning":"The Man","minutes":5.7,"ayahs":[{"number":1,"arabic":"هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا","transliteration":"Hal ata AAala alinsani heenun mina alddahri lam yakun shayan mathkooran","english":"Has there [not] come upon man a period of time when he was not a thing [even] mentioned"},{"number":2,"arabic":"إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا","transliteration":"Inna khalaqna alinsana min nutfatin amshajin nabtaleehi fajaAAalnahu sameeAAan baseeran","english":"Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing"},{"number":3,"arabic":"إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا","transliteration":"Inna hadaynahu alssabeela imma shakiran waimma kafooran","english":"Indeed, We guided him to the way, be he grateful or be he ungrateful"},{"number":4,"arabic":"إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ وَأَغۡلَٰلٗا وَسَعِيرًا","transliteration":"Inna aAAtadna lilkafireena salasila waaghlalan wasaAAeeran","english":"Indeed, We have prepared for the disbelievers chains and shackles and a blaze"},{"number":5,"arabic":"إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا","transliteration":"Inna alabrara yashraboona min kasin kana mizajuha kafooran","english":"Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kafur"},{"number":6,"arabic":"عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا","transliteration":"AAaynan yashrabu biha AAibadu Allahi yufajjiroonaha tafjeeran","english":"A spring of which the [righteous] servants of Allah will drink; they will make it gush forth in force [and abundance]"},{"number":7,"arabic":"يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا","transliteration":"Yoofoona bialnnathri wayakhafoona yawman kana sharruhu mustateeran","english":"They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread"},{"number":8,"arabic":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","transliteration":"WayutAAimona alttaAAama AAala hubbihi miskeenan wayateeman waaseeran","english":"And they give food in spite of love for it to the needy, the orphan, and the captive"},{"number":9,"arabic":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","transliteration":"Innama nutAAimukum liwajhi Allahi la nureedu minkum jazaan wala shukooran","english":"[Saying], \"We feed you only for the countenance of Allah. We wish not from you reward or gratitude"},{"number":10,"arabic":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا","transliteration":"Inna nakhafu min rabbina yawman AAaboosan qamtareeran","english":"Indeed, We fear from our Lord a Day austere and distressful"},{"number":11,"arabic":"فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا","transliteration":"Fawaqahumu Allahu sharra thalika alyawmi walaqqahum nadratan wasurooran","english":"So Allah will protect them from the evil of that Day and give them radiance and happiness"},{"number":12,"arabic":"وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا","transliteration":"Wajazahum bima sabaroo jannatan wahareeran","english":"And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments]"},{"number":13,"arabic":"مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا","transliteration":"Muttakieena feeha AAala alaraiki la yarawna feeha shamsan wala zamhareeran","english":"[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold"},{"number":14,"arabic":"وَدَانِيَةً عَلَيۡهِمۡ ظِلَٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلٗا","transliteration":"Wadaniyatan AAalayhim thilaluha wathullilat qutoofuha tathleelan","english":"And near above them are its shades, and its [fruit] to be picked will be lowered in compliance"},{"number":15,"arabic":"وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةٖ مِّن فِضَّةٖ وَأَكۡوَابٖ كَانَتۡ قَوَارِيرَا۠","transliteration":"Wayutafu AAalayhim bianiyatin min fiddatin waakwabin kanat qawareera","english":"And there will be circulated among them vessels of silver and cups having been [created] clear [as glass]"},{"number":16,"arabic":"قَوَارِيرَاْ مِن فِضَّةٖ قَدَّرُوهَا تَقۡدِيرٗا","transliteration":"Qawareera min fiddatin qaddarooha taqdeeran","english":"Clear glasses [made] from silver of which they have determined the measure"},{"number":17,"arabic":"وَيُسۡقَوۡنَ فِيهَا كَأۡسٗا كَانَ مِزَاجُهَا زَنجَبِيلًا","transliteration":"Wayusqawna feeha kasan kana mizajuha zanjabeelan","english":"And they will be given to drink a cup [of wine] whose mixture is of ginger"},{"number":18,"arabic":"عَيۡنٗا فِيهَا تُسَمَّىٰ سَلۡسَبِيلٗا","transliteration":"AAaynan feeha tusamma salsabeelan","english":"[From] a fountain within Paradise named Salsabeel"},{"number":19,"arabic":"۞وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا","transliteration":"Wayatoofu AAalayhim wildanun mukhalladoona itha raaytahum hasibtahum luluan manthooran","english":"There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls"},{"number":20,"arabic":"وَإِذَا رَأَيۡتَ ثَمَّ رَأَيۡتَ نَعِيمٗا وَمُلۡكٗا كَبِيرًا","transliteration":"Waitha raayta thamma raayta naAAeeman wamulkan kabeeran","english":"And when you look there [in Paradise], you will see pleasure and great dominion"},{"number":21,"arabic":"عَٰلِيَهُمۡ ثِيَابُ سُندُسٍ خُضۡرٞ وَإِسۡتَبۡرَقٞۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةٖ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابٗا طَهُورًا","transliteration":"AAaliyahum thiyabu sundusin khudrun waistabraqun wahulloo asawira min fiddatin wasaqahum rabbuhum sharaban tahooran","english":"Upon the inhabitants will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink"},{"number":22,"arabic":"إِنَّ هَٰذَا كَانَ لَكُمۡ جَزَآءٗ وَكَانَ سَعۡيُكُم مَّشۡكُورًا","transliteration":"Inna hatha kana lakum jazaan wakana saAAyukum mashkooran","english":"[And it will be said], \"Indeed, this is for you a reward, and your effort has been appreciated"},{"number":23,"arabic":"إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلٗا","transliteration":"Inna nahnu nazzalna AAalayka alqurana tanzeelan","english":"Indeed, it is We who have sent down to you, [O Muhammad], the Qur'an progressively"},{"number":24,"arabic":"فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا","transliteration":"Faisbir lihukmi rabbika wala tutiAA minhum athiman aw kafooran","english":"So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever]"},{"number":25,"arabic":"وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا","transliteration":"Waothkuri isma rabbika bukratan waaseelan","english":"And mention the name of your Lord [in prayer] morning and evening"},{"number":26,"arabic":"وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا","transliteration":"Wamina allayli faosjud lahu wasabbihhu laylan taweelan","english":"And during the night prostrate to Him and exalt Him a long [part of the] night"},{"number":27,"arabic":"إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلۡعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمۡ يَوۡمٗا ثَقِيلٗا","transliteration":"Inna haolai yuhibboona alAAajilata wayatharoona waraahum yawman thaqeelan","english":"Indeed, these [disbelievers] love the immediate and leave behind them a grave Day"},{"number":28,"arabic":"نَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا","transliteration":"Nahnu khalaqnahum washadadna asrahum waitha shina baddalna amthalahum tabdeelan","english":"We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration"},{"number":29,"arabic":"إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا","transliteration":"Inna hathihi tathkiratun faman shaa ittakhatha ila rabbihi sabeelan","english":"Indeed, this is a reminder, so he who wills may take to his Lord a way"},{"number":30,"arabic":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","transliteration":"Wama tashaoona illa an yashaa Allahu inna Allaha kana AAaleeman hakeeman","english":"And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise"},{"number":31,"arabic":"يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا","transliteration":"Yudkhilu man yashao fee rahmatihi waalththalimeena aAAadda lahum AAathaban aleeman","english":"He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment"}]},{"number":75,"name":"Al-Qiyamah","arabicName":"القيامة","meaning":"The Resurrection","minutes":3.5,"ayahs":[{"number":1,"arabic":"لَآ أُقۡسِمُ بِيَوۡمِ ٱلۡقِيَٰمَةِ","transliteration":"La oqsimu biyawmi alqiyamati","english":"I swear by the Day of Resurrection"},{"number":2,"arabic":"وَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ","transliteration":"Wala oqsimu bialnnafsi allawwamati","english":"And I swear by the reproaching soul [to the certainty of resurrection]"},{"number":3,"arabic":"أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ","transliteration":"Ayahsabu alinsanu allan najmaAAa AAithamahu","english":"Does man think that We will not assemble his bones"},{"number":4,"arabic":"بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ","transliteration":"Bala qadireena AAala an nusawwiya bananahu","english":"Yes. [We are] Able [even] to proportion his fingertips"},{"number":5,"arabic":"بَلۡ يُرِيدُ ٱلۡإِنسَٰنُ لِيَفۡجُرَ أَمَامَهُۥ","transliteration":"Bal yureedu alinsanu liyafjura amamahu","english":"But man desires to continue in sin"},{"number":6,"arabic":"يَسۡـَٔلُ أَيَّانَ يَوۡمُ ٱلۡقِيَٰمَةِ","transliteration":"Yasalu ayyana yawmu alqiyamati","english":"He asks, \"When is the Day of Resurrection"},{"number":7,"arabic":"فَإِذَا بَرِقَ ٱلۡبَصَرُ","transliteration":"Faitha bariqa albasaru","english":"So when vision is dazzled"},{"number":8,"arabic":"وَخَسَفَ ٱلۡقَمَرُ","transliteration":"Wakhasafa alqamaru","english":"And the moon darkens"},{"number":9,"arabic":"وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ","transliteration":"WajumiAAa alshshamsu waalqamaru","english":"And the sun and the moon are joined"},{"number":10,"arabic":"يَقُولُ ٱلۡإِنسَٰنُ يَوۡمَئِذٍ أَيۡنَ ٱلۡمَفَرُّ","transliteration":"Yaqoolu alinsanu yawmaithin ayna almafarru","english":"Man will say on that Day, \"Where is the [place of] escape"},{"number":11,"arabic":"كَلَّا لَا وَزَرَ","transliteration":"Kalla la wazara","english":"No! There is no refuge"},{"number":12,"arabic":"إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمُسۡتَقَرُّ","transliteration":"Ila rabbika yawmaithin almustaqarru","english":"To your Lord, that Day, is the [place of] permanence"},{"number":13,"arabic":"يُنَبَّؤُاْ ٱلۡإِنسَٰنُ يَوۡمَئِذِۭ بِمَا قَدَّمَ وَأَخَّرَ","transliteration":"Yunabbao alinsanu yawmaithin bima qaddama waakhkhara","english":"Man will be informed that Day of what he sent ahead and kept back"},{"number":14,"arabic":"بَلِ ٱلۡإِنسَٰنُ عَلَىٰ نَفۡسِهِۦ بَصِيرَةٞ","transliteration":"Bali alinsanu AAala nafsihi baseeratun","english":"Rather, man, against himself, will be a witness"},{"number":15,"arabic":"وَلَوۡ أَلۡقَىٰ مَعَاذِيرَهُۥ","transliteration":"Walaw alqa maAAatheerahu","english":"Even if he presents his excuses"},{"number":16,"arabic":"لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ","transliteration":"La tuharrik bihi lisanaka litaAAjala bihi","english":"Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur'an"},{"number":17,"arabic":"إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ","transliteration":"Inna AAalayna jamAAahu waquranahu","english":"Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation"},{"number":18,"arabic":"فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ","transliteration":"Faitha qaranahu faittabiAA quranahu","english":"So when We have recited it [through Gabriel], then follow its recitation"},{"number":19,"arabic":"ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ","transliteration":"Thumma inna AAalayna bayanahu","english":"Then upon Us is its clarification [to you]"},{"number":20,"arabic":"كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ","transliteration":"Kalla bal tuhibboona alAAajilata","english":"No! But you love the immediate"},{"number":21,"arabic":"وَتَذَرُونَ ٱلۡأٓخِرَةَ","transliteration":"Watatharoona alakhirata","english":"And leave the Hereafter"},{"number":22,"arabic":"وُجُوهٞ يَوۡمَئِذٖ نَّاضِرَةٌ","transliteration":"Wujoohun yawmaithin nadiratun","english":"[Some] faces, that Day, will be radiant"},{"number":23,"arabic":"إِلَىٰ رَبِّهَا نَاظِرَةٞ","transliteration":"Ila rabbiha nathiratun","english":"Looking at their Lord"},{"number":24,"arabic":"وَوُجُوهٞ يَوۡمَئِذِۭ بَاسِرَةٞ","transliteration":"Wawujoohun yawmaithin basiratun","english":"And [some] faces, that Day, will be contorted"},{"number":25,"arabic":"تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ","transliteration":"Tathunnu an yufAAala biha faqiratun","english":"Expecting that there will be done to them [something] backbreaking"},{"number":26,"arabic":"كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِيَ","transliteration":"Kalla itha balaghati alttaraqiya","english":"No! When the soul has reached the collar bones"},{"number":27,"arabic":"وَقِيلَ مَنۡۜ رَاقٖ","transliteration":"Waqeela man raqin","english":"And it is said, \"Who will cure [him]"},{"number":28,"arabic":"وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ","transliteration":"Wathanna annahu alfiraqu","english":"And the dying one is certain that it is the [time of] separation"},{"number":29,"arabic":"وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ","transliteration":"Wailtaffati alssaqu bialssaqi","english":"And the leg is wound about the leg"},{"number":30,"arabic":"إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمَسَاقُ","transliteration":"Ila rabbika yawmaithin almasaqu","english":"To your Lord, that Day, will be the procession"},{"number":31,"arabic":"فَلَا صَدَّقَ وَلَا صَلَّىٰ","transliteration":"Fala saddaqa wala salla","english":"And the disbeliever had not believed, nor had he prayed"},{"number":32,"arabic":"وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ","transliteration":"Walakin kaththaba watawalla","english":"But [instead], he denied and turned away"},{"number":33,"arabic":"ثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ يَتَمَطَّىٰٓ","transliteration":"Thumma thahaba ila ahlihi yatamatta","english":"And then he went to his people, swaggering [in pride]"},{"number":34,"arabic":"أَوۡلَىٰ لَكَ فَأَوۡلَىٰ","transliteration":"Awla laka faawla","english":"Woe to you, and woe"},{"number":35,"arabic":"ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰٓ","transliteration":"Thumma awla laka faawla","english":"Then woe to you, and woe"},{"number":36,"arabic":"أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى","transliteration":"Ayahsabu alinsanu an yutraka sudan","english":"Does man think that he will be left neglected"},{"number":37,"arabic":"أَلَمۡ يَكُ نُطۡفَةٗ مِّن مَّنِيّٖ يُمۡنَىٰ","transliteration":"Alam yaku nutfatan min manayyin yumna","english":"Had he not been a sperm from semen emitted"},{"number":38,"arabic":"ثُمَّ كَانَ عَلَقَةٗ فَخَلَقَ فَسَوَّىٰ","transliteration":"Thumma kana AAalaqatan fakhalaqa fasawwa","english":"Then he was a clinging clot, and [Allah] created [his form] and proportioned [him]"},{"number":39,"arabic":"فَجَعَلَ مِنۡهُ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ","transliteration":"FajaAAala minhu alzzawjayni alththakara waalontha","english":"And made of him two mates, the male and the female"},{"number":40,"arabic":"أَلَيۡسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰ","transliteration":"Alaysa thalika biqadirin AAala an yuhyiya almawta","english":"Is not that [Creator] Able to give life to the dead"}]},{"number":74,"name":"Al-Muddaththir","arabicName":"المدثر","meaning":"The Cloaked One","minutes":5.4,"ayahs":[{"number":1,"arabic":"يَـٰٓأَيُّهَا ٱلۡمُدَّثِّرُ","transliteration":"Ya ayyuha almuddaththiru","english":"O you who covers himself [with a garment]"},{"number":2,"arabic":"قُمۡ فَأَنذِرۡ","transliteration":"Qum faanthir","english":"Arise and warn"},{"number":3,"arabic":"وَرَبَّكَ فَكَبِّرۡ","transliteration":"Warabbaka fakabbir","english":"And your Lord glorify"},{"number":4,"arabic":"وَثِيَابَكَ فَطَهِّرۡ","transliteration":"Wathiyabaka fatahhir","english":"And your clothing purify"},{"number":5,"arabic":"وَٱلرُّجۡزَ فَٱهۡجُرۡ","transliteration":"Waalrrujza faohjur","english":"And uncleanliness avoid"},{"number":6,"arabic":"وَلَا تَمۡنُن تَسۡتَكۡثِرُ","transliteration":"Wala tamnun tastakthiru","english":"And do not confer favor to acquire more"},{"number":7,"arabic":"وَلِرَبِّكَ فَٱصۡبِرۡ","transliteration":"Walirabbika faisbir","english":"But for your Lord be patient"},{"number":8,"arabic":"فَإِذَا نُقِرَ فِي ٱلنَّاقُورِ","transliteration":"Faitha nuqira fee alnnaqoori","english":"And when the trumpet is blown"},{"number":9,"arabic":"فَذَٰلِكَ يَوۡمَئِذٖ يَوۡمٌ عَسِيرٌ","transliteration":"Fathalika yawmaithin yawmun AAaseerun","english":"That Day will be a difficult day"},{"number":10,"arabic":"عَلَى ٱلۡكَٰفِرِينَ غَيۡرُ يَسِيرٖ","transliteration":"AAala alkafireena ghayru yaseerin","english":"For the disbelievers - not easy"},{"number":11,"arabic":"ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدٗا","transliteration":"Tharnee waman khalaqtu waheedan","english":"Leave Me with the one I created alone"},{"number":12,"arabic":"وَجَعَلۡتُ لَهُۥ مَالٗا مَّمۡدُودٗا","transliteration":"WajaAAaltu lahu malan mamdoodan","english":"And to whom I granted extensive wealth"},{"number":13,"arabic":"وَبَنِينَ شُهُودٗا","transliteration":"Wabaneena shuhoodan","english":"And children present [with him]"},{"number":14,"arabic":"وَمَهَّدتُّ لَهُۥ تَمۡهِيدٗا","transliteration":"Wamahhadtu lahu tamheedan","english":"And spread [everything] before him, easing [his life]"},{"number":15,"arabic":"ثُمَّ يَطۡمَعُ أَنۡ أَزِيدَ","transliteration":"Thumma yatmaAAu an azeeda","english":"Then he desires that I should add more"},{"number":16,"arabic":"كَلَّآۖ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيدٗا","transliteration":"Kalla innahu kana liayatina AAaneedan","english":"No! Indeed, he has been toward Our verses obstinate"},{"number":17,"arabic":"سَأُرۡهِقُهُۥ صَعُودًا","transliteration":"Saorhiquhu saAAoodan","english":"I will cover him with arduous torment"},{"number":18,"arabic":"إِنَّهُۥ فَكَّرَ وَقَدَّرَ","transliteration":"Innahu fakkara waqaddara","english":"Indeed, he thought and deliberated"},{"number":19,"arabic":"فَقُتِلَ كَيۡفَ قَدَّرَ","transliteration":"Faqutila kayfa qaddara","english":"So may he be destroyed [for] how he deliberated"},{"number":20,"arabic":"ثُمَّ قُتِلَ كَيۡفَ قَدَّرَ","transliteration":"Thumma qutila kayfa qaddara","english":"Then may he be destroyed [for] how he deliberated"},{"number":21,"arabic":"ثُمَّ نَظَرَ","transliteration":"Thumma nathara","english":"Then he considered [again]"},{"number":22,"arabic":"ثُمَّ عَبَسَ وَبَسَرَ","transliteration":"Thumma AAabasa wabasara","english":"Then he frowned and scowled"},{"number":23,"arabic":"ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ","transliteration":"Thumma adbara waistakbara","english":"Then he turned back and was arrogant"},{"number":24,"arabic":"فَقَالَ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ يُؤۡثَرُ","transliteration":"Faqala in hatha illa sihrun yutharu","english":"And said, \"This is not but magic imitated [from others]"},{"number":25,"arabic":"إِنۡ هَٰذَآ إِلَّا قَوۡلُ ٱلۡبَشَرِ","transliteration":"In hatha illa qawlu albashari","english":"This is not but the word of a human being"},{"number":26,"arabic":"سَأُصۡلِيهِ سَقَرَ","transliteration":"Saosleehi saqara","english":"I will drive him into Saqar"},{"number":27,"arabic":"وَمَآ أَدۡرَىٰكَ مَا سَقَرُ","transliteration":"Wama adraka ma saqaru","english":"And what can make you know what is Saqar"},{"number":28,"arabic":"لَا تُبۡقِي وَلَا تَذَرُ","transliteration":"La tubqee wala tatharu","english":"It lets nothing remain and leaves nothing [unburned]"},{"number":29,"arabic":"لَوَّاحَةٞ لِّلۡبَشَرِ","transliteration":"Lawwahatun lilbashari","english":"Blackening the skins"},{"number":30,"arabic":"عَلَيۡهَا تِسۡعَةَ عَشَرَ","transliteration":"AAalayha tisAAata AAashara","english":"Over it are nineteen [angels]"},{"number":31,"arabic":"وَمَا جَعَلۡنَآ أَصۡحَٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةٗۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ لِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنٗا وَلَا يَرۡتَابَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَمَا يَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِيَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ","transliteration":"Wama jaAAalna ashaba alnnari illa malaikatan wama jaAAalna AAiddatahum illa fitnatan lillatheena kafaroo liyastayqina allatheena ootoo alkitaba wayazdada allatheena amanoo eemanan wala yartaba allatheena ootoo alkitaba waalmuminoona waliyaqoola allatheena fee quloobihim maradun waalkafiroona matha arada Allahu bihatha mathalan kathalika yudillu Allahu man yashao wayahdee man yashao wama yaAAlamu junooda rabbika illa huwa wama hiya illa thikra lilbashari","english":"And We have not made the keepers of the Fire except angels. And We have not made their number except as a trial for those who disbelieve - that those who were given the Scripture will be convinced and those who have believed will increase in faith and those who were given the Scripture and the believers will not doubt and that those in whose hearts is hypocrisy and the disbelievers will say, \"What does Allah intend by this as an example?\" Thus does Allah leave astray whom He wills and guides whom He wills. And none knows the soldiers of your Lord except Him. And mention of the Fire is not but a reminder to humanity"},{"number":32,"arabic":"كَلَّا وَٱلۡقَمَرِ","transliteration":"Kalla waalqamari","english":"No! By the moon"},{"number":33,"arabic":"وَٱلَّيۡلِ إِذۡ أَدۡبَرَ","transliteration":"Waallayli ith adbara","english":"And [by] the night when it departs"},{"number":34,"arabic":"وَٱلصُّبۡحِ إِذَآ أَسۡفَرَ","transliteration":"Waalssubhi itha asfara","english":"And [by] the morning when it brightens"},{"number":35,"arabic":"إِنَّهَا لَإِحۡدَى ٱلۡكُبَرِ","transliteration":"Innaha laihda alkubari","english":"Indeed, the Fire is of the greatest [afflictions]"},{"number":36,"arabic":"نَذِيرٗا لِّلۡبَشَرِ","transliteration":"Natheeran lilbashari","english":"As a warning to humanity"},{"number":37,"arabic":"لِمَن شَآءَ مِنكُمۡ أَن يَتَقَدَّمَ أَوۡ يَتَأَخَّرَ","transliteration":"Liman shaa minkum an yataqaddama aw yataakhkhara","english":"To whoever wills among you to proceed or stay behind"},{"number":38,"arabic":"كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِينَةٌ","transliteration":"Kullu nafsin bima kasabat raheenatun","english":"Every soul, for what it has earned, will be retained"},{"number":39,"arabic":"إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ","transliteration":"Illa ashaba alyameeni","english":"Except the companions of the right"},{"number":40,"arabic":"فِي جَنَّـٰتٖ يَتَسَآءَلُونَ","transliteration":"Fee jannatin yatasaaloona","english":"[Who will be] in gardens, questioning each other"},{"number":41,"arabic":"عَنِ ٱلۡمُجۡرِمِينَ","transliteration":"AAani almujrimeena","english":"About the criminals"},{"number":42,"arabic":"مَا سَلَكَكُمۡ فِي سَقَرَ","transliteration":"Ma salakakum fee saqara","english":"[And asking them], \"What put you into Saqar"},{"number":43,"arabic":"قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ","transliteration":"Qaloo lam naku mina almusalleena","english":"They will say, \"We were not of those who prayed"},{"number":44,"arabic":"وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ","transliteration":"Walam naku nutAAimu almiskeena","english":"Nor did we used to feed the poor"},{"number":45,"arabic":"وَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ","transliteration":"Wakunna nakhoodu maAAa alkhaideena","english":"And we used to enter into vain discourse with those who engaged [in it]"},{"number":46,"arabic":"وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ","transliteration":"Wakunna nukaththibu biyawmi alddeeni","english":"And we used to deny the Day of Recompense"},{"number":47,"arabic":"حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ","transliteration":"Hatta atana alyaqeenu","english":"Until there came to us the certainty"},{"number":48,"arabic":"فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّـٰفِعِينَ","transliteration":"Fama tanfaAAuhum shafaAAatu alshshafiAAeena","english":"So there will not benefit them the intercession of [any] intercessors"},{"number":49,"arabic":"فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِينَ","transliteration":"Fama lahum AAani alttathkirati muAArideena","english":"Then what is [the matter] with them that they are, from the reminder, turning away"},{"number":50,"arabic":"كَأَنَّهُمۡ حُمُرٞ مُّسۡتَنفِرَةٞ","transliteration":"Kaannahum humurun mustanfiratun","english":"As if they were alarmed donkeys"},{"number":51,"arabic":"فَرَّتۡ مِن قَسۡوَرَةِۭ","transliteration":"Farrat min qaswaratin","english":"Fleeing from a lion"},{"number":52,"arabic":"بَلۡ يُرِيدُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُؤۡتَىٰ صُحُفٗا مُّنَشَّرَةٗ","transliteration":"Bal yureedu kullu imriin minhum an yuta suhufan munashsharatan","english":"Rather, every person among them desires that he would be given scriptures spread about"},{"number":53,"arabic":"كَلَّاۖ بَل لَّا يَخَافُونَ ٱلۡأٓخِرَةَ","transliteration":"Kalla bal la yakhafoona alakhirata","english":"No! But they do not fear the Hereafter"},{"number":54,"arabic":"كَلَّآ إِنَّهُۥ تَذۡكِرَةٞ","transliteration":"Kalla innahu tathkiratun","english":"No! Indeed, the Qur'an is a reminder"},{"number":55,"arabic":"فَمَن شَآءَ ذَكَرَهُۥ","transliteration":"Faman shaa thakarahu","english":"Then whoever wills will remember it"},{"number":56,"arabic":"وَمَا يَذۡكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ","transliteration":"Wama yathkuroona illa an yashaa Allahu huwa ahlu alttaqwa waahlu almaghfirati","english":"And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness"}]},{"number":73,"name":"Al-Muzzammil","arabicName":"المزمل","meaning":"The Enshrouded One","minutes":4.5,"ayahs":[{"number":1,"arabic":"يَـٰٓأَيُّهَا ٱلۡمُزَّمِّلُ","transliteration":"Ya ayyuha almuzzammilu","english":"O you who wraps himself [in clothing]"},{"number":2,"arabic":"قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا","transliteration":"Qumi allayla illa qaleelan","english":"Arise [to pray] the night, except for a little"},{"number":3,"arabic":"نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا","transliteration":"Nisfahu awi onqus minhu qaleelan","english":"Half of it - or subtract from it a little"},{"number":4,"arabic":"أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا","transliteration":"Aw zid AAalayhi warattili alqurana tarteelan","english":"Or add to it, and recite the Qur'an with measured recitation"},{"number":5,"arabic":"إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلٗا ثَقِيلًا","transliteration":"Inna sanulqee AAalayka qawlan thaqeelan","english":"Indeed, We will cast upon you a heavy word"},{"number":6,"arabic":"إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا","transliteration":"Inna nashiata allayli hiya ashaddu watan waaqwamu qeelan","english":"Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words"},{"number":7,"arabic":"إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا","transliteration":"Inna laka fee alnnahari sabhan taweelan","english":"Indeed, for you by day is prolonged occupation"},{"number":8,"arabic":"وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا","transliteration":"Waothkuri isma rabbika watabattal ilayhi tabteelan","english":"And remember the name of your Lord and devote yourself to Him with [complete] devotion"},{"number":9,"arabic":"رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا","transliteration":"Rabbu almashriqi waalmaghribi la ilaha illa huwa faittakhithhu wakeelan","english":"[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs"},{"number":10,"arabic":"وَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرٗا جَمِيلٗا","transliteration":"Waisbir AAala ma yaqooloona waohjurhum hajran jameelan","english":"And be patient over what they say and avoid them with gracious avoidance"},{"number":11,"arabic":"وَذَرۡنِي وَٱلۡمُكَذِّبِينَ أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا","transliteration":"Watharnee waalmukaththibeena olee alnnaAAmati wamahhilhum qaleelan","english":"And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little"},{"number":12,"arabic":"إِنَّ لَدَيۡنَآ أَنكَالٗا وَجَحِيمٗا","transliteration":"Inna ladayna ankalan wajaheeman","english":"Indeed, with Us [for them] are shackles and burning fire"},{"number":13,"arabic":"وَطَعَامٗا ذَا غُصَّةٖ وَعَذَابًا أَلِيمٗا","transliteration":"WataAAaman tha ghussatin waAAathaban aleeman","english":"And food that chokes and a painful punishment"},{"number":14,"arabic":"يَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِيبٗا مَّهِيلًا","transliteration":"Yawma tarjufu alardu waaljibalu wakanati aljibalu katheeban maheelan","english":"On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down"},{"number":15,"arabic":"إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولٗا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولٗا","transliteration":"Inna arsalna ilaykum rasoolan shahidan AAalaykum kama arsalna ila firAAawna rasoolan","english":"Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger"},{"number":16,"arabic":"فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَٰهُ أَخۡذٗا وَبِيلٗا","transliteration":"FaAAasa firAAawnu alrrasoola faakhathnahu akhthan wabeelan","english":"But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure"},{"number":17,"arabic":"فَكَيۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ يَوۡمٗا يَجۡعَلُ ٱلۡوِلۡدَٰنَ شِيبًا","transliteration":"Fakayfa tattaqoona in kafartum yawman yajAAalu alwildana sheeban","english":"Then how can you fear, if you disbelieve, a Day that will make the children white- haired"},{"number":18,"arabic":"ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا","transliteration":"Alssamao munfatirun bihi kana waAAduhu mafAAoolan","english":"The heaven will break apart therefrom; ever is His promise fulfilled"},{"number":19,"arabic":"إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا","transliteration":"Inna hathihi tathkiratun faman shaa ittakhatha ila rabbihi sabeelan","english":"Indeed, this is a reminder, so whoever wills may take to his Lord a way"},{"number":20,"arabic":"۞إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ","transliteration":"Inna rabbaka yaAAlamu annaka taqoomu adna min thuluthayi allayli wanisfahu wathuluthahu wataifatun mina allatheena maAAaka waAllahu yuqaddiru allayla waalnnahara AAalima an lan tuhsoohu fataba AAalaykum faiqraoo ma tayassara mina alqurani AAalima an sayakoonu minkum marda waakharoona yadriboona fee alardi yabtaghoona min fadli Allahi waakharoona yuqatiloona fee sabeeli Allahi faiqraoo ma tayassara minhu waaqeemoo alssalata waatoo alzzakata waaqridoo Allaha qardan hasanan wama tuqaddimoo lianfusikum min khayrin tajidoohu AAinda Allahi huwa khayran waaAAthama ajran waistaghfiroo Allaha inna Allaha ghafoorun raheemun","english":"Indeed, your Lord knows, [O Muhammad], that you stand [in prayer] almost two thirds of the night or half of it or a third of it, and [so do] a group of those with you. And Allah determines [the extent of] the night and the day. He has known that you [Muslims] will not be able to do it and has turned to you in forgiveness, so recite what is easy [for you] of the Qur'an. He has known that there will be among you those who are ill and others traveling throughout the land seeking [something] of the bounty of Allah and others fighting for the cause of Allah. So recite what is easy from it and establish prayer and give zakah and loan Allah a goodly loan. And whatever good you put forward for yourselves - you will find it with Allah. It is better and greater in reward. And seek forgiveness of Allah. Indeed, Allah is Forgiving and Merciful"}]},{"number":72,"name":"Al-Jinn","arabicName":"الجن","meaning":"The Jinn","minutes":5.8,"ayahs":[{"number":1,"arabic":"قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا","transliteration":"Qul oohiya ilayya annahu istamaAAa nafarun mina aljinni faqaloo inna samiAAna quranan AAajaban","english":"Say, [O Muhammad], \"It has been revealed to me that a group of the jinn listened and said, 'Indeed, we have heard an amazing Qur'an"},{"number":2,"arabic":"يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا","transliteration":"Yahdee ila alrrushdi faamanna bihi walan nushrika birabbina ahadan","english":"It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone"},{"number":3,"arabic":"وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةٗ وَلَا وَلَدٗا","transliteration":"Waannahu taAAala jaddu rabbina ma ittakhatha sahibatan wala waladan","english":"And [it teaches] that exalted is the nobleness of our Lord; He has not taken a wife or a son"},{"number":4,"arabic":"وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطٗا","transliteration":"Waannahu kana yaqoolu safeehuna AAala Allahi shatatan","english":"And that our foolish one has been saying about Allah an excessive transgression"},{"number":5,"arabic":"وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا","transliteration":"Waanna thananna an lan taqoola alinsu waaljinnu AAala Allahi kathiban","english":"And we had thought that mankind and the jinn would never speak about Allah a lie"},{"number":6,"arabic":"وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا","transliteration":"Waannahu kana rijalun mina alinsi yaAAoothoona birijalin mina aljinni fazadoohum rahaqan","english":"And there were men from mankind who sought refuge in men from the jinn, so they [only] increased them in burden"},{"number":7,"arabic":"وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدٗا","transliteration":"Waannahum thannoo kama thanantum an lan yabAAatha Allahu ahadan","english":"And they had thought, as you thought, that Allah would never send anyone [as a messenger]"},{"number":8,"arabic":"وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسٗا شَدِيدٗا وَشُهُبٗا","transliteration":"Waanna lamasna alssamaa fawajadnaha muliat harasan shadeedan washuhuban","english":"And we have sought [to reach] the heaven but found it filled with powerful guards and burning flames"},{"number":9,"arabic":"وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابٗا رَّصَدٗا","transliteration":"Waanna kunna naqAAudu minha maqaAAida lilssamAAi faman yastamiAAi alana yajid lahu shihaban rasadan","english":"And we used to sit therein in positions for hearing, but whoever listens now will find a burning flame lying in wait for him"},{"number":10,"arabic":"وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا","transliteration":"Waanna la nadree asharrun oreeda biman fee alardi am arada bihim rabbuhum rashadan","english":"And we do not know [therefore] whether evil is intended for those on earth or whether their Lord intends for them a right course"},{"number":11,"arabic":"وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا","transliteration":"Waanna minna alssalihoona waminna doona thalika kunna taraiqa qidadan","english":"And among us are the righteous, and among us are [others] not so; we were [of] divided ways"},{"number":12,"arabic":"وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبٗا","transliteration":"Wanna thananna an lan nuAAjiza Allaha fee alardi walan nuAAjizahu haraban","english":"And we have become certain that we will never cause failure to Allah upon earth, nor can we escape Him by flight"},{"number":13,"arabic":"وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا","transliteration":"Waanna lamma samiAAna alhuda amanna bihi faman yumin birabbihi fala yakhafu bakhsan wala rahaqan","english":"And when we heard the guidance, we believed in it. And whoever believes in his Lord will not fear deprivation or burden"},{"number":14,"arabic":"وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَـٰٓئِكَ تَحَرَّوۡاْ رَشَدٗا","transliteration":"Waanna minna almuslimoona waminna alqasitoona faman aslama faolaika taharraw rashadan","english":"And among us are Muslims [in submission to Allah], and among us are the unjust. And whoever has become Muslim - those have sought out the right course"},{"number":15,"arabic":"وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبٗا","transliteration":"Waama alqasitoona fakanoo lijahannama hataban","english":"But as for the unjust, they will be, for Hell, firewood"},{"number":16,"arabic":"وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا","transliteration":"Waallawi istaqamoo AAala alttareeqati laasqaynahum maan ghadaqan","english":"And [Allah revealed] that if they had remained straight on the way, We would have given them abundant provision"},{"number":17,"arabic":"لِّنَفۡتِنَهُمۡ فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابٗا صَعَدٗا","transliteration":"Linaftinahum feehi waman yuAArid AAan thikri rabbihi yaslukhu AAathaban saAAadan","english":"So We might test them therein. And whoever turns away from the remembrance of his Lord He will put into arduous punishment"},{"number":18,"arabic":"وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا","transliteration":"Waanna almasajida lillahi fala tadAAoo maAAa Allahi ahadan","english":"And [He revealed] that the masjids are for Allah, so do not invoke with Allah anyone"},{"number":19,"arabic":"وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدٗا","transliteration":"Waannahu lamma qama AAabdu Allahi yadAAoohu kadoo yakoonoona AAalayhi libadan","english":"And that when the Servant of Allah stood up supplicating Him, they almost became about him a compacted mass"},{"number":20,"arabic":"قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ بِهِۦٓ أَحَدٗا","transliteration":"Qul innama adAAoo rabbee wala oshriku bihi ahadan","english":"Say, [O Muhammad], \"I only invoke my Lord and do not associate with Him anyone"},{"number":21,"arabic":"قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا","transliteration":"Qul innee la amliku lakum darran wala rashadan","english":"Say, \"Indeed, I do not possess for you [the power of] harm or right direction"},{"number":22,"arabic":"قُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا","transliteration":"Qul innee lan yujeeranee mina Allahi ahadun walan ajida min doonihi multahadan","english":"Say, \"Indeed, there will never protect me from Allah anyone [if I should disobey], nor will I find in other than Him a refuge"},{"number":23,"arabic":"إِلَّا بَلَٰغٗا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا","transliteration":"Illa balaghan mina Allahi warisalatihi waman yaAAsi Allaha warasoolahu fainna lahu nara jahannama khalideena feeha abadan","english":"But [I have for you] only notification from Allah, and His messages.\" And whoever disobeys Allah and His Messenger - then indeed, for him is the fire of Hell; they will abide therein forever"},{"number":24,"arabic":"حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرٗا وَأَقَلُّ عَدَدٗا","transliteration":"Hatta itha raaw ma yooAAadoona fasayaAAlamoona man adAAafu nasiran waaqallu AAadadan","english":"[The disbelievers continue] until, when they see that which they are promised, then they will know who is weaker in helpers and less in number"},{"number":25,"arabic":"قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبٞ مَّا تُوعَدُونَ أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا","transliteration":"Qul in adree aqareebun ma tooAAadoona am yajAAalu lahu rabbee amadan","english":"Say, \"I do not know if what you are promised is near or if my Lord will grant for it a [long] period"},{"number":26,"arabic":"عَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ أَحَدًا","transliteration":"AAalimu alghaybi fala yuthhiru AAala ghaybihi ahadan","english":"[He is] Knower of the unseen, and He does not disclose His [knowledge of the] unseen to anyone"},{"number":27,"arabic":"إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولٖ فَإِنَّهُۥ يَسۡلُكُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدٗا","transliteration":"Illa mani irtada min rasoolin fainnahu yasluku min bayni yadayhi wamin khalfihi rasadan","english":"Except whom He has approved of messengers, and indeed, He sends before each messenger and behind him observers"},{"number":28,"arabic":"لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا","transliteration":"LiyaAAlama an qad ablaghoo risalati rabbihim waahata bima ladayhim waahsa kulla shayin AAadadan","english":"That he may know that they have conveyed the messages of their Lord; and He has encompassed whatever is with them and has enumerated all things in number"}]},{"number":71,"name":"Nuh","arabicName":"نوح","meaning":"Noah","minutes":5.1,"ayahs":[{"number":1,"arabic":"إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ","transliteration":"Inna arsalna noohan ila qawmihi an anthir qawmaka min qabli an yatiyahum AAathabun aleemun","english":"Indeed, We sent Noah to his people, [saying], \"Warn your people before there comes to them a painful punishment"},{"number":2,"arabic":"قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ","transliteration":"Qala ya qawmi innee lakum natheerun mubeenun","english":"He said, \"O my people, indeed I am to you a clear warner"},{"number":3,"arabic":"أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ","transliteration":"Ani oAAbudoo Allaha waittaqoohu waateeAAooni","english":"[Saying], 'Worship Allah, fear Him and obey me"},{"number":4,"arabic":"يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ","transliteration":"Yaghfir lakum min thunoobikum wayuakhkhirkum ila ajalin musamman inna ajala Allahi itha jaa la yuakhkharu law kuntum taAAlamoona","english":"Allah will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allah, when it comes, will not be delayed, if you only knew"},{"number":5,"arabic":"قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا","transliteration":"Qala rabbi innee daAAawtu qawmee laylan wanaharan","english":"He said, \"My Lord, indeed I invited my people [to truth] night and day"},{"number":6,"arabic":"فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا","transliteration":"Falam yazidhum duAAaee illa firaran","english":"But my invitation increased them not except in flight"},{"number":7,"arabic":"وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا","transliteration":"Wainnee kullama daAAawtuhum litaghfira lahum jaAAaloo asabiAAahum fee athanihim waistaghshaw thiyabahum waasarroo waistakbaroo istikbaran","english":"And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance"},{"number":8,"arabic":"ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا","transliteration":"Thumma innee daAAawtuhum jiharan","english":"Then I invited them publicly"},{"number":9,"arabic":"ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا","transliteration":"Thumma innee aAAlantu lahum waasrartu lahum israran","english":"Then I announced to them and [also] confided to them secretly"},{"number":10,"arabic":"فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا","transliteration":"Faqultu istaghfiroo rabbakum innahu kana ghaffaran","english":"And said, 'Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver"},{"number":11,"arabic":"يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا","transliteration":"Yursili alssamaa AAalaykum midraran","english":"He will send [rain from] the sky upon you in [continuing] showers"},{"number":12,"arabic":"وَيُمۡدِدۡكُم بِأَمۡوَٰلٖ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّـٰتٖ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرٗا","transliteration":"Wayumdidkum biamwalin wabaneena wayajAAal lakum jannatin wayajAAal lakum anharan","english":"And give you increase in wealth and children and provide for you gardens and provide for you rivers"},{"number":13,"arabic":"مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا","transliteration":"Ma lakum la tarjoona lillahi waqaran","english":"What is [the matter] with you that you do not attribute to Allah [due] grandeur"},{"number":14,"arabic":"وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا","transliteration":"Waqad khalaqakum atwaran","english":"While He has created you in stages"},{"number":15,"arabic":"أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا","transliteration":"Alam taraw kayfa khalaqa Allahu sabAAa samawatin tibaqan","english":"Do you not consider how Allah has created seven heavens in layers"},{"number":16,"arabic":"وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورٗا وَجَعَلَ ٱلشَّمۡسَ سِرَاجٗا","transliteration":"WajaAAala alqamara feehinna nooran wajaAAala alshshamsa sirajan","english":"And made the moon therein a [reflected] light and made the sun a burning lamp"},{"number":17,"arabic":"وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتٗا","transliteration":"WaAllahu anbatakum mina alardi nabatan","english":"And Allah has caused you to grow from the earth a [progressive] growth"},{"number":18,"arabic":"ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجٗا","transliteration":"Thumma yuAAeedukum feeha wayukhrijukum ikhrajan","english":"Then He will return you into it and extract you [another] extraction"},{"number":19,"arabic":"وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطٗا","transliteration":"WaAllahu jaAAala lakumu alarda bisatan","english":"And Allah has made for you the earth an expanse"},{"number":20,"arabic":"لِّتَسۡلُكُواْ مِنۡهَا سُبُلٗا فِجَاجٗا","transliteration":"Litaslukoo minha subulan fijajan","english":"That you may follow therein roads of passage"},{"number":21,"arabic":"قَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا","transliteration":"Qala noohun rabbi innahum AAasawnee waittabaAAoo man lam yazidhu maluhu wawaladuhu illa khasaran","english":"Noah said, \"My Lord, indeed they have disobeyed me and followed him whose wealth and children will not increase him except in loss"},{"number":22,"arabic":"وَمَكَرُواْ مَكۡرٗا كُبَّارٗا","transliteration":"Wamakaroo makran kubbaran","english":"And they conspired an immense conspiracy"},{"number":23,"arabic":"وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدّٗا وَلَا سُوَاعٗا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرٗا","transliteration":"Waqaloo la tatharunna alihatakum wala tatharunna waddan wala suwaAAan wala yaghootha wayaAAooqa wanasran","english":"And said, 'Never leave your gods and never leave Wadd or Suwa' or Yaghuth and Ya'uq and Nasr"},{"number":24,"arabic":"وَقَدۡ أَضَلُّواْ كَثِيرٗاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَٰلٗا","transliteration":"Waqad adalloo katheeran wala tazidi alththalimeena illa dalalan","english":"And already they have misled many. And, [my Lord], do not increase the wrongdoers except in error"},{"number":25,"arabic":"مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارٗا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارٗا","transliteration":"Mimma khateeatihim oghriqoo faodkhiloo naran falam yajidoo lahum min dooni Allahi ansaran","english":"Because of their sins they were drowned and put into the Fire, and they found not for themselves besides Allah [any] helpers"},{"number":26,"arabic":"وَقَالَ نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا","transliteration":"Waqala noohun rabbi la tathar AAala alardi mina alkafireena dayyaran","english":"And Noah said, \"My Lord, do not leave upon the earth from among the disbelievers an inhabitant"},{"number":27,"arabic":"إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا","transliteration":"Innaka in tatharhum yudilloo AAibadaka wala yalidoo illa fajiran kaffaran","english":"Indeed, if You leave them, they will mislead Your servants and not beget except [every] wicked one and [confirmed] disbeliever"},{"number":28,"arabic":"رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارَۢا","transliteration":"Rabbi ighfir lee waliwalidayya waliman dakhala baytiya muminan walilmumineena waalmuminati wala tazidi alththalimeena illa tabaran","english":"My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction"}]},{"number":70,"name":"Al-Ma'arij","arabicName":"المعارج","meaning":"The Ascending Stairways","minutes":5.1,"ayahs":[{"number":1,"arabic":"سَأَلَ سَآئِلُۢ بِعَذَابٖ وَاقِعٖ","transliteration":"Saala sailun biAAathabin waqiAAin","english":"A supplicant asked for a punishment bound to happen"},{"number":2,"arabic":"لِّلۡكَٰفِرِينَ لَيۡسَ لَهُۥ دَافِعٞ","transliteration":"Lilkafireena laysa lahu dafiAAun","english":"To the disbelievers; of it there is no preventer"},{"number":3,"arabic":"مِّنَ ٱللَّهِ ذِي ٱلۡمَعَارِجِ","transliteration":"Mina Allahi thee almaAAariji","english":"[It is] from Allah, owner of the ways of ascent"},{"number":4,"arabic":"تَعۡرُجُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥ خَمۡسِينَ أَلۡفَ سَنَةٖ","transliteration":"TaAAruju almalaikatu waalrroohu ilayhi fee yawmin kana miqdaruhu khamseena alfa sanatin","english":"The angels and the Spirit will ascend to Him during a Day the extent of which is fifty thousand years"},{"number":5,"arabic":"فَٱصۡبِرۡ صَبۡرٗا جَمِيلًا","transliteration":"Faisbir sabran jameelan","english":"So be patient with gracious patience"},{"number":6,"arabic":"إِنَّهُمۡ يَرَوۡنَهُۥ بَعِيدٗا","transliteration":"Innahum yarawnahu baAAeedan","english":"Indeed, they see it [as] distant"},{"number":7,"arabic":"وَنَرَىٰهُ قَرِيبٗا","transliteration":"Wanarahu qareeban","english":"But We see it [as] near"},{"number":8,"arabic":"يَوۡمَ تَكُونُ ٱلسَّمَآءُ كَٱلۡمُهۡلِ","transliteration":"Yawma takoonu alssamao kaalmuhli","english":"On the Day the sky will be like murky oil"},{"number":9,"arabic":"وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ","transliteration":"Watakoonu aljibalu kaalAAihni","english":"And the mountains will be like wool"},{"number":10,"arabic":"وَلَا يَسۡـَٔلُ حَمِيمٌ حَمِيمٗا","transliteration":"Wala yasalu hameemun hameeman","english":"And no friend will ask [anything of] a friend"},{"number":11,"arabic":"يُبَصَّرُونَهُمۡۚ يَوَدُّ ٱلۡمُجۡرِمُ لَوۡ يَفۡتَدِي مِنۡ عَذَابِ يَوۡمِئِذِۭ بِبَنِيهِ","transliteration":"Yubassaroonahum yawaddu almujrimu law yaftadee min AAathabi yawmiithin bibaneehi","english":"They will be shown each other. The criminal will wish that he could be ransomed from the punishment of that Day by his children"},{"number":12,"arabic":"وَصَٰحِبَتِهِۦ وَأَخِيهِ","transliteration":"Wasahibatihi waakheehi","english":"And his wife and his brother"},{"number":13,"arabic":"وَفَصِيلَتِهِ ٱلَّتِي تُـٔۡوِيهِ","transliteration":"Wafaseelatihi allatee tuweehi","english":"And his nearest kindred who shelter him"},{"number":14,"arabic":"وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ يُنجِيهِ","transliteration":"Waman fee alardi jameeAAan thumma yunjeehi","english":"And whoever is on earth entirely [so] then it could save him"},{"number":15,"arabic":"كَلَّآۖ إِنَّهَا لَظَىٰ","transliteration":"Kalla innaha latha","english":"No! Indeed, it is the Flame [of Hell]"},{"number":16,"arabic":"نَزَّاعَةٗ لِّلشَّوَىٰ","transliteration":"NazzaAAatan lilshshawa","english":"A remover of exteriors"},{"number":17,"arabic":"تَدۡعُواْ مَنۡ أَدۡبَرَ وَتَوَلَّىٰ","transliteration":"TadAAoo man adbara watawalla","english":"It invites he who turned his back [on truth] and went away [from obedience]"},{"number":18,"arabic":"وَجَمَعَ فَأَوۡعَىٰٓ","transliteration":"WajamaAAa faawAAa","english":"And collected [wealth] and hoarded"},{"number":19,"arabic":"۞إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا","transliteration":"Inna alinsana khuliqa halooAAan","english":"Indeed, mankind was created anxious"},{"number":20,"arabic":"إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا","transliteration":"Itha massahu alshsharru jazooAAan","english":"When evil touches him, impatient"},{"number":21,"arabic":"وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا","transliteration":"Waitha massahu alkhayru manooAAan","english":"And when good touches him, withholding [of it]"},{"number":22,"arabic":"إِلَّا ٱلۡمُصَلِّينَ","transliteration":"Illa almusalleena","english":"Except the observers of prayer"},{"number":23,"arabic":"ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ","transliteration":"Allatheena hum AAala salatihim daimoona","english":"Those who are constant in their prayer"},{"number":24,"arabic":"وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ","transliteration":"Waallatheena fee amwalihim haqqun maAAloomun","english":"And those within whose wealth is a known right"},{"number":25,"arabic":"لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","transliteration":"Lilssaili waalmahroomi","english":"For the petitioner and the deprived"},{"number":26,"arabic":"وَٱلَّذِينَ يُصَدِّقُونَ بِيَوۡمِ ٱلدِّينِ","transliteration":"Waallatheena yusaddiqoona biyawmi alddeeni","english":"And those who believe in the Day of Recompense"},{"number":27,"arabic":"وَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ","transliteration":"Waallatheena hum min AAathabi rabbihim mushfiqoona","english":"And those who are fearful of the punishment of their Lord"},{"number":28,"arabic":"إِنَّ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡمُونٖ","transliteration":"Inna AAathaba rabbihim ghayru mamoonin","english":"Indeed, the punishment of their Lord is not that from which one is safe"},{"number":29,"arabic":"وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ","transliteration":"Waallatheena hum lifuroojihim hafithoona","english":"And those who guard their private parts"},{"number":30,"arabic":"إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ","transliteration":"Illa AAala azwajihim aw ma malakat aymanuhum fainnahum ghayru maloomeena","english":"Except from their wives or those their right hands possess, for indeed, they are not to be blamed"},{"number":31,"arabic":"فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡعَادُونَ","transliteration":"Famani ibtagha waraa thalika faolaika humu alAAadoona","english":"But whoever seeks beyond that, then they are the transgressors"},{"number":32,"arabic":"وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","transliteration":"Waallatheena hum liamanatihim waAAahdihim raAAoona","english":"And those who are to their trusts and promises attentive"},{"number":33,"arabic":"وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ","transliteration":"Waallatheena hum bishahadatihim qaimoona","english":"And those who are in their testimonies upright"},{"number":34,"arabic":"وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ","transliteration":"Waallatheena hum AAala salatihim yuhafithoona","english":"And those who [carefully] maintain their prayer"},{"number":35,"arabic":"أُوْلَـٰٓئِكَ فِي جَنَّـٰتٖ مُّكۡرَمُونَ","transliteration":"Olaika fee jannatin mukramoona","english":"They will be in gardens, honored"},{"number":36,"arabic":"فَمَالِ ٱلَّذِينَ كَفَرُواْ قِبَلَكَ مُهۡطِعِينَ","transliteration":"Famali allatheena kafaroo qibalaka muhtiAAeena","english":"So what is [the matter] with those who disbelieve, hastening [from] before you, [O Muhammad]"},{"number":37,"arabic":"عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ","transliteration":"AAani alyameeni waAAani alshshimali AAizeena","english":"[To sit] on [your] right and [your] left in separate groups"},{"number":38,"arabic":"أَيَطۡمَعُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُدۡخَلَ جَنَّةَ نَعِيمٖ","transliteration":"AyatmaAAu kullu imriin minhum an yudkhala jannata naAAeemin","english":"Does every person among them aspire to enter a garden of pleasure"},{"number":39,"arabic":"كَلَّآۖ إِنَّا خَلَقۡنَٰهُم مِّمَّا يَعۡلَمُونَ","transliteration":"Kalla inna khalaqnahum mimma yaAAlamoona","english":"No! Indeed, We have created them from that which they know"},{"number":40,"arabic":"فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ","transliteration":"Fala oqsimu birabbi almashariqi waalmagharibi inna laqadiroona","english":"So I swear by the Lord of [all] risings and settings that indeed We are able"},{"number":41,"arabic":"عَلَىٰٓ أَن نُّبَدِّلَ خَيۡرٗا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِينَ","transliteration":"AAala an nubaddila khayran minhum wama nahnu bimasbooqeena","english":"To replace them with better than them; and We are not to be outdone"},{"number":42,"arabic":"فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ","transliteration":"Fatharhum yakhoodoo wayalAAaboo hatta yulaqoo yawmahumu allathee yooAAadoona","english":"So leave them to converse vainly and amuse themselves until they meet their Day which they are promised"},{"number":43,"arabic":"يَوۡمَ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعٗا كَأَنَّهُمۡ إِلَىٰ نُصُبٖ يُوفِضُونَ","transliteration":"Yawma yakhrujoona mina alajdathi siraAAan kaannahum ila nusubin yoofidoona","english":"The Day they will emerge from the graves rapidly as if they were, toward an erected idol, hastening"},{"number":44,"arabic":"خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۚ ذَٰلِكَ ٱلۡيَوۡمُ ٱلَّذِي كَانُواْ يُوعَدُونَ","transliteration":"KhashiAAatan absaruhum tarhaquhum thillatun thalika alyawmu allathee kanoo yooAAadoona","english":"Their eyes humbled, humiliation will cover them. That is the Day which they had been promised"}]},{"number":69,"name":"Al-Haqqah","arabicName":"الحاقة","meaning":"The Reality","minutes":5.9,"ayahs":[{"number":1,"arabic":"ٱلۡحَآقَّةُ","transliteration":"Alhaqqatu","english":"The Inevitable Reality"},{"number":2,"arabic":"مَا ٱلۡحَآقَّةُ","transliteration":"Ma alhaqqatu","english":"What is the Inevitable Reality"},{"number":3,"arabic":"وَمَآ أَدۡرَىٰكَ مَا ٱلۡحَآقَّةُ","transliteration":"Wama adraka ma alhaqqatu","english":"And what can make you know what is the Inevitable Reality"},{"number":4,"arabic":"كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ","transliteration":"Kaththabat thamoodu waAAadun bialqariAAati","english":"Thamud and 'Aad denied the Striking Calamity"},{"number":5,"arabic":"فَأَمَّا ثَمُودُ فَأُهۡلِكُواْ بِٱلطَّاغِيَةِ","transliteration":"Faamma thamoodu faohlikoo bialttaghiyati","english":"So as for Thamud, they were destroyed by the overpowering [blast]"},{"number":6,"arabic":"وَأَمَّا عَادٞ فَأُهۡلِكُواْ بِرِيحٖ صَرۡصَرٍ عَاتِيَةٖ","transliteration":"Waamma AAadun faohlikoo bireehin sarsarin AAatiyatin","english":"And as for 'Aad, they were destroyed by a screaming, violent wind"},{"number":7,"arabic":"سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومٗاۖ فَتَرَى ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٖ","transliteration":"Sakhkharaha AAalayhim sabAAa layalin wathamaniyata ayyamin husooman fatara alqawma feeha sarAAa kaannahum aAAjazu nakhlin khawiyatun","english":"Which Allah imposed upon them for seven nights and eight days in succession, so you would see the people therein fallen as if they were hollow trunks of palm trees"},{"number":8,"arabic":"فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖ","transliteration":"Fahal tara lahum min baqiyatin","english":"Then do you see of them any remains"},{"number":9,"arabic":"وَجَآءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَٰتُ بِٱلۡخَاطِئَةِ","transliteration":"Wajaa firAAawnu waman qablahu waalmutafikatu bialkhatiati","english":"And there came Pharaoh and those before him and the overturned cities with sin"},{"number":10,"arabic":"فَعَصَوۡاْ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةٗ رَّابِيَةً","transliteration":"FaAAasaw rasoola rabbihim faakhathahum akhthatan rabiyatan","english":"And they disobeyed the messenger of their Lord, so He seized them with a seizure exceeding [in severity]"},{"number":11,"arabic":"إِنَّا لَمَّا طَغَا ٱلۡمَآءُ حَمَلۡنَٰكُمۡ فِي ٱلۡجَارِيَةِ","transliteration":"Inna lamma tagha almao hamalnakum fee aljariyati","english":"Indeed, when the water overflowed, We carried your ancestors in the sailing ship"},{"number":12,"arabic":"لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةٗ وَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ","transliteration":"LinajAAalaha lakum tathkiratan wataAAiyaha othunun waAAiyatun","english":"That We might make it for you a reminder and [that] a conscious ear would be conscious of it"},{"number":13,"arabic":"فَإِذَا نُفِخَ فِي ٱلصُّورِ نَفۡخَةٞ وَٰحِدَةٞ","transliteration":"Faitha nufikha fee alssoori nafkhatun wahidatun","english":"Then when the Horn is blown with one blast"},{"number":14,"arabic":"وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةٗ وَٰحِدَةٗ","transliteration":"Wahumilati alardu waaljibalu fadukkata dakkatan wahidatan","english":"And the earth and the mountains are lifted and leveled with one blow"},{"number":15,"arabic":"فَيَوۡمَئِذٖ وَقَعَتِ ٱلۡوَاقِعَةُ","transliteration":"Fayawmaithin waqaAAati alwaqiAAatu","english":"Then on that Day, the Resurrection will occur"},{"number":16,"arabic":"وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِيَ يَوۡمَئِذٖ وَاهِيَةٞ","transliteration":"Wainshaqqati alssamao fahiya yawmaithin wahiyatun","english":"And the heaven will split [open], for that Day it is infirm"},{"number":17,"arabic":"وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَاۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِذٖ ثَمَٰنِيَةٞ","transliteration":"Waalmalaku AAala arjaiha wayahmilu AAarsha rabbika fawqahum yawmaithin thamaniyatun","english":"And the angels are at its edges. And there will bear the Throne of your Lord above them, that Day, eight [of them]"},{"number":18,"arabic":"يَوۡمَئِذٖ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِيَةٞ","transliteration":"Yawmaithin tuAAradoona la takhfa minkum khafiyatun","english":"That Day, you will be exhibited [for judgement]; not hidden among you is anything concealed"},{"number":19,"arabic":"فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقۡرَءُواْ كِتَٰبِيَهۡ","transliteration":"Faamma man ootiya kitabahu biyameenihi fayaqoolu haomu iqraoo kitabiyah","english":"So as for he who is given his record in his right hand, he will say, \"Here, read my record"},{"number":20,"arabic":"إِنِّي ظَنَنتُ أَنِّي مُلَٰقٍ حِسَابِيَهۡ","transliteration":"Innee thanantu annee mulaqin hisabiyah","english":"Indeed, I was certain that I would be meeting my account"},{"number":21,"arabic":"فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ","transliteration":"Fahuwa fee AAeeshatin radiyatin","english":"So he will be in a pleasant life"},{"number":22,"arabic":"فِي جَنَّةٍ عَالِيَةٖ","transliteration":"Fee jannatin AAaliyatin","english":"In an elevated garden"},{"number":23,"arabic":"قُطُوفُهَا دَانِيَةٞ","transliteration":"Qutoofuha daniyatun","english":"Its [fruit] to be picked hanging near"},{"number":24,"arabic":"كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ","transliteration":"Kuloo waishraboo haneean bima aslaftum fee alayyami alkhaliyati","english":"[They will be told], \"Eat and drink in satisfaction for what you put forth in the days past"},{"number":25,"arabic":"وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ","transliteration":"Waamma man ootiya kitabahu bishimalihi fayaqoolu ya laytanee lam oota kitabiyah","english":"But as for he who is given his record in his left hand, he will say, \"Oh, I wish I had not been given my record"},{"number":26,"arabic":"وَلَمۡ أَدۡرِ مَا حِسَابِيَهۡ","transliteration":"Walam adri ma hisabiyah","english":"And had not known what is my account"},{"number":27,"arabic":"يَٰلَيۡتَهَا كَانَتِ ٱلۡقَاضِيَةَ","transliteration":"Ya laytaha kanati alqadiyatu","english":"I wish my death had been the decisive one"},{"number":28,"arabic":"مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ","transliteration":"Ma aghna AAannee maliyah","english":"My wealth has not availed me"},{"number":29,"arabic":"هَلَكَ عَنِّي سُلۡطَٰنِيَهۡ","transliteration":"Halaka AAannee sultaniyah","english":"Gone from me is my authority"},{"number":30,"arabic":"خُذُوهُ فَغُلُّوهُ","transliteration":"Khuthoohu faghulloohu","english":"[Allah will say], \"Seize him and shackle him"},{"number":31,"arabic":"ثُمَّ ٱلۡجَحِيمَ صَلُّوهُ","transliteration":"Thumma aljaheema salloohu","english":"Then into Hellfire drive him"},{"number":32,"arabic":"ثُمَّ فِي سِلۡسِلَةٖ ذَرۡعُهَا سَبۡعُونَ ذِرَاعٗا فَٱسۡلُكُوهُ","transliteration":"Thumma fee silsilatin tharAAuha sabAAoona thiraAAan faoslukoohu","english":"Then into a chain whose length is seventy cubits insert him"},{"number":33,"arabic":"إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ","transliteration":"Innahu kana la yuminu biAllahi alAAatheemi","english":"Indeed, he did not used to believe in Allah, the Most Great"},{"number":34,"arabic":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","transliteration":"Wala yahuddu AAala taAAami almiskeeni","english":"Nor did he encourage the feeding of the poor"},{"number":35,"arabic":"فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ","transliteration":"Falaysa lahu alyawma hahuna hameemun","english":"So there is not for him here this Day any devoted friend"},{"number":36,"arabic":"وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينٖ","transliteration":"Wala taAAamun illa min ghisleenin","english":"Nor any food except from the discharge of wounds"},{"number":37,"arabic":"لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ","transliteration":"La yakuluhu illa alkhatioona","english":"None will eat it except the sinners"},{"number":38,"arabic":"فَلَآ أُقۡسِمُ بِمَا تُبۡصِرُونَ","transliteration":"Fala oqsimu bima tubsiroona","english":"So I swear by what you see"},{"number":39,"arabic":"وَمَا لَا تُبۡصِرُونَ","transliteration":"Wama la tubsiroona","english":"And what you do not see"},{"number":40,"arabic":"إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ","transliteration":"Innahu laqawlu rasoolin kareemin","english":"[That] indeed, the Qur'an is the word of a noble Messenger"},{"number":41,"arabic":"وَمَا هُوَ بِقَوۡلِ شَاعِرٖۚ قَلِيلٗا مَّا تُؤۡمِنُونَ","transliteration":"Wama huwa biqawli shaAAirin qaleelan ma tuminoona","english":"And it is not the word of a poet; little do you believe"},{"number":42,"arabic":"وَلَا بِقَوۡلِ كَاهِنٖۚ قَلِيلٗا مَّا تَذَكَّرُونَ","transliteration":"Wala biqawli kahinin qaleelan ma tathakkaroona","english":"Nor the word of a soothsayer; little do you remember"},{"number":43,"arabic":"تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ","transliteration":"Tanzeelun min rabbi alAAalameena","english":"[It is] a revelation from the Lord of the worlds"},{"number":44,"arabic":"وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ","transliteration":"Walaw taqawwala AAalayna baAAda alaqaweeli","english":"And if Muhammad had made up about Us some [false] sayings"},{"number":45,"arabic":"لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ","transliteration":"Laakhathna minhu bialyameeni","english":"We would have seized him by the right hand"},{"number":46,"arabic":"ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِينَ","transliteration":"Thumma laqataAAna minhu alwateena","english":"Then We would have cut from him the aorta"},{"number":47,"arabic":"فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَٰجِزِينَ","transliteration":"Fama minkum min ahadin AAanhu hajizeena","english":"And there is no one of you who could prevent [Us] from him"},{"number":48,"arabic":"وَإِنَّهُۥ لَتَذۡكِرَةٞ لِّلۡمُتَّقِينَ","transliteration":"Wainnahu latathkiratun lilmuttaqeena","english":"And indeed, the Qur'an is a reminder for the righteous"},{"number":49,"arabic":"وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ","transliteration":"Wainna lanaAAlamu anna minkum mukaththibeena","english":"And indeed, We know that among you are deniers"},{"number":50,"arabic":"وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَٰفِرِينَ","transliteration":"Wainnahu lahasratun AAala alkafireena","english":"And indeed, it will be [a cause of] regret upon the disbelievers"},{"number":51,"arabic":"وَإِنَّهُۥ لَحَقُّ ٱلۡيَقِينِ","transliteration":"Wainnahu lahaqqu alyaqeeni","english":"And indeed, it is the truth of certainty"},{"number":52,"arabic":"فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ","transliteration":"Fasabbih biismi rabbika alAAatheemi","english":"So exalt the name of your Lord, the Most Great"}]},{"number":68,"name":"Al-Qalam","arabicName":"القلم","meaning":"The Pen","minutes":6.7,"ayahs":[{"number":1,"arabic":"نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ","transliteration":"Noon waalqalami wama yasturoona","english":"Nun. By the pen and what they inscribe"},{"number":2,"arabic":"مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونٖ","transliteration":"Ma anta biniAAmati rabbika bimajnoonin","english":"You are not, [O Muhammad], by the favor of your Lord, a madman"},{"number":3,"arabic":"وَإِنَّ لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونٖ","transliteration":"Wainna laka laajran ghayra mamnoonin","english":"And indeed, for you is a reward uninterrupted"},{"number":4,"arabic":"وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖ","transliteration":"Wainnaka laAAala khuluqin AAatheemin","english":"And indeed, you are of a great moral character"},{"number":5,"arabic":"فَسَتُبۡصِرُ وَيُبۡصِرُونَ","transliteration":"Fasatubsiru wayubsiroona","english":"So you will see and they will see"},{"number":6,"arabic":"بِأَييِّكُمُ ٱلۡمَفۡتُونُ","transliteration":"Biayyikumu almaftoonu","english":"Which of you is the afflicted [by a devil]"},{"number":7,"arabic":"إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","transliteration":"Inna rabbaka huwa aAAlamu biman dalla AAan sabeelihi wahuwa aAAlamu bialmuhtadeena","english":"Indeed, your Lord is most knowing of who has gone astray from His way, and He is most knowing of the [rightly] guided"},{"number":8,"arabic":"فَلَا تُطِعِ ٱلۡمُكَذِّبِينَ","transliteration":"Fala tutiAAi almukaththibeena","english":"Then do not obey the deniers"},{"number":9,"arabic":"وَدُّواْ لَوۡ تُدۡهِنُ فَيُدۡهِنُونَ","transliteration":"Waddoo law tudhinu fayudhinoona","english":"They wish that you would soften [in your position], so they would soften [toward you]"},{"number":10,"arabic":"وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ","transliteration":"Wala tutiAA kulla hallafin maheenin","english":"And do not obey every worthless habitual swearer"},{"number":11,"arabic":"هَمَّازٖ مَّشَّآءِۭ بِنَمِيمٖ","transliteration":"Hammazin mashshain binameemin","english":"[And] scorner, going about with malicious gossip"},{"number":12,"arabic":"مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٍ أَثِيمٍ","transliteration":"MannaAAin lilkhayri muAAtadin atheemin","english":"A preventer of good, transgressing and sinful"},{"number":13,"arabic":"عُتُلِّۭ بَعۡدَ ذَٰلِكَ زَنِيمٍ","transliteration":"AAutullin baAAda thalika zaneemin","english":"Cruel, moreover, and an illegitimate pretender"},{"number":14,"arabic":"أَن كَانَ ذَا مَالٖ وَبَنِينَ","transliteration":"An kana tha malin wabaneena","english":"Because he is a possessor of wealth and children"},{"number":15,"arabic":"إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","transliteration":"Itha tutla AAalayhi ayatuna qala asateeru alawwaleena","english":"When Our verses are recited to him, he says, \"Legends of the former peoples"},{"number":16,"arabic":"سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ","transliteration":"Sanasimuhu AAala alkhurtoomi","english":"We will brand him upon the snout"},{"number":17,"arabic":"إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ","transliteration":"Inna balawnahum kama balawna ashaba aljannati ith aqsamoo layasrimunnaha musbiheena","english":"Indeed, We have tried them as We tried the companions of the garden, when they swore to cut its fruit in the [early] morning"},{"number":18,"arabic":"وَلَا يَسۡتَثۡنُونَ","transliteration":"Wala yastathnoona","english":"Without making exception"},{"number":19,"arabic":"فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ","transliteration":"Fatafa AAalayha taifun min rabbika wahum naimoona","english":"So there came upon the garden an affliction from your Lord while they were asleep"},{"number":20,"arabic":"فَأَصۡبَحَتۡ كَٱلصَّرِيمِ","transliteration":"Faasbahat kaalssareemi","english":"And it became as though reaped"},{"number":21,"arabic":"فَتَنَادَوۡاْ مُصۡبِحِينَ","transliteration":"Fatanadaw musbiheena","english":"And they called one another at morning"},{"number":22,"arabic":"أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ","transliteration":"Ani ighdoo AAala harthikum in kuntum sarimeena","english":"[Saying], \"Go early to your crop if you would cut the fruit"},{"number":23,"arabic":"فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ","transliteration":"Faintalaqoo wahum yatakhafatoona","english":"So they set out, while lowering their voices"},{"number":24,"arabic":"أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ","transliteration":"An la yadkhulannaha alyawma AAalaykum miskeenun","english":"[Saying], \"There will surely not enter it today upon you [any] poor person"},{"number":25,"arabic":"وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ","transliteration":"Waghadaw AAala hardin qadireena","english":"And they went early in determination, [assuming themselves] able"},{"number":26,"arabic":"فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ","transliteration":"Falamma raawha qaloo inna ladalloona","english":"But when they saw it, they said, \"Indeed, we are lost"},{"number":27,"arabic":"بَلۡ نَحۡنُ مَحۡرُومُونَ","transliteration":"Bal nahnu mahroomoona","english":"Rather, we have been deprived"},{"number":28,"arabic":"قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ","transliteration":"Qala awsatuhum alam aqul lakum lawla tusabbihoona","english":"The most moderate of them said, \"Did I not say to you, 'Why do you not exalt [Allah]"},{"number":29,"arabic":"قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ","transliteration":"Qaloo subhana rabbina inna kunna thalimeena","english":"They said, \"Exalted is our Lord! Indeed, we were wrongdoers"},{"number":30,"arabic":"فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ","transliteration":"Faaqbala baAAduhum AAala baAAdin yatalawamoona","english":"Then they approached one another, blaming each other"},{"number":31,"arabic":"قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ","transliteration":"Qaloo ya waylana inna kunna tagheena","english":"They said, \"O woe to us; indeed we were transgressors"},{"number":32,"arabic":"عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ","transliteration":"AAasa rabbuna an yubdilana khayran minha inna ila rabbina raghiboona","english":"Perhaps our Lord will substitute for us [one] better than it. Indeed, we are toward our Lord desirous"},{"number":33,"arabic":"كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ","transliteration":"Kathalika alAAathabu walaAAathabu alakhirati akbaru law kanoo yaAAlamoona","english":"Such is the punishment [of this world]. And the punishment of the Hereafter is greater, if they only knew"},{"number":34,"arabic":"إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِيمِ","transliteration":"Inna lilmuttaqeena AAinda rabbihim jannati alnnaAAeemi","english":"Indeed, for the righteous with their Lord are the Gardens of Pleasure"},{"number":35,"arabic":"أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ","transliteration":"AfanajAAalu almuslimeena kaalmujrimeena","english":"Then will We treat the Muslims like the criminals"},{"number":36,"arabic":"مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ","transliteration":"Ma lakum kayfa tahkumoona","english":"What is [the matter] with you? How do you judge"},{"number":37,"arabic":"أَمۡ لَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ","transliteration":"Am lakum kitabun feehi tadrusoona","english":"Or do you have a scripture in which you learn"},{"number":38,"arabic":"إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ","transliteration":"Inna lakum feehi lama takhayyaroona","english":"That indeed for you is whatever you choose"},{"number":39,"arabic":"أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ","transliteration":"Am lakum aymanun AAalayna balighatun ila yawmi alqiyamati inna lakum lama tahkumoona","english":"Or do you have oaths [binding] upon Us, extending until the Day of Resurrection, that indeed for you is whatever you judge"},{"number":40,"arabic":"سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ زَعِيمٌ","transliteration":"Salhum ayyuhum bithalika zaAAeemun","english":"Ask them which of them, for that [claim], is responsible"},{"number":41,"arabic":"أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ","transliteration":"Am lahum shurakao falyatoo bishurakaihim in kanoo sadiqeena","english":"Or do they have partners? Then let them bring their partners, if they should be truthful"},{"number":42,"arabic":"يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ","transliteration":"Yawma yukshafu AAan saqin wayudAAawna ila alssujoodi fala yastateeAAoona","english":"The Day the shin will be uncovered and they are invited to prostration but the disbelievers will not be able"},{"number":43,"arabic":"خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ","transliteration":"KhashiAAatan absaruhum tarhaquhum thillatun waqad kanoo yudAAawna ila alssujoodi wahum salimoona","english":"Their eyes humbled, humiliation will cover them. And they used to be invited to prostration while they were sound"},{"number":44,"arabic":"فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ","transliteration":"Fatharnee waman yukaththibu bihatha alhadeethi sanastadrijuhum min haythu la yaAAlamoona","english":"So leave Me, [O Muhammad], with [the matter of] whoever denies the Qur'an. We will progressively lead them [to punishment] from where they do not know"},{"number":45,"arabic":"وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ","transliteration":"Waomlee lahum inna kaydee mateenun","english":"And I will give them time. Indeed, My plan is firm"},{"number":46,"arabic":"أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ","transliteration":"Am tasaluhum ajran fahum min maghramin muthqaloona","english":"Or do you ask of them a payment, so they are by debt burdened down"},{"number":47,"arabic":"أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ","transliteration":"Am AAindahumu alghaybu fahum yaktuboona","english":"Or have they [knowledge of] the unseen, so they write [it] down"},{"number":48,"arabic":"فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ","transliteration":"Faisbir lihukmi rabbika wala takun kasahibi alhooti ith nada wahuwa makthoomun","english":"Then be patient for the decision of your Lord, [O Muhammad], and be not like the companion of the fish when he called out while he was distressed"},{"number":49,"arabic":"لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ","transliteration":"Lawla an tadarakahu niAAmatun min rabbihi lanubitha bialAAarai wahuwa mathmoomun","english":"If not that a favor from his Lord overtook him, he would have been thrown onto the naked shore while he was censured"},{"number":50,"arabic":"فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِينَ","transliteration":"Faijtabahu rabbuhu fajaAAalahu mina alssaliheena","english":"And his Lord chose him and made him of the righteous"},{"number":51,"arabic":"وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ","transliteration":"Wain yakadu allatheena kafaroo layuzliqoonaka biabsarihim lamma samiAAoo alththikra wayaqooloona innahu lamajnoonun","english":"And indeed, those who disbelieve would almost make you slip with their eyes when they hear the message, and they say, \"Indeed, he is mad"},{"number":52,"arabic":"وَمَا هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ","transliteration":"Wama huwa illa thikrun lilAAalameena","english":"But it is not except a reminder to the worlds"}]},{"number":67,"name":"Al-Mulk","arabicName":"الملك","meaning":"The Sovereignty","minutes":7.0,"ayahs":[{"number":1,"arabic":"تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","transliteration":"Tabaraka allathee biyadihi almulku wahuwa AAala kulli shayin qadeerun","english":"Blessed is He in whose hand is dominion, and He is over all things competent"},{"number":2,"arabic":"ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ","transliteration":"Allathee khalaqa almawta waalhayata liyabluwakum ayyukum ahsanu AAamalan wahuwa alAAazeezu alghafooru","english":"[He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving"},{"number":3,"arabic":"ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن تَفَٰوُتٖۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورٖ","transliteration":"Allathee khalaqa sabAAa samawatin tibaqan ma tara fee khalqi alrrahmani min tafawutin fairjiAAi albasara hal tara min futoorin","english":"[And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks"},{"number":4,"arabic":"ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ","transliteration":"Thumma irjiAAi albasara karratayni yanqalib ilayka albasaru khasian wahuwa haseerun","english":"Then return [your] vision twice again. [Your] vision will return to you humbled while it is fatigued"},{"number":5,"arabic":"وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ","transliteration":"Walaqad zayyanna alssamaa alddunya bimasabeeha wajaAAalnaha rujooman lilshshayateeni waaAAtadna lahum AAathaba alssaAAeeri","english":"And We have certainly beautified the nearest heaven with stars and have made [from] them what is thrown at the devils and have prepared for them the punishment of the Blaze"},{"number":6,"arabic":"وَلِلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِيرُ","transliteration":"Walillatheena kafaroo birabbihim AAathabu jahannama wabisa almaseeru","english":"And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination"},{"number":7,"arabic":"إِذَآ أُلۡقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقٗا وَهِيَ تَفُورُ","transliteration":"Itha olqoo feeha samiAAoo laha shaheeqan wahiya tafooru","english":"When they are thrown into it, they hear from it a [dreadful] inhaling while it boils up"},{"number":8,"arabic":"تَكَادُ تَمَيَّزُ مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجٞ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرٞ","transliteration":"Takadu tamayyazu mina alghaythi kullama olqiya feeha fawjun saalahum khazanatuha alam yatikum natheerun","english":"It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, \"Did there not come to you a warner"},{"number":9,"arabic":"قَالُواْ بَلَىٰ قَدۡ جَآءَنَا نَذِيرٞ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ كَبِيرٖ","transliteration":"Qaloo bala qad jaana natheerun fakaththabna waqulna ma nazzala Allahu min shayin in antum illa fee dalalin kabeerin","english":"They will say,\" Yes, a warner had come to us, but we denied and said, 'Allah has not sent down anything. You are not but in great error"},{"number":10,"arabic":"وَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ ٱلسَّعِيرِ","transliteration":"Waqaloo law kunna nasmaAAu aw naAAqilu ma kunna fee ashabi alssaAAeeri","english":"And they will say, \"If only we had been listening or reasoning, we would not be among the companions of the Blaze"},{"number":11,"arabic":"فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقٗا لِّأَصۡحَٰبِ ٱلسَّعِيرِ","transliteration":"FaiAAtarafoo bithanbihim fasuhqan liashabi alssaAAeeri","english":"And they will admit their sin, so [it is] alienation for the companions of the Blaze"},{"number":12,"arabic":"إِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ","transliteration":"Inna allatheena yakhshawna rabbahum bialghaybi lahum maghfiratun waajrun kabeerun","english":"Indeed, those who fear their Lord unseen will have forgiveness and great reward"},{"number":13,"arabic":"وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","transliteration":"Waasirroo qawlakum awi ijharoo bihi innahu AAaleemun bithati alssudoori","english":"And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts"},{"number":14,"arabic":"أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ","transliteration":"Ala yaAAlamu man khalaqa wahuwa allateefu alkhabeeru","english":"Does He who created not know, while He is the Subtle, the Acquainted"},{"number":15,"arabic":"هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ","transliteration":"Huwa allathee jaAAala lakumu alarda thaloolan faimshoo fee manakibiha wakuloo min rizqihi wailayhi alnnushooru","english":"It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection"},{"number":16,"arabic":"ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ","transliteration":"Aamintum man fee alssamai an yakhsifa bikumu alarda faitha hiya tamooru","english":"Do you feel secure that He who [holds authority] in the heaven would not cause the earth to swallow you and suddenly it would sway"},{"number":17,"arabic":"أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗاۖ فَسَتَعۡلَمُونَ كَيۡفَ نَذِيرِ","transliteration":"Am amintum man fee alssamai an yursila AAalaykum hasiban fasataAAlamoona kayfa natheeri","english":"Or do you feel secure that He who [holds authority] in the heaven would not send against you a storm of stones? Then you would know how [severe] was My warning"},{"number":18,"arabic":"وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ كَانَ نَكِيرِ","transliteration":"Walaqad kaththaba allatheena min qablihim fakayfa kana nakeeri","english":"And already had those before them denied, and how [terrible] was My reproach"},{"number":19,"arabic":"أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَـٰٓفَّـٰتٖ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ","transliteration":"Awalam yaraw ila alttayri fawqahum saffatin wayaqbidna ma yumsikuhunna illa alrrahmanu innahu bikulli shayin baseerun","english":"Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing"},{"number":20,"arabic":"أَمَّنۡ هَٰذَا ٱلَّذِي هُوَ جُندٞ لَّكُمۡ يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ","transliteration":"Amman hatha allathee huwa jundun lakum yansurukum min dooni alrrahmani ini alkafiroona illa fee ghuroorin","english":"Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion"},{"number":21,"arabic":"أَمَّنۡ هَٰذَا ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوّٖ وَنُفُورٍ","transliteration":"Amman hatha allathee yarzuqukum in amsaka rizqahu bal lajjoo fee AAutuwwin wanufoorin","english":"Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion"},{"number":22,"arabic":"أَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","transliteration":"Afaman yamshee mukibban AAala wajhihi ahda amman yamshee sawiyyan AAala siratin mustaqeemin","english":"Then is one who walks fallen on his face better guided or one who walks erect on a straight path"},{"number":23,"arabic":"قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ","transliteration":"Qul huwa allathee anshaakum wajaAAala lakumu alssamAAa waalabsara waalafidata qaleelan ma tashkuroona","english":"Say, \"It is He who has produced you and made for you hearing and vision and hearts; little are you grateful"},{"number":24,"arabic":"قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ","transliteration":"Qul huwa allathee tharaakum fee alardi wailayhi tuhsharoona","english":"Say, \"It is He who has multiplied you throughout the earth, and to Him you will be gathered"},{"number":25,"arabic":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ","transliteration":"Wayaqooloona mata hatha alwaAAdu in kuntum sadiqeena","english":"And they say, \"When is this promise, if you should be truthful"},{"number":26,"arabic":"قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٞ","transliteration":"Qul innama alAAilmu AAinda Allahi wainnama ana natheerun mubeenun","english":"Say, \"The knowledge is only with Allah, and I am only a clear warner"},{"number":27,"arabic":"فَلَمَّا رَأَوۡهُ زُلۡفَةٗ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَدَّعُونَ","transliteration":"Falamma raawhu zulfatan seeat wujoohu allatheena kafaroo waqeela hatha allathee kuntum bihi taddaAAoona","english":"But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, \"This is that for which you used to call"},{"number":28,"arabic":"قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ أَوۡ رَحِمَنَا فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمٖ","transliteration":"Qul araaytum in ahlakaniya Allahu waman maAAiya aw rahimana faman yujeeru alkafireena min AAathabin aleemin","english":"Say, [O Muhammad], \"Have you considered: whether Allah should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment"},{"number":29,"arabic":"قُلۡ هُوَ ٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ","transliteration":"Qul huwa alrrahmanu amanna bihi waAAalayhi tawakkalna fasataAAlamoona man huwa fee dalalin mubeenin","english":"Say, \"He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will [come to] know who it is that is in clear error"},{"number":30,"arabic":"قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ مَآؤُكُمۡ غَوۡرٗا فَمَن يَأۡتِيكُم بِمَآءٖ مَّعِينِۭ","transliteration":"Qul araaytum in asbaha maokum ghawran faman yateekum bimain maAAeenin","english":"Say, \"Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water"}]},{"number":66,"name":"At-Tahrim","arabicName":"التحريم","meaning":"The Prohibition","minutes":5.7,"ayahs":[{"number":1,"arabic":"يَـٰٓأَيُّهَا ٱلنَّبِيُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِي مَرۡضَاتَ أَزۡوَٰجِكَۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","transliteration":"Ya ayyuha alnnabiyyu lima tuharrimu ma ahalla Allahu laka tabtaghee mardata azwajika waAllahu ghafoorun raheemun","english":"O Prophet, why do you prohibit [yourself from] what Allah has made lawful for you, seeking the approval of your wives? And Allah is Forgiving and Merciful"},{"number":2,"arabic":"قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","transliteration":"Qad farada Allahu lakum tahillata aymanikum waAllahu mawlakum wahuwa alAAaleemu alhakeemu","english":"Allah has already ordained for you [Muslims] the dissolution of your oaths. And Allah is your protector, and He is the Knowing, the Wise"},{"number":3,"arabic":"وَإِذۡ أَسَرَّ ٱلنَّبِيُّ إِلَىٰ بَعۡضِ أَزۡوَٰجِهِۦ حَدِيثٗا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضٖۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَٰذَاۖ قَالَ نَبَّأَنِيَ ٱلۡعَلِيمُ ٱلۡخَبِيرُ","transliteration":"Waith asarra alnnabiyyu ila baAAdi azwajihi hadeethan falamma nabbaat bihi waathharahu Allahu AAalayhi AAarrafa baAAdahu waaAArada AAan baAAdin falamma nabbaaha bihi qalat man anbaaka hatha qala nabbaaniya alAAaleemu alkhabeeru","english":"And [remember] when the Prophet confided to one of his wives a statement; and when she informed [another] of it and Allah showed it to him, he made known part of it and ignored a part. And when he informed her about it, she said, \"Who told you this?\" He said, \"I was informed by the Knowing, the Acquainted"},{"number":4,"arabic":"إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَٰهَرَا عَلَيۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِيلُ وَصَٰلِحُ ٱلۡمُؤۡمِنِينَۖ وَٱلۡمَلَـٰٓئِكَةُ بَعۡدَ ذَٰلِكَ ظَهِيرٌ","transliteration":"In tatooba ila Allahi faqad saghat quloobukuma wain tathahara AAalayhi fainna Allaha huwa mawlahu wajibreelu wasalihu almumineena waalmalaikatu baAAda thalika thaheerun","english":"If you two [wives] repent to Allah, [it is best], for your hearts have deviated. But if you cooperate against him - then indeed Allah is his protector, and Gabriel and the righteous of the believers and the angels, moreover, are [his] assistants"},{"number":5,"arabic":"عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبۡدِلَهُۥٓ أَزۡوَٰجًا خَيۡرٗا مِّنكُنَّ مُسۡلِمَٰتٖ مُّؤۡمِنَٰتٖ قَٰنِتَٰتٖ تَـٰٓئِبَٰتٍ عَٰبِدَٰتٖ سَـٰٓئِحَٰتٖ ثَيِّبَٰتٖ وَأَبۡكَارٗا","transliteration":"AAasa rabbuhu in tallaqakunna an yubdilahu azwajan khayran minkunna muslimatin muminatin qanitatin taibatin AAabidatin saihatin thayyibatin waabkaran","english":"Perhaps his Lord, if he divorced you [all], would substitute for him wives better than you - submitting [to Allah], believing, devoutly obedient, repentant, worshipping, and traveling - [ones] previously married and virgins"},{"number":6,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ قُوٓاْ أَنفُسَكُمۡ وَأَهۡلِيكُمۡ نَارٗا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَيۡهَا مَلَـٰٓئِكَةٌ غِلَاظٞ شِدَادٞ لَّا يَعۡصُونَ ٱللَّهَ مَآ أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ","transliteration":"Ya ayyuha allatheena amanoo qoo anfusakum waahleekum naran waqooduha alnnasu waalhijaratu AAalayha malaikatun ghilathun shidadun la yaAAsoona Allaha ma amarahum wayafAAaloona ma yumaroona","english":"O you who have believed, protect yourselves and your families from a Fire whose fuel is people and stones, over which are [appointed] angels, harsh and severe; they do not disobey Allah in what He commands them but do what they are commanded"},{"number":7,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُواْ لَا تَعۡتَذِرُواْ ٱلۡيَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ","transliteration":"Ya ayyuha allatheena kafaroo la taAAtathiroo alyawma innama tujzawna ma kuntum taAAmaloona","english":"O you who have disbelieved, make no excuses that Day. You will only be recompensed for what you used to do"},{"number":8,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","transliteration":"Ya ayyuha allatheena amanoo tooboo ila Allahi tawbatan nasoohan AAasa rabbukum an yukaffira AAankum sayyiatikum wayudkhilakum jannatin tajree min tahtiha alanharu yawma la yukhzee Allahu alnnabiyya waallatheena amanoo maAAahu nooruhum yasAAa bayna aydeehim wabiaymanihim yaqooloona rabbana atmim lana noorana waighfir lana innaka AAala kulli shayin qadeerun","english":"O you who have believed, repent to Allah with sincere repentance. Perhaps your Lord will remove from you your misdeeds and admit you into gardens beneath which rivers flow [on] the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right; they will say, \"Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent"},{"number":9,"arabic":"يَـٰٓأَيُّهَا ٱلنَّبِيُّ جَٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَٰفِقِينَ وَٱغۡلُظۡ عَلَيۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ","transliteration":"Ya ayyuha alnnabiyyu jahidi alkuffara waalmunafiqeena waoghluth AAalayhim wamawahum jahannamu wabisa almaseeru","english":"O Prophet, strive against the disbelievers and the hypocrites and be harsh upon them. And their refuge is Hell, and wretched is the destination"},{"number":10,"arabic":"ضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ كَفَرُواْ ٱمۡرَأَتَ نُوحٖ وَٱمۡرَأَتَ لُوطٖۖ كَانَتَا تَحۡتَ عَبۡدَيۡنِ مِنۡ عِبَادِنَا صَٰلِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ ٱللَّهِ شَيۡـٔٗا وَقِيلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّـٰخِلِينَ","transliteration":"Daraba Allahu mathalan lillatheena kafaroo imraata noohin waimraata lootin kanata tahta AAabdayni min AAibadina salihayni fakhanatahuma falam yughniya AAanhuma mina Allahi shayan waqeela odkhula alnnara maAAa alddakhileena","english":"Allah presents an example of those who disbelieved: the wife of Noah and the wife of Lot. They were under two of Our righteous servants but betrayed them, so those prophets did not avail them from Allah at all, and it was said, \"Enter the Fire with those who enter"},{"number":11,"arabic":"وَضَرَبَ ٱللَّهُ مَثَلٗا لِّلَّذِينَ ءَامَنُواْ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ وَنَجِّنِي مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ","transliteration":"Wadaraba Allahu mathalan lillatheena amanoo imraata firAAawna ith qalat rabbi ibni lee AAindaka baytan fee aljannati wanajjinee min firAAawna waAAamalihi wanajjinee mina alqawmi alththalimeena","english":"And Allah presents an example of those who believed: the wife of Pharaoh, when she said, \"My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people"},{"number":12,"arabic":"وَمَرۡيَمَ ٱبۡنَتَ عِمۡرَٰنَ ٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَٰنِتِينَ","transliteration":"Wamaryama ibnata AAimrana allatee ahsanat farjaha fanafakhna feehi min roohina wasaddaqat bikalimati rabbiha wakutubihi wakanat mina alqaniteena","english":"And [the example of] Mary, the daughter of 'Imran, who guarded her chastity, so We blew into [her garment] through Our angel, and she believed in the words of her Lord and His scriptures and was of the devoutly obedient"}]},{"number":65,"name":"At-Talaq","arabicName":"الطلاق","meaning":"The Divorce","minutes":6.3,"ayahs":[{"number":1,"arabic":"يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرٗا","transliteration":"Ya ayyuha alnnabiyyu itha tallaqtumu alnnisaa fatalliqoohunna liAAiddatihinna waahsoo alAAiddata waittaqoo Allaha rabbakum la tukhrijoohunna min buyootihinna wala yakhrujna illa an yateena bifahishatin mubayyinatin watilka hudoodu Allahi waman yataAAadda hudooda Allahi faqad thalama nafsahu la tadree laAAalla Allaha yuhdithu baAAda thalika amran","english":"O Prophet, when you [Muslims] divorce women, divorce them for [the commencement of] their waiting period and keep count of the waiting period, and fear Allah, your Lord. Do not turn them out of their [husbands'] houses, nor should they [themselves] leave [during that period] unless they are committing a clear immorality. And those are the limits [set by] Allah. And whoever transgresses the limits of Allah has certainly wronged himself. You know not; perhaps Allah will bring about after that a [different] matter"},{"number":2,"arabic":"فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا","transliteration":"Faitha balaghna ajalahunna faamsikoohunna bimaAAroofin aw fariqoohunna bimaAAroofin waashhidoo thaway AAadlin minkum waaqeemoo alshshahadata lillahi thalikum yooAAathu bihi man kana yuminu biAllahi waalyawmi alakhiri waman yattaqi Allaha yajAAal lahu makhrajan","english":"And when they have [nearly] fulfilled their term, either retain them according to acceptable terms or part with them according to acceptable terms. And bring to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last day. And whoever fears Allah - He will make for him a way out"},{"number":3,"arabic":"وَيَرۡزُقۡهُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُۚ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓۚ إِنَّ ٱللَّهَ بَٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَيۡءٖ قَدۡرٗا","transliteration":"Wayarzuqhu min haythu la yahtasibu waman yatawakkal AAala Allahi fahuwa hasbuhu inna Allaha balighu amrihi qad jaAAala Allahu likulli shayin qadran","english":"And will provide for him from where he does not expect. And whoever relies upon Allah - then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a [decreed] extent"},{"number":4,"arabic":"وَٱلَّـٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرٖ وَٱلَّـٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرٗا","transliteration":"Waallaee yaisna mina almaheedi min nisaikum ini irtabtum faAAiddatuhunna thalathatu ashhurin waallaee lam yahidna waolatu alahmali ajaluhunna an yadaAAna hamlahunna waman yattaqi Allaha yajAAal lahu min amrihi yusran","english":"And those who no longer expect menstruation among your women - if you doubt, then their period is three months, and [also for] those who have not menstruated. And for those who are pregnant, their term is until they give birth. And whoever fears Allah - He will make for him of his matter ease"},{"number":5,"arabic":"ذَٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيۡكُمۡۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُعۡظِمۡ لَهُۥٓ أَجۡرًا","transliteration":"Thalika amru Allahi anzalahu ilaykum waman yattaqi Allaha yukaffir AAanhu sayyiatihi wayuAAthim lahu ajran","english":"That is the command of Allah, which He has sent down to you; and whoever fears Allah - He will remove for him his misdeeds and make great for him his reward"},{"number":6,"arabic":"أَسۡكِنُوهُنَّ مِنۡ حَيۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُواْ عَلَيۡهِنَّۚ وَإِن كُنَّ أُوْلَٰتِ حَمۡلٖ فَأَنفِقُواْ عَلَيۡهِنَّ حَتَّىٰ يَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُواْ بَيۡنَكُم بِمَعۡرُوفٖۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥٓ أُخۡرَىٰ","transliteration":"Askinoohunna min haythu sakantum min wujdikum wala tudarroohunna litudayyiqoo AAalayhinna wain kunna olati hamlin faanfiqoo AAalayhinna hatta yadaAAna hamlahunna fain ardaAAna lakum faatoohunna ojoorahunna watamiroo baynakum bimaAAroofin wain taAAasartum fasaturdiAAu lahu okhra","english":"Lodge them [in a section] of where you dwell out of your means and do not harm them in order to oppress them. And if they should be pregnant, then spend on them until they give birth. And if they breastfeed for you, then give them their payment and confer among yourselves in the acceptable way; but if you are in discord, then there may breastfeed for the father another woman"},{"number":7,"arabic":"لِيُنفِقۡ ذُو سَعَةٖ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَيۡهِ رِزۡقُهُۥ فَلۡيُنفِقۡ مِمَّآ ءَاتَىٰهُ ٱللَّهُۚ لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَآ ءَاتَىٰهَاۚ سَيَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرٖ يُسۡرٗا","transliteration":"Liyunfiq thoo saAAatin min saAAatihi waman qudira AAalayhi rizquhu falyunfiq mimma atahu Allahu la yukallifu Allahu nafsan illa ma ataha sayajAAalu Allahu baAAda AAusrin yusran","english":"Let a man of wealth spend from his wealth, and he whose provision is restricted - let him spend from what Allah has given him. Allah does not charge a soul except [according to] what He has given it. Allah will bring about, after hardship, ease"},{"number":8,"arabic":"وَكَأَيِّن مِّن قَرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَٰهَا حِسَابٗا شَدِيدٗا وَعَذَّبۡنَٰهَا عَذَابٗا نُّكۡرٗا","transliteration":"Wakaayyin min qaryatin AAatat AAan amri rabbiha warusulihi fahasabnaha hisaban shadeedan waAAaththabnaha AAathaban nukran","english":"And how many a city was insolent toward the command of its Lord and His messengers, so We took it to severe account and punished it with a terrible punishment"},{"number":9,"arabic":"فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَٰقِبَةُ أَمۡرِهَا خُسۡرًا","transliteration":"Fathaqat wabala amriha wakana AAaqibatu amriha khusran","english":"And it tasted the bad consequence of its affair, and the outcome of its affair was loss"},{"number":10,"arabic":"أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابٗا شَدِيدٗاۖ فَٱتَّقُواْ ٱللَّهَ يَـٰٓأُوْلِي ٱلۡأَلۡبَٰبِ ٱلَّذِينَ ءَامَنُواْۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَيۡكُمۡ ذِكۡرٗا","transliteration":"aAAadda Allahu lahum AAathaban shadeedan faittaqoo Allaha ya olee alalbabi allatheena amanoo qad anzala Allahu ilaykum thikran","english":"Allah has prepared for them a severe punishment; so fear Allah, O you of understanding who have believed. Allah has sent down to you the Qur'an"},{"number":11,"arabic":"رَّسُولٗا يَتۡلُواْ عَلَيۡكُمۡ ءَايَٰتِ ٱللَّهِ مُبَيِّنَٰتٖ لِّيُخۡرِجَ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا","transliteration":"Rasoolan yatloo AAalaykum ayati Allahi mubayyinatin liyukhrija allatheena amanoo waAAamiloo alssalihati mina alththulumati ila alnnoori waman yumin biAllahi wayaAAmal salihan yudkhilhu jannatin tajree min tahtiha alanharu khalideena feeha abadan qad ahsana Allahu lahu rizqan","english":"[He sent] a Messenger [Muhammad] reciting to you the distinct verses of Allah that He may bring out those who believe and do righteous deeds from darknesses into the light. And whoever believes in Allah and does righteousness - He will admit him into gardens beneath which rivers flow to abide therein forever. Allah will have perfected for him a provision"},{"number":12,"arabic":"ٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا","transliteration":"Allahu allathee khalaqa sabAAa samawatin wamina alardi mithlahunna yatanazzalu alamru baynahunna litaAAlamoo anna Allaha AAala kulli shayin qadeerun waanna Allaha qad ahata bikulli shayin AAilman","english":"It is Allah who has created seven heavens and of the earth, the like of them. [His] command descends among them so you may know that Allah is over all things competent and that Allah has encompassed all things in knowledge"}]},{"number":64,"name":"At-Taghabun","arabicName":"التغابن","meaning":"The Mutual Disillusion","minutes":5.7,"ayahs":[{"number":1,"arabic":"يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","transliteration":"Yusabbihu lillahi ma fee alssamawati wama fee alardi lahu almulku walahu alhamdu wahuwa AAala kulli shayin qadeerun","english":"Whatever is in the heavens and whatever is on the earth is exalting Allah. To Him belongs dominion, and to Him belongs [all] praise, and He is over all things competent"},{"number":2,"arabic":"هُوَ ٱلَّذِي خَلَقَكُمۡ فَمِنكُمۡ كَافِرٞ وَمِنكُم مُّؤۡمِنٞۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ","transliteration":"Huwa allathee khalaqakum faminkum kafirun waminkum muminun waAllahu bima taAAmaloona baseerun","english":"It is He who created you, and among you is the disbeliever, and among you is the believer. And Allah, of what you do, is Seeing"},{"number":3,"arabic":"خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَيۡهِ ٱلۡمَصِيرُ","transliteration":"Khalaqa alssamawati waalarda bialhaqqi wasawwarakum faahsana suwarakum wailayhi almaseeru","english":"He created the heavens and earth in truth and formed you and perfected your forms; and to Him is the [final] destination"},{"number":4,"arabic":"يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","transliteration":"YaAAlamu ma fee alssamawati waalardi wayaAAlamu ma tusirroona wama tuAAlinoona waAllahu AAaleemun bithati alssudoori","english":"He knows what is within the heavens and earth and knows what you conceal and what you declare. And Allah is Knowing of that within the breasts"},{"number":5,"arabic":"أَلَمۡ يَأۡتِكُمۡ نَبَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَبۡلُ فَذَاقُواْ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِيمٞ","transliteration":"Alam yatikum nabao allatheena kafaroo min qablu fathaqoo wabala amrihim walahum AAathabun aleemun","english":"Has there not come to you the news of those who disbelieved before? So they tasted the bad consequence of their affair, and they will have a painful punishment"},{"number":6,"arabic":"ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَقَالُوٓاْ أَبَشَرٞ يَهۡدُونَنَا فَكَفَرُواْ وَتَوَلَّواْۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِيٌّ حَمِيدٞ","transliteration":"Thalika biannahu kanat tateehim rusuluhum bialbayyinati faqaloo abasharun yahdoonana fakafaroo watawallaw waistaghna Allahu waAllahu ghaniyyun hameedun","english":"That is because their messengers used to come to them with clear evidences, but they said, \"Shall human beings guide us?\" and disbelieved and turned away. And Allah dispensed [with them]; and Allah is Free of need and Praiseworthy"},{"number":7,"arabic":"زَعَمَ ٱلَّذِينَ كَفَرُوٓاْ أَن لَّن يُبۡعَثُواْۚ قُلۡ بَلَىٰ وَرَبِّي لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ","transliteration":"ZaAAama allatheena kafaroo an lan yubAAathoo qul bala warabbee latubAAathunna thumma latunabbaonna bima AAamiltum wathalika AAala Allahi yaseerun","english":"Those who disbelieve have claimed that they will never be resurrected. Say, \"Yes, by my Lord, you will surely be resurrected; then you will surely be informed of what you did. And that, for Allah, is easy"},{"number":8,"arabic":"فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِيٓ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","transliteration":"Faaminoo biAllahi warasoolihi waalnnoori allathee anzalna waAllahu bima taAAmaloona khabeerun","english":"So believe in Allah and His Messenger and the Qur'an which We have sent down. And Allah is Acquainted with what you do"},{"number":9,"arabic":"يَوۡمَ يَجۡمَعُكُمۡ لِيَوۡمِ ٱلۡجَمۡعِۖ ذَٰلِكَ يَوۡمُ ٱلتَّغَابُنِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ وَيَعۡمَلۡ صَٰلِحٗا يُكَفِّرۡ عَنۡهُ سَيِّـَٔاتِهِۦ وَيُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","transliteration":"Yawma yajmaAAukum liyawmi aljamAAi thalika yawmu alttaghabuni waman yumin biAllahi wayaAAmal salihan yukaffir AAanhu sayyiatihi wayudkhilhu jannatin tajree min tahtiha alanharu khalideena feeha abadan thalika alfawzu alAAatheemu","english":"The Day He will assemble you for the Day of Assembly - that is the Day of Deprivation. And whoever believes in Allah and does righteousness - He will remove from him his misdeeds and admit him to gardens beneath which rivers flow, wherein they will abide forever. That is the great attainment"},{"number":10,"arabic":"وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِ خَٰلِدِينَ فِيهَاۖ وَبِئۡسَ ٱلۡمَصِيرُ","transliteration":"Waallatheena kafaroo wakaththaboo biayatina olaika ashabu alnnari khalideena feeha wabisa almaseeru","english":"But the ones who disbelieved and denied Our verses - those are the companions of the Fire, abiding eternally therein; and wretched is the destination"},{"number":11,"arabic":"مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن يُؤۡمِنۢ بِٱللَّهِ يَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","transliteration":"Ma asaba min museebatin illa biithni Allahi waman yumin biAllahi yahdi qalbahu waAllahu bikulli shayin AAaleemun","english":"No disaster strikes except by permission of Allah. And whoever believes in Allah - He will guide his heart. And Allah is Knowing of all things"},{"number":12,"arabic":"وَأَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۚ فَإِن تَوَلَّيۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَٰغُ ٱلۡمُبِينُ","transliteration":"WaateeAAoo Allaha waateeAAoo alrrasoola fain tawallaytum fainnama AAala rasoolina albalaghu almubeenu","english":"And obey Allah and obey the Messenger; but if you turn away - then upon Our Messenger is only [the duty of] clear notification"},{"number":13,"arabic":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ","transliteration":"Allahu la ilaha illa huwa waAAala Allahi falyatawakkali almuminoona","english":"Allah - there is no deity except Him. And upon Allah let the believers rely"},{"number":14,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُواْ وَتَصۡفَحُواْ وَتَغۡفِرُواْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","transliteration":"Ya ayyuha allatheena amanoo inna min azwajikum waawladikum AAaduwwan lakum faihtharoohum wain taAAfoo watasfahoo wataghfiroo fainna Allaha ghafoorun raheemun","english":"O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful"},{"number":15,"arabic":"إِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ","transliteration":"Innama amwalukum waawladukum fitnatun waAllahu AAindahu ajrun AAatheemun","english":"Your wealth and your children are but a trial, and Allah has with Him a great reward"},{"number":16,"arabic":"فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","transliteration":"Faittaqoo Allaha ma istataAAtum waismaAAoo waateeAAoo waanfiqoo khayran lianfusikum waman yooqa shuhha nafsihi faolaika humu almuflihoona","english":"So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful"},{"number":17,"arabic":"إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ","transliteration":"In tuqridoo Allaha qardan hasanan yudaAAifhu lakum wayaghfir lakum waAllahu shakoorun haleemun","english":"If you loan Allah a goodly loan, He will multiply it for you and forgive you. And Allah is Most Appreciative and Forbearing"},{"number":18,"arabic":"عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","transliteration":"AAalimu alghaybi waalshshahadati alAAazeezu alhakeemu","english":"Knower of the unseen and the witnessed, the Exalted in Might, the Wise"}]},{"number":63,"name":"Al-Munafiqun","arabicName":"المنافقون","meaning":"The Hypocrites","minutes":4.2,"ayahs":[{"number":1,"arabic":"إِذَا جَآءَكَ ٱلۡمُنَٰفِقُونَ قَالُواْ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ يَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ","transliteration":"Itha jaaka almunafiqoona qaloo nashhadu innaka larasoolu Allahi waAllahu yaAAlamu innaka larasooluhu waAllahu yashhadu inna almunafiqeena lakathiboona","english":"When the hypocrites come to you, [O Muhammad], they say, \"We testify that you are the Messenger of Allah.\" And Allah knows that you are His Messenger, and Allah testifies that the hypocrites are liars"},{"number":2,"arabic":"ٱتَّخَذُوٓاْ أَيۡمَٰنَهُمۡ جُنَّةٗ فَصَدُّواْ عَن سَبِيلِ ٱللَّهِۚ إِنَّهُمۡ سَآءَ مَا كَانُواْ يَعۡمَلُونَ","transliteration":"Ittakhathoo aymanahum junnatan fasaddoo AAan sabeeli Allahi innahum saa ma kanoo yaAAmaloona","english":"They have taken their oaths as a cover, so they averted [people] from the way of Allah. Indeed, it was evil that they were doing"},{"number":3,"arabic":"ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَهُونَ","transliteration":"Thalika biannahum amanoo thumma kafaroo fatubiAAa AAala quloobihim fahum la yafqahoona","english":"That is because they believed, and then they disbelieved; so their hearts were sealed over, and they do not understand"},{"number":4,"arabic":"۞وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن يَقُولُواْ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبٞ مُّسَنَّدَةٞۖ يَحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ","transliteration":"Waitha raaytahum tuAAjibuka ajsamuhum wain yaqooloo tasmaAA liqawlihim kaannahum khushubun musannadatun yahsaboona kulla sayhatin AAalayhim humu alAAaduwwu faihtharhum qatalahumu Allahu anna yufakoona","english":"And when you see them, their forms please you, and if they speak, you listen to their speech. [They are] as if they were pieces of wood propped up - they think that every shout is against them. They are the enemy, so beware of them. May Allah destroy them; how are they deluded"},{"number":5,"arabic":"وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ رُءُوسَهُمۡ وَرَأَيۡتَهُمۡ يَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ","transliteration":"Waitha qeela lahum taAAalaw yastaghfir lakum rasoolu Allahi lawwaw ruoosahum waraaytahum yasuddoona wahum mustakbiroona","english":"And when it is said to them, \"Come, the Messenger of Allah will ask forgiveness for you,\" they turn their heads aside and you see them evading while they are arrogant"},{"number":6,"arabic":"سَوَآءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ","transliteration":"Sawaon AAalayhim astaghfarta lahum am lam tastaghfir lahum lan yaghfira Allahu lahum inna Allaha la yahdee alqawma alfasiqeena","english":"It is all the same for them whether you ask forgiveness for them or do not ask forgiveness for them; never will Allah forgive them. Indeed, Allah does not guide the defiantly disobedient people"},{"number":7,"arabic":"هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُواْ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّواْۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَفۡقَهُونَ","transliteration":"Humu allatheena yaqooloona la tunfiqoo AAala man AAinda rasooli Allahi hatta yanfaddoo walillahi khazainu alssamawati waalardi walakinna almunafiqeena la yafqahoona","english":"They are the ones who say, \"Do not spend on those who are with the Messenger of Allah until they disband.\" And to Allah belongs the depositories of the heavens and the earth, but the hypocrites do not understand"},{"number":8,"arabic":"يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ","transliteration":"Yaqooloona lain rajaAAna ila almadeenati layukhrijanna alaAAazzu minha alathalla walillahi alAAizzatu walirasoolihi walilmumineena walakinna almunafiqeena la yaAAlamoona","english":"They say, \"If we return to al-Madinah, the more honored [for power] will surely expel therefrom the more humble.\" And to Allah belongs [all] honor, and to His Messenger, and to the believers, but the hypocrites do not know"},{"number":9,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","transliteration":"Ya ayyuha allatheena amanoo la tulhikum amwalukum wala awladukum AAan thikri Allahi waman yafAAal thalika faolaika humu alkhasiroona","english":"O you who have believed, let not your wealth and your children divert you from remembrance of Allah. And whoever does that - then those are the losers"},{"number":10,"arabic":"وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ","transliteration":"Waanfiqoo min ma razaqnakum min qabli an yatiya ahadakumu almawtu fayaqoola rabbi lawla akhkhartanee ila ajalin qareebin faassaddaqa waakun mina alssaliheena","english":"And spend [in the way of Allah] from what We have provided you before death approaches one of you and he says, \"My Lord, if only You would delay me for a brief term so I would give charity and be among the righteous"},{"number":11,"arabic":"وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ","transliteration":"Walan yuakhkhira Allahu nafsan itha jaa ajaluha waAllahu khabeerun bima taAAmaloona","english":"But never will Allah delay a soul when its time has come. And Allah is Acquainted with what you do"}]},{"number":62,"name":"Al-Jumu'ah","arabicName":"الجمعة","meaning":"The Congregation, Friday","minutes":4.0,"ayahs":[{"number":1,"arabic":"يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ","transliteration":"Yusabbihu lillahi ma fee alssamawati wama fee alardi almaliki alquddoosi alAAazeezi alhakeemi","english":"Whatever is in the heavens and whatever is on the earth is exalting Allah, the Sovereign, the Pure, the Exalted in Might, the Wise"},{"number":2,"arabic":"هُوَ ٱلَّذِي بَعَثَ فِي ٱلۡأُمِّيِّـۧنَ رَسُولٗا مِّنۡهُمۡ يَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِهِۦ وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُواْ مِن قَبۡلُ لَفِي ضَلَٰلٖ مُّبِينٖ","transliteration":"Huwa allathee baAAatha fee alommiyyeena rasoolan minhum yatloo AAalayhim ayatihi wayuzakkeehim wayuAAallimuhumu alkitaba waalhikmata wain kanoo min qablu lafee dalalin mubeenin","english":"It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error"},{"number":3,"arabic":"وَءَاخَرِينَ مِنۡهُمۡ لَمَّا يَلۡحَقُواْ بِهِمۡۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","transliteration":"Waakhareena minhum lamma yalhaqoo bihim wahuwa alAAazeezu alhakeemu","english":"And [to] others of them who have not yet joined them. And He is the Exalted in Might, the Wise"},{"number":4,"arabic":"ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ","transliteration":"Thalika fadlu Allahi yuteehi man yashao waAllahu thoo alfadli alAAatheemi","english":"That is the bounty of Allah, which He gives to whom He wills, and Allah is the possessor of great bounty"},{"number":5,"arabic":"مَثَلُ ٱلَّذِينَ حُمِّلُواْ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ يَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ يَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ","transliteration":"Mathalu allatheena hummiloo alttawrata thumma lam yahmilooha kamathali alhimari yahmilu asfaran bisa mathalu alqawmi allatheena kaththaboo biayati Allahi waAllahu la yahdee alqawma alththalimeena","english":"The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people"},{"number":6,"arabic":"قُلۡ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓاْ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُاْ ٱلۡمَوۡتَ إِن كُنتُمۡ صَٰدِقِينَ","transliteration":"Qul ya ayyuha allatheena hadoo in zaAAamtum annakum awliyao lillahi min dooni alnnasi fatamannawoo almawta in kuntum sadiqeena","english":"Say, \"O you who are Jews, if you claim that you are allies of Allah, excluding the [other] people, then wish for death, if you should be truthful"},{"number":7,"arabic":"وَلَا يَتَمَنَّوۡنَهُۥٓ أَبَدَۢا بِمَا قَدَّمَتۡ أَيۡدِيهِمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّـٰلِمِينَ","transliteration":"Wala yatamannawnahu abadan bima qaddamat aydeehim waAllahu AAaleemun bialththalimeena","english":"But they will not wish for it, ever, because of what their hands have put forth. And Allah is Knowing of the wrongdoers"},{"number":8,"arabic":"قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِي تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَٰقِيكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ","transliteration":"Qul inna almawta allathee tafirroona minhu fainnahu mulaqeekum thumma turaddoona ila AAalimi alghaybi waalshshahadati fayunabbiokum bima kuntum taAAmaloona","english":"Say, \"Indeed, the death from which you flee - indeed, it will meet you. Then you will be returned to the Knower of the unseen and the witnessed, and He will inform you about what you used to do"},{"number":9,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نُودِيَ لِلصَّلَوٰةِ مِن يَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُواْ ٱلۡبَيۡعَۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","transliteration":"Ya ayyuha allatheena amanoo itha noodiya lilssalati min yawmi aljumuAAati faisAAaw ila thikri Allahi watharoo albayAAa thalikum khayrun lakum in kuntum taAAlamoona","english":"O you who have believed, when [the adhan] is called for the prayer on the day of Jumu'ah [Friday], then proceed to the remembrance of Allah and leave trade. That is better for you, if you only knew"},{"number":10,"arabic":"فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ فِي ٱلۡأَرۡضِ وَٱبۡتَغُواْ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","transliteration":"Faitha qudiyati alssalatu faintashiroo fee alardi waibtaghoo min fadli Allahi waothkuroo Allaha katheeran laAAallakum tuflihoona","english":"And when the prayer has been concluded, disperse within the land and seek from the bounty of Allah, and remember Allah often that you may succeed"},{"number":11,"arabic":"وَإِذَا رَأَوۡاْ تِجَٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوٓاْ إِلَيۡهَا وَتَرَكُوكَ قَآئِمٗاۚ قُلۡ مَا عِندَ ٱللَّهِ خَيۡرٞ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَٰرَةِۚ وَٱللَّهُ خَيۡرُ ٱلرَّـٰزِقِينَ","transliteration":"Waitha raaw tijaratan aw lahwan infaddoo ilayha watarakooka qaiman qul ma AAinda Allahi khayrun mina allahwi wamina alttijarati waAllahu khayru alrraziqeena","english":"But when they saw a transaction or a diversion, [O Muhammad], they rushed to it and left you standing. Say, \"What is with Allah is better than diversion and than a transaction, and Allah is the best of providers"}]},{"number":61,"name":"As-Saf","arabicName":"الصف","meaning":"The Ranks","minutes":5.0,"ayahs":[{"number":1,"arabic":"سَبَّحَ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","transliteration":"Sabbaha lillahi ma fee alssamawati wama fee alardi wahuwa alAAazeezu alhakeemu","english":"Whatever is in the heavens and whatever is on the earth exalts Allah, and He is the Exalted in Might, the Wise"},{"number":2,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ","transliteration":"Ya ayyuha allatheena amanoo lima taqooloona ma la tafAAaloona","english":"O you who have believed, why do you say what you do not do"},{"number":3,"arabic":"كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُواْ مَا لَا تَفۡعَلُونَ","transliteration":"Kabura maqtan AAinda Allahi an taqooloo ma la tafAAaloona","english":"Great is hatred in the sight of Allah that you say what you do not do"},{"number":4,"arabic":"إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ","transliteration":"Inna Allaha yuhibbu allatheena yuqatiloona fee sabeelihi saffan kaannahum bunyanun marsoosun","english":"Indeed, Allah loves those who fight in His cause in a row as though they are a [single] structure joined firmly"},{"number":5,"arabic":"وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ لِمَ تُؤۡذُونَنِي وَقَد تَّعۡلَمُونَ أَنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡۖ فَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡفَٰسِقِينَ","transliteration":"Waith qala moosa liqawmihi ya qawmi lima tuthoonanee waqad taAAlamoona annee rasoolu Allahi ilaykum falamma zaghoo azagha Allahu quloobahum waAllahu la yahdee alqawma alfasiqeena","english":"And [mention, O Muhammad], when Moses said to his people, \"O my people, why do you harm me while you certainly know that I am the messenger of Allah to you?\" And when they deviated, Allah caused their hearts to deviate. And Allah does not guide the defiantly disobedient people"},{"number":6,"arabic":"وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَـٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا جَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ","transliteration":"Waith qala AAeesa ibnu maryama ya banee israeela innee rasoolu Allahi ilaykum musaddiqan lima bayna yadayya mina alttawrati wamubashshiran birasoolin yatee min baAAdee ismuhu ahmadu falamma jaahum bialbayyinati qaloo hatha sihrun mubeenun","english":"And [mention] when Jesus, the son of Mary, said, \"O children of Israel, indeed I am the messenger of Allah to you confirming what came before me of the Torah and bringing good tidings of a messenger to come after me, whose name is Ahmad.\" But when he came to them with clear evidences, they said, \"This is obvious magic"},{"number":7,"arabic":"وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ يُدۡعَىٰٓ إِلَى ٱلۡإِسۡلَٰمِۚ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ","transliteration":"Waman athlamu mimmani iftara AAala Allahi alkathiba wahuwa yudAAa ila alislami waAllahu la yahdee alqawma alththalimeena","english":"And who is more unjust than one who invents about Allah untruth while he is being invited to Islam. And Allah does not guide the wrongdoing people"},{"number":8,"arabic":"يُرِيدُونَ لِيُطۡفِـُٔواْ نُورَ ٱللَّهِ بِأَفۡوَٰهِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ","transliteration":"Yureedoona liyutfioo noora Allahi biafwahihim waAllahu mutimmu noorihi walaw kariha alkafiroona","english":"They want to extinguish the light of Allah with their mouths, but Allah will perfect His light, although the disbelievers dislike it"},{"number":9,"arabic":"هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ","transliteration":"Huwa allathee arsala rasoolahu bialhuda wadeeni alhaqqi liyuthhirahu AAala alddeeni kullihi walaw kariha almushrikoona","english":"It is He who sent His Messenger with guidance and the religion of truth to manifest it over all religion, although those who associate others with Allah dislike it"},{"number":10,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَٰرَةٖ تُنجِيكُم مِّنۡ عَذَابٍ أَلِيمٖ","transliteration":"Ya ayyuha allatheena amanoo hal adullukum AAala tijaratin tunjeekum min AAathabin aleemin","english":"O you who have believed, shall I guide you to a transaction that will save you from a painful punishment"},{"number":11,"arabic":"تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","transliteration":"Tuminoona biAllahi warasoolihi watujahidoona fee sabeeli Allahi biamwalikum waanfusikum thalikum khayrun lakum in kuntum taAAlamoona","english":"[It is that] you believe in Allah and His Messenger and strive in the cause of Allah with your wealth and your lives. That is best for you, if you should know"},{"number":12,"arabic":"يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُدۡخِلۡكُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَمَسَٰكِنَ طَيِّبَةٗ فِي جَنَّـٰتِ عَدۡنٖۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","transliteration":"Yaghfir lakum thunoobakum wayudkhilkum jannatin tajree min tahtiha alanharu wamasakina tayyibatan fee jannati AAadnin thalika alfawzu alAAatheemu","english":"He will forgive for you your sins and admit you to gardens beneath which rivers flow and pleasant dwellings in gardens of perpetual residence. That is the great attainment"},{"number":13,"arabic":"وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرٞ مِّنَ ٱللَّهِ وَفَتۡحٞ قَرِيبٞۗ وَبَشِّرِ ٱلۡمُؤۡمِنِينَ","transliteration":"Waokhra tuhibboonaha nasrun mina Allahi wafathun qarreebun wabashshiri almumineena","english":"And [you will obtain] another [favor] that you love - victory from Allah and an imminent conquest; and give good tidings to the believers"},{"number":14,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُوٓاْ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ لِلۡحَوَارِيِّـۧنَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّآئِفَةٞ مِّنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ وَكَفَرَت طَّآئِفَةٞۖ فَأَيَّدۡنَا ٱلَّذِينَ ءَامَنُواْ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُواْ ظَٰهِرِينَ","transliteration":"Ya ayyuha allatheena amanoo koonoo ansara Allahi kama qala AAeesa ibnu maryama lilhawariyyeena man ansaree ila Allahi qala alhawariyyoona nahnu ansaru Allahi faamanat taifatun min banee israeela wakafarat taifatun faayyadna allatheena amanoo AAala AAaduwwihim faasbahoo thahireena","english":"O you who have believed, be supporters of Allah, as when Jesus, the son of Mary, said to the disciples, \"Who are my supporters for Allah?\" The disciples said, \"We are supporters of Allah.\" And a faction of the Children of Israel believed and a faction disbelieved. So We supported those who believed against their enemy, and they became dominant"}]},{"number":60,"name":"Al-Mumtahanah","arabicName":"الممتحنة","meaning":"She that is to be examined","minutes":8.2,"ayahs":[{"number":1,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ عَدُوِّي وَعَدُوَّكُمۡ أَوۡلِيَآءَ تُلۡقُونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُواْ بِمَا جَآءَكُم مِّنَ ٱلۡحَقِّ يُخۡرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمۡ أَن تُؤۡمِنُواْ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَٰدٗا فِي سَبِيلِي وَٱبۡتِغَآءَ مَرۡضَاتِيۚ تُسِرُّونَ إِلَيۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَآ أَخۡفَيۡتُمۡ وَمَآ أَعۡلَنتُمۡۚ وَمَن يَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَآءَ ٱلسَّبِيلِ","transliteration":"Ya ayyuha allatheena amanoo la tattakhithoo AAaduwwee waAAaduwwakum awliyaa tulqoona ilayhim bialmawaddati waqad kafaroo bima jaakum mina alhaqqi yukhrijoona alrrasoola waiyyakum an tuminoo biAllahi rabbikum in kuntum kharajtum jihadan fee sabeelee waibtighaa mardatee tusirroona ilayhim bialmawaddati waana aAAlamu bima akhfaytum wama aAAlantum waman yafAAalhu minkum faqad dalla sawaa alssabeeli","english":"O you who have believed, do not take My enemies and your enemies as allies, extending to them affection while they have disbelieved in what came to you of the truth, having driven out the Prophet and yourselves [only] because you believe in Allah, your Lord. If you have come out for jihad in My cause and seeking means to My approval, [take them not as friends]. You confide to them affection, but I am most knowing of what you have concealed and what you have declared. And whoever does it among you has certainly strayed from the soundness of the way"},{"number":2,"arabic":"إِن يَثۡقَفُوكُمۡ يَكُونُواْ لَكُمۡ أَعۡدَآءٗ وَيَبۡسُطُوٓاْ إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّواْ لَوۡ تَكۡفُرُونَ","transliteration":"In yathqafookum yakoonoo lakam aAAdaan wayabsutoo ilaykum aydiyahum waalsinatahum bialssooi wawaddoo law takfuroona","english":"If they gain dominance over you, they would be to you as enemies and extend against you their hands and their tongues with evil, and they wish you would disbelieve"},{"number":3,"arabic":"لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَآ أَوۡلَٰدُكُمۡۚ يَوۡمَ ٱلۡقِيَٰمَةِ يَفۡصِلُ بَيۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ","transliteration":"Lan tanfaAAakum arhamukum wala awladukum yawma alqiyamati yafsilu baynakum waAllahu bima taAAmaloona baseerun","english":"Never will your relatives or your children benefit you; the Day of Resurrection He will judge between you. And Allah, of what you do, is Seeing"},{"number":4,"arabic":"قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةٞ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَـٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءٖۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ","transliteration":"Qad kanat lakum oswatun hasanatun fee ibraheema waallatheena maAAahu ith qaloo liqawmihim inna buraao minkum wamimma taAAbudoona min dooni Allahi kafarna bikum wabada baynana wabaynakumu alAAadawatu waalbaghdao abadan hatta tuminoo biAllahi wahdahu illa qawla ibraheema liabeehi laastaghfiranna laka wama amliku laka mina Allahi min shayin rabbana AAalayka tawakkalna wailayka anabna wailayka almaseeru","english":"There has already been for you an excellent pattern in Abraham and those with him, when they said to their people, \"Indeed, we are disassociated from you and from whatever you worship other than Allah. We have denied you, and there has appeared between us and you animosity and hatred forever until you believe in Allah alone\" except for the saying of Abraham to his father, \"I will surely ask forgiveness for you, but I have not [power to do] for you anything against Allah. Our Lord, upon You we have relied, and to You we have returned, and to You is the destination"},{"number":5,"arabic":"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","transliteration":"Rabbana la tajAAalna fitnatan lillatheena kafaroo waighfir lana rabbana innaka anta alAAazeezu alhakeemu","english":"Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise"},{"number":6,"arabic":"لَقَدۡ كَانَ لَكُمۡ فِيهِمۡ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ","transliteration":"Laqad kana lakum feehim oswatun hasanatun liman kana yarjoo Allaha waalyawma alakhira waman yatawalla fainna Allaha huwa alghanniyyu alhameedu","english":"There has certainly been for you in them an excellent pattern for anyone whose hope is in Allah and the Last Day. And whoever turns away - then indeed, Allah is the Free of need, the Praiseworthy"},{"number":7,"arabic":"۞عَسَى ٱللَّهُ أَن يَجۡعَلَ بَيۡنَكُمۡ وَبَيۡنَ ٱلَّذِينَ عَادَيۡتُم مِّنۡهُم مَّوَدَّةٗۚ وَٱللَّهُ قَدِيرٞۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","transliteration":"AAasa Allahu an yajAAala baynakum wabayna allatheena AAadaytum minhum mawaddatan waAllahu qadeerun waAllahu ghafoorun raheemun","english":"Perhaps Allah will put, between you and those to whom you have been enemies among them, affection. And Allah is competent, and Allah is Forgiving and Merciful"},{"number":8,"arabic":"لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","transliteration":"La yanhakumu Allahu AAani allatheena lam yuqatilookum fee alddeeni walam yukhrijookum min diyarikum an tabarroohum watuqsitoo ilayhim inna Allaha yuhibbu almuqsiteena","english":"Allah does not forbid you from those who do not fight you because of religion and do not expel you from your homes - from being righteous toward them and acting justly toward them. Indeed, Allah loves those who act justly"},{"number":9,"arabic":"إِنَّمَا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَٰتَلُوكُمۡ فِي ٱلدِّينِ وَأَخۡرَجُوكُم مِّن دِيَٰرِكُمۡ وَظَٰهَرُواْ عَلَىٰٓ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن يَتَوَلَّهُمۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ","transliteration":"Innama yanhakumu Allahu AAani allatheena qatalookum fee alddeeni waakhrajookum min diyarikum wathaharoo AAala ikhrajikum an tawallawhum waman yatawallahum faolaika humu alththalimoona","english":"Allah only forbids you from those who fight you because of religion and expel you from your homes and aid in your expulsion - [forbids] that you make allies of them. And whoever makes allies of them, then it is those who are the wrongdoers"},{"number":10,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا جَآءَكُمُ ٱلۡمُؤۡمِنَٰتُ مُهَٰجِرَٰتٖ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِيمَٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلّٞ لَّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّآ أَنفَقُواْۚ وَلَا جُنَاحَ عَلَيۡكُمۡ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُواْ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُواْ مَآ أَنفَقۡتُمۡ وَلۡيَسۡـَٔلُواْ مَآ أَنفَقُواْۚ ذَٰلِكُمۡ حُكۡمُ ٱللَّهِ يَحۡكُمُ بَيۡنَكُمۡۖ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","transliteration":"Ya ayyuha allatheena amanoo itha jaakumu almuminatu muhajiratin faimtahinoohunna Allahu aAAlamu bieemanihinna fain AAalimtumoohunna muminatin fala tarjiAAoohunna ila alkuffari la hunna hillun lahum wala hum yahilloona lahunna waatoohum ma anfaqoo wala junaha AAalaykum an tankihoohunna itha ataytumoohunna ojoorahunna wala tumsikoo biAAisami alkawafiri waisaloo ma anfaqtum walyasaloo ma anfaqoo thalikum hukmu Allahi yahkumu baynakum waAllahu AAaleemun hakeemun","english":"O you who have believed, when the believing women come to you as emigrants, examine them. Allah is most knowing as to their faith. And if you know them to be believers, then do not return them to the disbelievers; they are not lawful [wives] for them, nor are they lawful [husbands] for them. But give the disbelievers what they have spent. And there is no blame upon you if you marry them when you have given them their due compensation. And hold not to marriage bonds with disbelieving women, but ask for what you have spent and let them ask for what they have spent. That is the judgement of Allah; He judges between you. And Allah is Knowing and Wise"},{"number":11,"arabic":"وَإِن فَاتَكُمۡ شَيۡءٞ مِّنۡ أَزۡوَٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُواْ ٱلَّذِينَ ذَهَبَتۡ أَزۡوَٰجُهُم مِّثۡلَ مَآ أَنفَقُواْۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ أَنتُم بِهِۦ مُؤۡمِنُونَ","transliteration":"Wain fatakum shayon min azwajikum ila alkuffari faAAaqabtum faatoo allatheena thahabat azwajuhum mithla ma anfaqoo waittaqoo Allaha allathee antum bihi muminoona","english":"And if you have lost any of your wives to the disbelievers and you subsequently obtain [something], then give those whose wives have gone the equivalent of what they had spent. And fear Allah, in whom you are believers"},{"number":12,"arabic":"يَـٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا جَآءَكَ ٱلۡمُؤۡمِنَٰتُ يُبَايِعۡنَكَ عَلَىٰٓ أَن لَّا يُشۡرِكۡنَ بِٱللَّهِ شَيۡـٔٗا وَلَا يَسۡرِقۡنَ وَلَا يَزۡنِينَ وَلَا يَقۡتُلۡنَ أَوۡلَٰدَهُنَّ وَلَا يَأۡتِينَ بِبُهۡتَٰنٖ يَفۡتَرِينَهُۥ بَيۡنَ أَيۡدِيهِنَّ وَأَرۡجُلِهِنَّ وَلَا يَعۡصِينَكَ فِي مَعۡرُوفٖ فَبَايِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","transliteration":"Ya ayyuha alnnabiyyu itha jaaka almuminatu yubayiAAnaka AAala an la yushrikna biAllahi shayan wala yasriqna wala yazneena wala yaqtulna awladahunna wala yateena bibuhtanin yaftareenahu bayna aydeehinna waarjulihinna wala yaAAseenaka fee maAAroofin fabayiAAhunna waistaghfir lahunna Allaha inna Allaha ghafoorun raheemun","english":"O Prophet, when the believing women come to you pledging to you that they will not associate anything with Allah, nor will they steal, nor will they commit unlawful sexual intercourse, nor will they kill their children, nor will they bring forth a slander they have invented between their arms and legs, nor will they disobey you in what is right - then accept their pledge and ask forgiveness for them of Allah. Indeed, Allah is Forgiving and Merciful"},{"number":13,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَوَلَّوۡاْ قَوۡمًا غَضِبَ ٱللَّهُ عَلَيۡهِمۡ قَدۡ يَئِسُواْ مِنَ ٱلۡأٓخِرَةِ كَمَا يَئِسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَٰبِ ٱلۡقُبُورِ","transliteration":"Ya ayyuha allatheena amanoo la tatawallaw qawman ghadiba Allahu AAalayhim qad yaisoo mina alakhirati kama yaisa alkuffaru min ashabi alquboori","english":"O you who have believed, do not make allies of a people with whom Allah has become angry. They have despaired of [reward in] the Hereafter just as the disbelievers have despaired of [meeting] the inhabitants of the graves"}]},{"number":56,"name":"Al-Waqi'ah","arabicName":"الواقعة","meaning":"The Inevitable","minutes":9.1,"ayahs":[{"number":1,"arabic":"إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ","transliteration":"Itha waqaAAati alwaqiAAatu","english":"When the Occurrence occurs"},{"number":2,"arabic":"لَيۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ","transliteration":"Laysa liwaqAAatiha kathibatun","english":"There is, at its occurrence, no denial"},{"number":3,"arabic":"خَافِضَةٞ رَّافِعَةٌ","transliteration":"Khafidatun rafiAAatun","english":"It will bring down [some] and raise up [others]"},{"number":4,"arabic":"إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجّٗا","transliteration":"Itha rujjati alardu rajjan","english":"When the earth is shaken with convulsion"},{"number":5,"arabic":"وَبُسَّتِ ٱلۡجِبَالُ بَسّٗا","transliteration":"Wabussati aljibalu bassan","english":"And the mountains are broken down, crumbling"},{"number":6,"arabic":"فَكَانَتۡ هَبَآءٗ مُّنۢبَثّٗا","transliteration":"Fakanat habaan munbaththan","english":"And become dust dispersing"},{"number":7,"arabic":"وَكُنتُمۡ أَزۡوَٰجٗا ثَلَٰثَةٗ","transliteration":"Wakuntum azwajan thalathatan","english":"And you become [of] three kinds"},{"number":8,"arabic":"فَأَصۡحَٰبُ ٱلۡمَيۡمَنَةِ مَآ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ","transliteration":"Faashabu almaymanati ma ashabu almaymanati","english":"Then the companions of the right - what are the companions of the right"},{"number":9,"arabic":"وَأَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ مَآ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ","transliteration":"Waashabu almashamati ma ashabu almashamati","english":"And the companions of the left - what are the companions of the left"},{"number":10,"arabic":"وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ","transliteration":"Waalssabiqoona alssabiqoona","english":"And the forerunners, the forerunners"},{"number":11,"arabic":"أُوْلَـٰٓئِكَ ٱلۡمُقَرَّبُونَ","transliteration":"Olaika almuqarraboona","english":"Those are the ones brought near [to Allah]"},{"number":12,"arabic":"فِي جَنَّـٰتِ ٱلنَّعِيمِ","transliteration":"Fee jannati alnnaAAeemi","english":"In the Gardens of Pleasure"},{"number":13,"arabic":"ثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ","transliteration":"Thullatun mina alawwaleena","english":"A [large] company of the former peoples"},{"number":14,"arabic":"وَقَلِيلٞ مِّنَ ٱلۡأٓخِرِينَ","transliteration":"Waqaleelun mina alakhireena","english":"And a few of the later peoples"},{"number":15,"arabic":"عَلَىٰ سُرُرٖ مَّوۡضُونَةٖ","transliteration":"AAala sururin mawdoonatin","english":"On thrones woven [with ornament]"},{"number":16,"arabic":"مُّتَّكِـِٔينَ عَلَيۡهَا مُتَقَٰبِلِينَ","transliteration":"Muttakieena AAalayha mutaqabileena","english":"Reclining on them, facing each other"},{"number":17,"arabic":"يَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ","transliteration":"Yatoofu AAalayhim wildanun mukhalladoona","english":"There will circulate among them young boys made eternal"},{"number":18,"arabic":"بِأَكۡوَابٖ وَأَبَارِيقَ وَكَأۡسٖ مِّن مَّعِينٖ","transliteration":"Biakwabin waabareeqa wakasin min maAAeenin","english":"With vessels, pitchers and a cup [of wine] from a flowing spring"},{"number":19,"arabic":"لَّا يُصَدَّعُونَ عَنۡهَا وَلَا يُنزِفُونَ","transliteration":"La yusaddaAAoona AAanha wala yunzifoona","english":"No headache will they have therefrom, nor will they be intoxicated"},{"number":20,"arabic":"وَفَٰكِهَةٖ مِّمَّا يَتَخَيَّرُونَ","transliteration":"Wafakihatin mimma yatakhayyaroona","english":"And fruit of what they select"},{"number":21,"arabic":"وَلَحۡمِ طَيۡرٖ مِّمَّا يَشۡتَهُونَ","transliteration":"Walahmi tayrin mimma yashtahoona","english":"And the meat of fowl, from whatever they desire"},{"number":22,"arabic":"وَحُورٌ عِينٞ","transliteration":"Wahoorun AAeenun","english":"And [for them are] fair women with large, [beautiful] eyes"},{"number":23,"arabic":"كَأَمۡثَٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ","transliteration":"Kaamthali allului almaknooni","english":"The likenesses of pearls well-protected"},{"number":24,"arabic":"جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ","transliteration":"Jazaan bima kanoo yaAAmaloona","english":"As reward for what they used to do"},{"number":25,"arabic":"لَا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا تَأۡثِيمًا","transliteration":"La yasmaAAoona feeha laghwan wala tatheeman","english":"They will not hear therein ill speech or commission of sin"},{"number":26,"arabic":"إِلَّا قِيلٗا سَلَٰمٗا سَلَٰمٗا","transliteration":"Illa qeelan salaman salaman","english":"Only a saying: \"Peace, peace"},{"number":27,"arabic":"وَأَصۡحَٰبُ ٱلۡيَمِينِ مَآ أَصۡحَٰبُ ٱلۡيَمِينِ","transliteration":"Waashabu alyameeni ma ashabu alyameeni","english":"The companions of the right - what are the companions of the right"},{"number":28,"arabic":"فِي سِدۡرٖ مَّخۡضُودٖ","transliteration":"Fee sidrin makhdoodin","english":"[They will be] among lote trees with thorns removed"},{"number":29,"arabic":"وَطَلۡحٖ مَّنضُودٖ","transliteration":"Watalhin mandoodin","english":"And [banana] trees layered [with fruit]"},{"number":30,"arabic":"وَظِلّٖ مَّمۡدُودٖ","transliteration":"Wathillin mamdoodin","english":"And shade extended"},{"number":31,"arabic":"وَمَآءٖ مَّسۡكُوبٖ","transliteration":"Wamain maskoobin","english":"And water poured out"},{"number":32,"arabic":"وَفَٰكِهَةٖ كَثِيرَةٖ","transliteration":"Wafakihatin katheeratin","english":"And fruit, abundant [and varied]"},{"number":33,"arabic":"لَّا مَقۡطُوعَةٖ وَلَا مَمۡنُوعَةٖ","transliteration":"La maqtooAAatin wala mamnooAAatin","english":"Neither limited [to season] nor forbidden"},{"number":34,"arabic":"وَفُرُشٖ مَّرۡفُوعَةٍ","transliteration":"Wafurushin marfooAAatin","english":"And [upon] beds raised high"},{"number":35,"arabic":"إِنَّآ أَنشَأۡنَٰهُنَّ إِنشَآءٗ","transliteration":"Inna anshanahunna inshaan","english":"Indeed, We have produced the women of Paradise in a [new] creation"},{"number":36,"arabic":"فَجَعَلۡنَٰهُنَّ أَبۡكَارًا","transliteration":"FajaAAalnahunna abkaran","english":"And made them virgins"},{"number":37,"arabic":"عُرُبًا أَتۡرَابٗا","transliteration":"AAuruban atraban","english":"Devoted [to their husbands] and of equal age"},{"number":38,"arabic":"لِّأَصۡحَٰبِ ٱلۡيَمِينِ","transliteration":"Liashabi alyameeni","english":"For the companions of the right [who are]"},{"number":39,"arabic":"ثُلَّةٞ مِّنَ ٱلۡأَوَّلِينَ","transliteration":"Thullatun mina alawwaleena","english":"A company of the former peoples"},{"number":40,"arabic":"وَثُلَّةٞ مِّنَ ٱلۡأٓخِرِينَ","transliteration":"Wathullatun mina alakhireena","english":"And a company of the later peoples"},{"number":41,"arabic":"وَأَصۡحَٰبُ ٱلشِّمَالِ مَآ أَصۡحَٰبُ ٱلشِّمَالِ","transliteration":"Waashabu alshshimali ma ashabu alshshimali","english":"And the companions of the left - what are the companions of the left"},{"number":42,"arabic":"فِي سَمُومٖ وَحَمِيمٖ","transliteration":"Fee samoomin wahameemin","english":"[They will be] in scorching fire and scalding water"},{"number":43,"arabic":"وَظِلّٖ مِّن يَحۡمُومٖ","transliteration":"Wathillin min yahmoomin","english":"And a shade of black smoke"},{"number":44,"arabic":"لَّا بَارِدٖ وَلَا كَرِيمٍ","transliteration":"La baridin wala kareemin","english":"Neither cool nor beneficial"},{"number":45,"arabic":"إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُتۡرَفِينَ","transliteration":"Innahum kanoo qabla thalika mutrafeena","english":"Indeed they were, before that, indulging in affluence"},{"number":46,"arabic":"وَكَانُواْ يُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِيمِ","transliteration":"Wakanoo yusirroona AAala alhinthi alAAatheemi","english":"And they used to persist in the great violation"},{"number":47,"arabic":"وَكَانُواْ يَقُولُونَ أَئِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ","transliteration":"Wakanoo yaqooloona aitha mitna wakunna turaban waAAithaman ainna lamabAAoothoona","english":"And they used to say, \"When we die and become dust and bones, are we indeed to be resurrected"},{"number":48,"arabic":"أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ","transliteration":"Awa abaona alawwaloona","english":"And our forefathers [as well]"},{"number":49,"arabic":"قُلۡ إِنَّ ٱلۡأَوَّلِينَ وَٱلۡأٓخِرِينَ","transliteration":"Qul inna alawwaleena waalakhireena","english":"Say, [O Muhammad], \"Indeed, the former and the later peoples"},{"number":50,"arabic":"لَمَجۡمُوعُونَ إِلَىٰ مِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ","transliteration":"LamajmooAAoona ila meeqati yawmin maAAloomin","english":"Are to be gathered together for the appointment of a known Day"},{"number":51,"arabic":"ثُمَّ إِنَّكُمۡ أَيُّهَا ٱلضَّآلُّونَ ٱلۡمُكَذِّبُونَ","transliteration":"Thumma innakum ayyuha alddalloona almukaththiboona","english":"Then indeed you, O those astray [who are] deniers"},{"number":52,"arabic":"لَأٓكِلُونَ مِن شَجَرٖ مِّن زَقُّومٖ","transliteration":"Laakiloona min shajarin min zaqqoomin","english":"Will be eating from trees of zaqqum"},{"number":53,"arabic":"فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ","transliteration":"Famalioona minha albutoona","english":"And filling with it your bellies"},{"number":54,"arabic":"فَشَٰرِبُونَ عَلَيۡهِ مِنَ ٱلۡحَمِيمِ","transliteration":"Fashariboona AAalayhi mina alhameemi","english":"And drinking on top of it from scalding water"},{"number":55,"arabic":"فَشَٰرِبُونَ شُرۡبَ ٱلۡهِيمِ","transliteration":"Fashariboona shurba alheemi","english":"And will drink as the drinking of thirsty camels"},{"number":56,"arabic":"هَٰذَا نُزُلُهُمۡ يَوۡمَ ٱلدِّينِ","transliteration":"Hatha nuzuluhum yawma alddeeni","english":"That is their accommodation on the Day of Recompense"},{"number":57,"arabic":"نَحۡنُ خَلَقۡنَٰكُمۡ فَلَوۡلَا تُصَدِّقُونَ","transliteration":"Nahnu khalaqnakum falawla tusaddiqoona","english":"We have created you, so why do you not believe"},{"number":58,"arabic":"أَفَرَءَيۡتُم مَّا تُمۡنُونَ","transliteration":"Afaraaytum ma tumnoona","english":"Have you seen that which you emit"},{"number":59,"arabic":"ءَأَنتُمۡ تَخۡلُقُونَهُۥٓ أَمۡ نَحۡنُ ٱلۡخَٰلِقُونَ","transliteration":"Aantum takhluqoonahu am nahnu alkhaliqoona","english":"Is it you who creates it, or are We the Creator"},{"number":60,"arabic":"نَحۡنُ قَدَّرۡنَا بَيۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِينَ","transliteration":"Nahnu qaddarna baynakumu almawta wama nahnu bimasbooqeena","english":"We have decreed death among you, and We are not to be outdone"},{"number":61,"arabic":"عَلَىٰٓ أَن نُّبَدِّلَ أَمۡثَٰلَكُمۡ وَنُنشِئَكُمۡ فِي مَا لَا تَعۡلَمُونَ","transliteration":"AAala an nubaddila amthalakum wanunshiakum fee ma la taAAlamoona","english":"In that We will change your likenesses and produce you in that [form] which you do not know"},{"number":62,"arabic":"وَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ","transliteration":"Walaqad AAalimtumu alnnashata aloola falawla tathakkaroona","english":"And you have already known the first creation, so will you not remember"},{"number":63,"arabic":"أَفَرَءَيۡتُم مَّا تَحۡرُثُونَ","transliteration":"Afaraaytum ma tahruthoona","english":"And have you seen that [seed] which you sow"},{"number":64,"arabic":"ءَأَنتُمۡ تَزۡرَعُونَهُۥٓ أَمۡ نَحۡنُ ٱلزَّـٰرِعُونَ","transliteration":"Aantum tazraAAoonahu am nahnu alzzariAAoona","english":"Is it you who makes it grow, or are We the grower"},{"number":65,"arabic":"لَوۡ نَشَآءُ لَجَعَلۡنَٰهُ حُطَٰمٗا فَظَلۡتُمۡ تَفَكَّهُونَ","transliteration":"Law nashao lajaAAalnahu hutaman fathaltum tafakkahoona","english":"If We willed, We could make it [dry] debris, and you would remain in wonder"},{"number":66,"arabic":"إِنَّا لَمُغۡرَمُونَ","transliteration":"Inna lamughramoona","english":"[Saying], \"Indeed, we are [now] in debt"},{"number":67,"arabic":"بَلۡ نَحۡنُ مَحۡرُومُونَ","transliteration":"Bal nahnu mahroomoona","english":"Rather, we have been deprived"},{"number":68,"arabic":"أَفَرَءَيۡتُمُ ٱلۡمَآءَ ٱلَّذِي تَشۡرَبُونَ","transliteration":"Afaraaytumu almaa allathee tashraboona","english":"And have you seen the water that you drink"},{"number":69,"arabic":"ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ","transliteration":"Aantum anzaltumoohu mina almuzni am nahnu almunziloona","english":"Is it you who brought it down from the clouds, or is it We who bring it down"},{"number":70,"arabic":"لَوۡ نَشَآءُ جَعَلۡنَٰهُ أُجَاجٗا فَلَوۡلَا تَشۡكُرُونَ","transliteration":"Law nashao jaAAalnahu ojajan falawla tashkuroona","english":"If We willed, We could make it bitter, so why are you not grateful"},{"number":71,"arabic":"أَفَرَءَيۡتُمُ ٱلنَّارَ ٱلَّتِي تُورُونَ","transliteration":"Afaraaytumu alnnara allatee tooroona","english":"And have you seen the fire that you ignite"},{"number":72,"arabic":"ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَآ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ","transliteration":"Aantum anshatum shajarataha am nahnu almunshioona","english":"Is it you who produced its tree, or are We the producer"},{"number":73,"arabic":"نَحۡنُ جَعَلۡنَٰهَا تَذۡكِرَةٗ وَمَتَٰعٗا لِّلۡمُقۡوِينَ","transliteration":"Nahnu jaAAalnaha tathkiratan wamataAAan lilmuqweena","english":"We have made it a reminder and provision for the travelers"},{"number":74,"arabic":"فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ","transliteration":"Fasabbih biismi rabbika alAAatheemi","english":"So exalt the name of your Lord, the Most Great"},{"number":75,"arabic":"۞فَلَآ أُقۡسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ","transliteration":"Fala oqsimu bimawaqiAAi alnnujoomi","english":"Then I swear by the setting of the stars"},{"number":76,"arabic":"وَإِنَّهُۥ لَقَسَمٞ لَّوۡ تَعۡلَمُونَ عَظِيمٌ","transliteration":"Wainnahu laqasamun law taAAlamoona AAatheemun","english":"And indeed, it is an oath - if you could know - [most] great"},{"number":77,"arabic":"إِنَّهُۥ لَقُرۡءَانٞ كَرِيمٞ","transliteration":"Innahu laquranun kareemun","english":"Indeed, it is a noble Qur'an"},{"number":78,"arabic":"فِي كِتَٰبٖ مَّكۡنُونٖ","transliteration":"Fee kitabin maknoonin","english":"In a Register well-protected"},{"number":79,"arabic":"لَّا يَمَسُّهُۥٓ إِلَّا ٱلۡمُطَهَّرُونَ","transliteration":"La yamassuhu illa almutahharoona","english":"None touch it except the purified"},{"number":80,"arabic":"تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ","transliteration":"Tanzeelun min rabbi alAAalameena","english":"[It is] a revelation from the Lord of the worlds"},{"number":81,"arabic":"أَفَبِهَٰذَا ٱلۡحَدِيثِ أَنتُم مُّدۡهِنُونَ","transliteration":"Afabihatha alhadeethi antum mudhinoona","english":"Then is it to this statement that you are indifferent"},{"number":82,"arabic":"وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ","transliteration":"WatajAAaloona rizqakum annakum tukaththiboona","english":"And make [the thanks for] your provision that you deny [the Provider]"},{"number":83,"arabic":"فَلَوۡلَآ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ","transliteration":"Falawla itha balaghati alhulqooma","english":"Then why, when the soul at death reaches the throat"},{"number":84,"arabic":"وَأَنتُمۡ حِينَئِذٖ تَنظُرُونَ","transliteration":"Waantum heenaithin tanthuroona","english":"And you are at that time looking on"},{"number":85,"arabic":"وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنكُمۡ وَلَٰكِن لَّا تُبۡصِرُونَ","transliteration":"Wanahnu aqrabu ilayhi minkum walakin la tubsiroona","english":"And Our angels are nearer to him than you, but you do not see"},{"number":86,"arabic":"فَلَوۡلَآ إِن كُنتُمۡ غَيۡرَ مَدِينِينَ","transliteration":"Falawla in kuntum ghayra madeeneena","english":"Then why do you not, if you are not to be recompensed"},{"number":87,"arabic":"تَرۡجِعُونَهَآ إِن كُنتُمۡ صَٰدِقِينَ","transliteration":"TarjiAAoonaha in kuntum sadiqeena","english":"Bring it back, if you should be truthful"},{"number":88,"arabic":"فَأَمَّآ إِن كَانَ مِنَ ٱلۡمُقَرَّبِينَ","transliteration":"Faamma in kana mina almuqarrabeena","english":"And if the deceased was of those brought near to Allah"},{"number":89,"arabic":"فَرَوۡحٞ وَرَيۡحَانٞ وَجَنَّتُ نَعِيمٖ","transliteration":"Farawhun warayhanun wajannatu naAAeemin","english":"Then [for him is] rest and bounty and a garden of pleasure"},{"number":90,"arabic":"وَأَمَّآ إِن كَانَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ","transliteration":"Waamma in kana min ashabi alyameeni","english":"And if he was of the companions of the right"},{"number":91,"arabic":"فَسَلَٰمٞ لَّكَ مِنۡ أَصۡحَٰبِ ٱلۡيَمِينِ","transliteration":"Fasalamun laka min ashabi alyameeni","english":"Then [the angels will say], \"Peace for you; [you are] from the companions of the right"},{"number":92,"arabic":"وَأَمَّآ إِن كَانَ مِنَ ٱلۡمُكَذِّبِينَ ٱلضَّآلِّينَ","transliteration":"Waamma in kana mina almukaththibeena alddalleena","english":"But if he was of the deniers [who were] astray"},{"number":93,"arabic":"فَنُزُلٞ مِّنۡ حَمِيمٖ","transliteration":"Fanuzulun min hameemin","english":"Then [for him is] accommodation of scalding water"},{"number":94,"arabic":"وَتَصۡلِيَةُ جَحِيمٍ","transliteration":"Watasliyatu jaheemin","english":"And burning in Hellfire"},{"number":95,"arabic":"إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلۡيَقِينِ","transliteration":"Inna hatha lahuwa haqqu alyaqeeni","english":"Indeed, this is the true certainty"},{"number":96,"arabic":"فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ","transliteration":"Fasabbih biismi rabbika alAAatheemi","english":"So exalt the name of your Lord, the Most Great"}]},{"number":55,"name":"Ar-Rahman","arabicName":"الرحمن","meaning":"The Beneficent","minutes":8.8,"ayahs":[{"number":1,"arabic":"ٱلرَّحۡمَٰنُ","transliteration":"Alrrahmanu","english":"The Most Merciful"},{"number":2,"arabic":"عَلَّمَ ٱلۡقُرۡءَانَ","transliteration":"AAallama alqurana","english":"Taught the Qur'an"},{"number":3,"arabic":"خَلَقَ ٱلۡإِنسَٰنَ","transliteration":"Khalaqa alinsana","english":"Created man"},{"number":4,"arabic":"عَلَّمَهُ ٱلۡبَيَانَ","transliteration":"AAallamahu albayana","english":"[And] taught him eloquence"},{"number":5,"arabic":"ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانٖ","transliteration":"Alshshamsu waalqamaru bihusbanin","english":"The sun and the moon [move] by precise calculation"},{"number":6,"arabic":"وَٱلنَّجۡمُ وَٱلشَّجَرُ يَسۡجُدَانِ","transliteration":"Waalnnajmu waalshshajaru yasjudani","english":"And the stars and trees prostrate"},{"number":7,"arabic":"وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلۡمِيزَانَ","transliteration":"Waalssamaa rafaAAaha wawadaAAa almeezana","english":"And the heaven He raised and imposed the balance"},{"number":8,"arabic":"أَلَّا تَطۡغَوۡاْ فِي ٱلۡمِيزَانِ","transliteration":"Alla tatghaw fee almeezani","english":"That you not transgress within the balance"},{"number":9,"arabic":"وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُواْ ٱلۡمِيزَانَ","transliteration":"Waaqeemoo alwazna bialqisti wala tukhsiroo almeezana","english":"And establish weight in justice and do not make deficient the balance"},{"number":10,"arabic":"وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ","transliteration":"Waalarda wadaAAaha lilanami","english":"And the earth He laid [out] for the creatures"},{"number":11,"arabic":"فِيهَا فَٰكِهَةٞ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ","transliteration":"Feeha fakihatun waalnnakhlu thatu alakmami","english":"Therein is fruit and palm trees having sheaths [of dates]"},{"number":12,"arabic":"وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّيۡحَانُ","transliteration":"Waalhabbu thoo alAAasfi waalrrayhani","english":"And grain having husks and scented plants"},{"number":13,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":14,"arabic":"خَلَقَ ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ كَٱلۡفَخَّارِ","transliteration":"Khalaqa alinsana min salsalin kaalfakhkhari","english":"He created man from clay like [that of] pottery"},{"number":15,"arabic":"وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجٖ مِّن نَّارٖ","transliteration":"Wakhalaqa aljanna min marijin min narin","english":"And He created the jinn from a smokeless flame of fire"},{"number":16,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":17,"arabic":"رَبُّ ٱلۡمَشۡرِقَيۡنِ وَرَبُّ ٱلۡمَغۡرِبَيۡنِ","transliteration":"Rabbu almashriqayni warabbu almaghribayni","english":"[He is] Lord of the two sunrises and Lord of the two sunsets"},{"number":18,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":19,"arabic":"مَرَجَ ٱلۡبَحۡرَيۡنِ يَلۡتَقِيَانِ","transliteration":"Maraja albahrayni yaltaqiyani","english":"He released the two seas, meeting [side by side]"},{"number":20,"arabic":"بَيۡنَهُمَا بَرۡزَخٞ لَّا يَبۡغِيَانِ","transliteration":"Baynahuma barzakhun la yabghiyani","english":"Between them is a barrier [so] neither of them transgresses"},{"number":21,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":22,"arabic":"يَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ","transliteration":"Yakhruju minhuma alluluo waalmarjanu","english":"From both of them emerge pearl and coral"},{"number":23,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":24,"arabic":"وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ","transliteration":"Walahu aljawari almunshaatu fee albahri kaalaAAlami","english":"And to Him belong the ships [with sails] elevated in the sea like mountains"},{"number":25,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":26,"arabic":"كُلُّ مَنۡ عَلَيۡهَا فَانٖ","transliteration":"Kullu man AAalayha fanin","english":"Everyone upon the earth will perish"},{"number":27,"arabic":"وَيَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ","transliteration":"Wayabqa wajhu rabbika thoo aljalali waalikrami","english":"And there will remain the Face of your Lord, Owner of Majesty and Honor"},{"number":28,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":29,"arabic":"يَسۡـَٔلُهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ كُلَّ يَوۡمٍ هُوَ فِي شَأۡنٖ","transliteration":"Yasaluhu man fee alssamawati waalardi kulla yawmin huwa fee shanin","english":"Whoever is within the heavens and earth asks Him; every day He is bringing about a matter"},{"number":30,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":31,"arabic":"سَنَفۡرُغُ لَكُمۡ أَيُّهَ ٱلثَّقَلَانِ","transliteration":"Sanafrughu lakum ayyuha alththaqalani","english":"We will attend to you, O prominent beings"},{"number":32,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":33,"arabic":"يَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُواْ مِنۡ أَقۡطَارِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ فَٱنفُذُواْۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَٰنٖ","transliteration":"Ya maAAshara aljinni waalinsi ini istataAAtum an tanfuthoo min aqtari alssamawati waalardi faonfuthoo la tanfuthoona illa bisultanin","english":"O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah]"},{"number":34,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":35,"arabic":"يُرۡسَلُ عَلَيۡكُمَا شُوَاظٞ مِّن نَّارٖ وَنُحَاسٞ فَلَا تَنتَصِرَانِ","transliteration":"Yursalu AAalaykuma shuwathun min narin wanuhasun fala tantasirani","english":"There will be sent upon you a flame of fire and smoke, and you will not defend yourselves"},{"number":36,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":37,"arabic":"فَإِذَا ٱنشَقَّتِ ٱلسَّمَآءُ فَكَانَتۡ وَرۡدَةٗ كَٱلدِّهَانِ","transliteration":"Faitha inshaqqati alssamao fakanat wardatan kaalddihani","english":"And when the heaven is split open and becomes rose-colored like oil"},{"number":38,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":39,"arabic":"فَيَوۡمَئِذٖ لَّا يُسۡـَٔلُ عَن ذَنۢبِهِۦٓ إِنسٞ وَلَا جَآنّٞ","transliteration":"Fayawmaithin la yusalu AAan thanbihi insun wala jannun","english":"Then on that Day none will be asked about his sin among men or jinn"},{"number":40,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":41,"arabic":"يُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِيمَٰهُمۡ فَيُؤۡخَذُ بِٱلنَّوَٰصِي وَٱلۡأَقۡدَامِ","transliteration":"YuAArafu almujrimoona biseemahum fayukhathu bialnnawasee waalaqdami","english":"The criminals will be known by their marks, and they will be seized by the forelocks and the feet"},{"number":42,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":43,"arabic":"هَٰذِهِۦ جَهَنَّمُ ٱلَّتِي يُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ","transliteration":"Hathihi jahannamu allatee yukaththibu biha almujrimoona","english":"This is Hell, which the criminals deny"},{"number":44,"arabic":"يَطُوفُونَ بَيۡنَهَا وَبَيۡنَ حَمِيمٍ ءَانٖ","transliteration":"Yatoofoona baynaha wabayna hameemin anin","english":"They will go around between it and scalding water, heated [to the utmost degree]"},{"number":45,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":46,"arabic":"وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ","transliteration":"Waliman khafa maqama rabbihi jannatani","english":"But for he who has feared the position of his Lord are two gardens"},{"number":47,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":48,"arabic":"ذَوَاتَآ أَفۡنَانٖ","transliteration":"Thawata afnanin","english":"Having [spreading] branches"},{"number":49,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":50,"arabic":"فِيهِمَا عَيۡنَانِ تَجۡرِيَانِ","transliteration":"Feehima AAaynani tajriyani","english":"In both of them are two springs, flowing"},{"number":51,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":52,"arabic":"فِيهِمَا مِن كُلِّ فَٰكِهَةٖ زَوۡجَانِ","transliteration":"Feehima min kulli fakihatin zawjani","english":"In both of them are of every fruit, two kinds"},{"number":53,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":54,"arabic":"مُتَّكِـِٔينَ عَلَىٰ فُرُشِۭ بَطَآئِنُهَا مِنۡ إِسۡتَبۡرَقٖۚ وَجَنَى ٱلۡجَنَّتَيۡنِ دَانٖ","transliteration":"Muttakieena AAala furushin batainuha min istabraqin wajana aljannatayni danin","english":"[They are] reclining on beds whose linings are of silk brocade, and the fruit of the two gardens is hanging low"},{"number":55,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":56,"arabic":"فِيهِنَّ قَٰصِرَٰتُ ٱلطَّرۡفِ لَمۡ يَطۡمِثۡهُنَّ إِنسٞ قَبۡلَهُمۡ وَلَا جَآنّٞ","transliteration":"Feehinna qasiratu alttarfi lam yatmithhunna insun qablahum wala jannun","english":"In them are women limiting [their] glances, untouched before them by man or jinni"},{"number":57,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":58,"arabic":"كَأَنَّهُنَّ ٱلۡيَاقُوتُ وَٱلۡمَرۡجَانُ","transliteration":"Kaannahunna alyaqootu waalmarjanu","english":"As if they were rubies and coral"},{"number":59,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":60,"arabic":"هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ","transliteration":"Hal jazao alihsani illa alihsanu","english":"Is the reward for good [anything] but good"},{"number":61,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":62,"arabic":"وَمِن دُونِهِمَا جَنَّتَانِ","transliteration":"Wamin doonihima jannatani","english":"And below them both [in excellence] are two [other] gardens"},{"number":63,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":64,"arabic":"مُدۡهَآمَّتَانِ","transliteration":"Mudhammatani","english":"Dark green [in color]"},{"number":65,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":66,"arabic":"فِيهِمَا عَيۡنَانِ نَضَّاخَتَانِ","transliteration":"Feehima AAaynani naddakhatani","english":"In both of them are two springs, spouting"},{"number":67,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":68,"arabic":"فِيهِمَا فَٰكِهَةٞ وَنَخۡلٞ وَرُمَّانٞ","transliteration":"Feehima fakihatun wanakhlun warummanun","english":"In both of them are fruit and palm trees and pomegranates"},{"number":69,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":70,"arabic":"فِيهِنَّ خَيۡرَٰتٌ حِسَانٞ","transliteration":"Feehinna khayratun hisanun","english":"In them are good and beautiful women"},{"number":71,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":72,"arabic":"حُورٞ مَّقۡصُورَٰتٞ فِي ٱلۡخِيَامِ","transliteration":"Hoorun maqsooratun fee alkhiyami","english":"Fair ones reserved in pavilions"},{"number":73,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":74,"arabic":"لَمۡ يَطۡمِثۡهُنَّ إِنسٞ قَبۡلَهُمۡ وَلَا جَآنّٞ","transliteration":"Lam yatmithhunna insun qablahum wala jannun","english":"Untouched before them by man or jinni"},{"number":75,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":76,"arabic":"مُتَّكِـِٔينَ عَلَىٰ رَفۡرَفٍ خُضۡرٖ وَعَبۡقَرِيٍّ حِسَانٖ","transliteration":"Muttakieena AAala rafrafin khudrin waAAabqariyyin hisanin","english":"Reclining on green cushions and beautiful fine carpets"},{"number":77,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ","transliteration":"Fabiayyi alai rabbikuma tukaththibani","english":"So which of the favors of your Lord would you deny"},{"number":78,"arabic":"تَبَٰرَكَ ٱسۡمُ رَبِّكَ ذِي ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ","transliteration":"Tabaraka ismu rabbika thee aljalali waalikrami","english":"Blessed is the name of your Lord, Owner of Majesty and Honor"}]},{"number":54,"name":"Al-Qamar","arabicName":"القمر","meaning":"The Moon","minutes":7.7,"ayahs":[{"number":1,"arabic":"ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ","transliteration":"Iqtarabati alssaAAatu wainshaqqa alqamaru","english":"The Hour has come near, and the moon has split [in two]"},{"number":2,"arabic":"وَإِن يَرَوۡاْ ءَايَةٗ يُعۡرِضُواْ وَيَقُولُواْ سِحۡرٞ مُّسۡتَمِرّٞ","transliteration":"Wain yaraw ayatan yuAAridoo wayaqooloo sihrun mustamirrun","english":"And if they see a miracle, they turn away and say, \"Passing magic"},{"number":3,"arabic":"وَكَذَّبُواْ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡۚ وَكُلُّ أَمۡرٖ مُّسۡتَقِرّٞ","transliteration":"Wakaththaboo waittabaAAoo ahwaahum wakullu amrin mustaqirrun","english":"And they denied and followed their inclinations. But for every matter is a [time of] settlement"},{"number":4,"arabic":"وَلَقَدۡ جَآءَهُم مِّنَ ٱلۡأَنۢبَآءِ مَا فِيهِ مُزۡدَجَرٌ","transliteration":"Walaqad jaahum mina alanbai ma feehi muzdajarun","english":"And there has already come to them of information that in which there is deterrence"},{"number":5,"arabic":"حِكۡمَةُۢ بَٰلِغَةٞۖ فَمَا تُغۡنِ ٱلنُّذُرُ","transliteration":"Hikmatun balighatun fama tughnee alnnuthuru","english":"Extensive wisdom - but warning does not avail [them]"},{"number":6,"arabic":"فَتَوَلَّ عَنۡهُمۡۘ يَوۡمَ يَدۡعُ ٱلدَّاعِ إِلَىٰ شَيۡءٖ نُّكُرٍ","transliteration":"Fatawalla AAanhum yawma yadAAu alddaAAi ila shayin nukurin","english":"So leave them, [O Muhammad]. The Day the Caller calls to something forbidding"},{"number":7,"arabic":"خُشَّعًا أَبۡصَٰرُهُمۡ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادٞ مُّنتَشِرٞ","transliteration":"KhushshaAAan absaruhum yakhrujoona mina alajdathi kaannahum jaradun muntashirun","english":"Their eyes humbled, they will emerge from the graves as if they were locusts spreading"},{"number":8,"arabic":"مُّهۡطِعِينَ إِلَى ٱلدَّاعِۖ يَقُولُ ٱلۡكَٰفِرُونَ هَٰذَا يَوۡمٌ عَسِرٞ","transliteration":"MuhtiAAeena ila alddaAAi yaqoolu alkafiroona hatha yawmun AAasirun","english":"Racing ahead toward the Caller. The disbelievers will say, \"This is a difficult Day"},{"number":9,"arabic":"۞كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ فَكَذَّبُواْ عَبۡدَنَا وَقَالُواْ مَجۡنُونٞ وَٱزۡدُجِرَ","transliteration":"Kaththabat qablahum qawmu noohin fakaththaboo AAabdana waqaloo majnoonun waizdujira","english":"The people of Noah denied before them, and they denied Our servant and said, \"A madman,\" and he was repelled"},{"number":10,"arabic":"فَدَعَا رَبَّهُۥٓ أَنِّي مَغۡلُوبٞ فَٱنتَصِرۡ","transliteration":"FadaAAa rabbahu annee maghloobun faintasir","english":"So he invoked his Lord, \"Indeed, I am overpowered, so help"},{"number":11,"arabic":"فَفَتَحۡنَآ أَبۡوَٰبَ ٱلسَّمَآءِ بِمَآءٖ مُّنۡهَمِرٖ","transliteration":"Fafatahna abwaba alssamai bimain munhamirin","english":"Then We opened the gates of the heaven with rain pouring down"},{"number":12,"arabic":"وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونٗا فَٱلۡتَقَى ٱلۡمَآءُ عَلَىٰٓ أَمۡرٖ قَدۡ قُدِرَ","transliteration":"Wafajjarna alarda AAuyoonan failtaqa almao AAala amrin qad qudira","english":"And caused the earth to burst with springs, and the waters met for a matter already predestined"},{"number":13,"arabic":"وَحَمَلۡنَٰهُ عَلَىٰ ذَاتِ أَلۡوَٰحٖ وَدُسُرٖ","transliteration":"Wahamalnahu AAala thati alwahin wadusurin","english":"And We carried him on a [construction of] planks and nails"},{"number":14,"arabic":"تَجۡرِي بِأَعۡيُنِنَا جَزَآءٗ لِّمَن كَانَ كُفِرَ","transliteration":"Tajree biaAAyunina jazaan liman kana kufira","english":"Sailing under Our observation as reward for he who had been denied"},{"number":15,"arabic":"وَلَقَد تَّرَكۡنَٰهَآ ءَايَةٗ فَهَلۡ مِن مُّدَّكِرٖ","transliteration":"Walaqad taraknaha ayatan fahal min muddakirin","english":"And We left it as a sign, so is there any who will remember"},{"number":16,"arabic":"فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","transliteration":"Fakayfa kana AAathabee wanuthuri","english":"And how [severe] were My punishment and warning"},{"number":17,"arabic":"وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ","transliteration":"Walaqad yassarna alqurana lilththikri fahal min muddakirin","english":"And We have certainly made the Qur'an easy for remembrance, so is there any who will remember"},{"number":18,"arabic":"كَذَّبَتۡ عَادٞ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","transliteration":"Kaththabat AAadun fakayfa kana AAathabee wanuthuri","english":"Aad denied; and how [severe] were My punishment and warning"},{"number":19,"arabic":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِي يَوۡمِ نَحۡسٖ مُّسۡتَمِرّٖ","transliteration":"Inna arsalna AAalayhim reehan sarsaran fee yawmi nahsin mustamirrin","english":"Indeed, We sent upon them a screaming wind on a day of continuous misfortune"},{"number":20,"arabic":"تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٖ مُّنقَعِرٖ","transliteration":"TanziAAu alnnasa kaannahum aAAjazu nakhlin munqaAAirin","english":"Extracting the people as if they were trunks of palm trees uprooted"},{"number":21,"arabic":"فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","transliteration":"Fakayfa kana AAathabee wanuthuri","english":"And how [severe] were My punishment and warning"},{"number":22,"arabic":"وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ","transliteration":"Walaqad yassarna alqurana lilththikri fahal min muddakirin","english":"And We have certainly made the Qur'an easy for remembrance, so is there any who will remember"},{"number":23,"arabic":"كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ","transliteration":"Kaththabat thamoodu bialnnuthuri","english":"Thamud denied the warning"},{"number":24,"arabic":"فَقَالُوٓاْ أَبَشَرٗا مِّنَّا وَٰحِدٗا نَّتَّبِعُهُۥٓ إِنَّآ إِذٗا لَّفِي ضَلَٰلٖ وَسُعُرٍ","transliteration":"Faqaloo abasharan minna wahidan nattabiAAuhu inna ithan lafee dalalin wasuAAurin","english":"And said, \"Is it one human being among us that we should follow? Indeed, we would then be in error and madness"},{"number":25,"arabic":"أَءُلۡقِيَ ٱلذِّكۡرُ عَلَيۡهِ مِنۢ بَيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرٞ","transliteration":"Aolqiya alththikru AAalayhi min baynina bal huwa kaththabun ashirun","english":"Has the message been sent down upon him from among us? Rather, he is an insolent liar"},{"number":26,"arabic":"سَيَعۡلَمُونَ غَدٗا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ","transliteration":"SayaAAlamoona ghadan mani alkaththabu alashiru","english":"They will know tomorrow who is the insolent liar"},{"number":27,"arabic":"إِنَّا مُرۡسِلُواْ ٱلنَّاقَةِ فِتۡنَةٗ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ","transliteration":"Inna mursiloo alnnaqati fitnatan lahum fairtaqibhum waistabir","english":"Indeed, We are sending the she-camel as trial for them, so watch them and be patient"},{"number":28,"arabic":"وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَآءَ قِسۡمَةُۢ بَيۡنَهُمۡۖ كُلُّ شِرۡبٖ مُّحۡتَضَرٞ","transliteration":"Wanabbihum anna almaa qismatun baynahum kullu shirbin muhtadarun","english":"And inform them that the water is shared between them, each [day of] drink attended [by turn]"},{"number":29,"arabic":"فَنَادَوۡاْ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ","transliteration":"Fanadaw sahibahum fataAAata faAAaqara","english":"But they called their companion, and he dared and hamstrung [her]"},{"number":30,"arabic":"فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ","transliteration":"Fakayfa kana AAathabee wanuthuri","english":"And how [severe] were My punishment and warning"},{"number":31,"arabic":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَةٗ وَٰحِدَةٗ فَكَانُواْ كَهَشِيمِ ٱلۡمُحۡتَظِرِ","transliteration":"Inna arsalna AAalayhim sayhatan wahidatan fakanoo kahasheemi almuhtathiri","english":"Indeed, We sent upon them one blast from the sky, and they became like the dry twig fragments of an [animal] pen"},{"number":32,"arabic":"وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ","transliteration":"Walaqad yassarna alqurana lilththikri fahal min muddakirin","english":"And We have certainly made the Qur'an easy for remembrance, so is there any who will remember"},{"number":33,"arabic":"كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ","transliteration":"Kaththabat qawmu lootin bialnnuthuri","english":"The people of Lot denied the warning"},{"number":34,"arabic":"إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلَّآ ءَالَ لُوطٖۖ نَّجَّيۡنَٰهُم بِسَحَرٖ","transliteration":"Inna arsalna AAalayhim hasiban illa ala lootin najjaynahum bisaharin","english":"Indeed, We sent upon them a storm of stones, except the family of Lot - We saved them before dawn"},{"number":35,"arabic":"نِّعۡمَةٗ مِّنۡ عِندِنَاۚ كَذَٰلِكَ نَجۡزِي مَن شَكَرَ","transliteration":"NiAAmatan min AAindina kathalika najzee man shakara","english":"As favor from us. Thus do We reward he who is grateful"},{"number":36,"arabic":"وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡاْ بِٱلنُّذُرِ","transliteration":"Walaqad antharahum batshatana fatamaraw bialnnuthuri","english":"And he had already warned them of Our assault, but they disputed the warning"},{"number":37,"arabic":"وَلَقَدۡ رَٰوَدُوهُ عَن ضَيۡفِهِۦ فَطَمَسۡنَآ أَعۡيُنَهُمۡ فَذُوقُواْ عَذَابِي وَنُذُرِ","transliteration":"Walaqad rawadoohu AAan dayfihi fatamasna aAAyunahum fathooqoo AAathabee wanuthuri","english":"And they had demanded from him his guests, but We obliterated their eyes, [saying], \"Taste My punishment and warning"},{"number":38,"arabic":"وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابٞ مُّسۡتَقِرّٞ","transliteration":"Walaqad sabbahahum bukratan AAathabun mustaqirrun","english":"And there came upon them by morning an abiding punishment"},{"number":39,"arabic":"فَذُوقُواْ عَذَابِي وَنُذُرِ","transliteration":"Fathooqoo AAathabee wanuthuri","english":"So taste My punishment and warning"},{"number":40,"arabic":"وَلَقَدۡ يَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرٖ","transliteration":"Walaqad yassarna alqurana lilththikri fahal min muddakirin","english":"And We have certainly made the Qur'an easy for remembrance, so is there any who will remember"},{"number":41,"arabic":"وَلَقَدۡ جَآءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ","transliteration":"Walaqad jaa ala firAAawna alnnuthuru","english":"And there certainly came to the people of Pharaoh warning"},{"number":42,"arabic":"كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذۡنَٰهُمۡ أَخۡذَ عَزِيزٖ مُّقۡتَدِرٍ","transliteration":"Kaththaboo biayatina kulliha faakhathnahum akhtha AAazeezin muqtadirin","english":"They denied Our signs, all of them, so We seized them with a seizure of one Exalted in Might and Perfect in Ability"},{"number":43,"arabic":"أَكُفَّارُكُمۡ خَيۡرٞ مِّنۡ أُوْلَـٰٓئِكُمۡ أَمۡ لَكُم بَرَآءَةٞ فِي ٱلزُّبُرِ","transliteration":"Akuffarukum khayrun min olaikum am lakum baraatun fee alzzuburi","english":"Are your disbelievers better than those [former ones], or have you immunity in the scripture"},{"number":44,"arabic":"أَمۡ يَقُولُونَ نَحۡنُ جَمِيعٞ مُّنتَصِرٞ","transliteration":"Am yaqooloona nahnu jameeAAun muntasirun","english":"Or do they say, \"We are an assembly supporting [each other]"},{"number":45,"arabic":"سَيُهۡزَمُ ٱلۡجَمۡعُ وَيُوَلُّونَ ٱلدُّبُرَ","transliteration":"Sayuhzamu aljamAAu wayuwalloona alddubura","english":"[Their] assembly will be defeated, and they will turn their backs [in retreat]"},{"number":46,"arabic":"بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ","transliteration":"Bali alssaAAatu mawAAiduhum waalssaAAatu adha waamarru","english":"But the Hour is their appointment [for due punishment], and the Hour is more disastrous and more bitter"},{"number":47,"arabic":"إِنَّ ٱلۡمُجۡرِمِينَ فِي ضَلَٰلٖ وَسُعُرٖ","transliteration":"Inna almujrimeena fee dalalin wasuAAurin","english":"Indeed, the criminals are in error and madness"},{"number":48,"arabic":"يَوۡمَ يُسۡحَبُونَ فِي ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُواْ مَسَّ سَقَرَ","transliteration":"Yawma yushaboona fee alnnari AAala wujoohihim thooqoo massa saqara","english":"The Day they are dragged into the Fire on their faces [it will be said], \"Taste the touch of Saqar"},{"number":49,"arabic":"إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرٖ","transliteration":"Inna kulla shayin khalaqnahu biqadarin","english":"Indeed, all things We created with predestination"},{"number":50,"arabic":"وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةٞ كَلَمۡحِۭ بِٱلۡبَصَرِ","transliteration":"Wama amruna illa wahidatun kalamhin bialbasari","english":"And Our command is but one, like a glance of the eye"},{"number":51,"arabic":"وَلَقَدۡ أَهۡلَكۡنَآ أَشۡيَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرٖ","transliteration":"Walaqad ahlakna ashyaAAakum fahal min muddakirin","english":"And We have already destroyed your kinds, so is there any who will remember"},{"number":52,"arabic":"وَكُلُّ شَيۡءٖ فَعَلُوهُ فِي ٱلزُّبُرِ","transliteration":"Wakullu shayin faAAaloohu fee alzzuburi","english":"And everything they did is in written records"},{"number":53,"arabic":"وَكُلُّ صَغِيرٖ وَكَبِيرٖ مُّسۡتَطَرٌ","transliteration":"Wakullu sagheerin wakabeerin mustatarun","english":"And every small and great [thing] is inscribed"},{"number":54,"arabic":"إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَنَهَرٖ","transliteration":"Inna almuttaqeena fee jannatin wanaharin","english":"Indeed, the righteous will be among gardens and rivers"},{"number":55,"arabic":"فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۭ","transliteration":"Fee maqAAadi sidqin AAinda maleekin muqtadirin","english":"In a seat of honor near a Sovereign, Perfect in Ability"}]},{"number":53,"name":"An-Najm","arabicName":"النجم","meaning":"The Star","minutes":7.5,"ayahs":[{"number":1,"arabic":"وَٱلنَّجۡمِ إِذَا هَوَىٰ","transliteration":"Waalnnajmi itha hawa","english":"By the star when it descends"},{"number":2,"arabic":"مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ","transliteration":"Ma dalla sahibukum wama ghawa","english":"Your companion [Muhammad] has not strayed, nor has he erred"},{"number":3,"arabic":"وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ","transliteration":"Wama yantiqu AAani alhawa","english":"Nor does he speak from [his own] inclination"},{"number":4,"arabic":"إِنۡ هُوَ إِلَّا وَحۡيٞ يُوحَىٰ","transliteration":"In huwa illa wahyun yooha","english":"It is not but a revelation revealed"},{"number":5,"arabic":"عَلَّمَهُۥ شَدِيدُ ٱلۡقُوَىٰ","transliteration":"AAallamahu shadeedu alquwa","english":"Taught to him by one intense in strength"},{"number":6,"arabic":"ذُو مِرَّةٖ فَٱسۡتَوَىٰ","transliteration":"Thoo mirratin faistawa","english":"One of soundness. And he rose to [his] true form"},{"number":7,"arabic":"وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ","transliteration":"Wahuwa bialofuqi alaAAla","english":"While he was in the higher [part of the] horizon"},{"number":8,"arabic":"ثُمَّ دَنَا فَتَدَلَّىٰ","transliteration":"Thumma dana fatadalla","english":"Then he approached and descended"},{"number":9,"arabic":"فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَدۡنَىٰ","transliteration":"Fakana qaba qawsayni aw adna","english":"And was at a distance of two bow lengths or nearer"},{"number":10,"arabic":"فَأَوۡحَىٰٓ إِلَىٰ عَبۡدِهِۦ مَآ أَوۡحَىٰ","transliteration":"Faawha ila AAabdihi ma awha","english":"And he revealed to His Servant what he revealed"},{"number":11,"arabic":"مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰٓ","transliteration":"Ma kathaba alfuadu ma raa","english":"The heart did not lie [about] what it saw"},{"number":12,"arabic":"أَفَتُمَٰرُونَهُۥ عَلَىٰ مَا يَرَىٰ","transliteration":"Afatumaroonahu AAala ma yara","english":"So will you dispute with him over what he saw"},{"number":13,"arabic":"وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ","transliteration":"Walaqad raahu nazlatan okhra","english":"And he certainly saw him in another descent"},{"number":14,"arabic":"عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ","transliteration":"AAinda sidrati almuntaha","english":"At the Lote Tree of the Utmost Boundary"},{"number":15,"arabic":"عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰٓ","transliteration":"AAindaha jannatu almawa","english":"Near it is the Garden of Refuge"},{"number":16,"arabic":"إِذۡ يَغۡشَى ٱلسِّدۡرَةَ مَا يَغۡشَىٰ","transliteration":"Ith yaghsha alssidrata ma yaghsha","english":"When there covered the Lote Tree that which covered [it]"},{"number":17,"arabic":"مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ","transliteration":"Ma zagha albasaru wama tagha","english":"The sight [of the Prophet] did not swerve, nor did it transgress [its limit]"},{"number":18,"arabic":"لَقَدۡ رَأَىٰ مِنۡ ءَايَٰتِ رَبِّهِ ٱلۡكُبۡرَىٰٓ","transliteration":"Laqad raa min ayati rabbihi alkubra","english":"He certainly saw of the greatest signs of his Lord"},{"number":19,"arabic":"أَفَرَءَيۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ","transliteration":"Afaraaytumu allata waalAAuzza","english":"So have you considered al-Lat and al-'Uzza"},{"number":20,"arabic":"وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ","transliteration":"Wamanata alththalithata alokhra","english":"And Manat, the third - the other one"},{"number":21,"arabic":"أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ","transliteration":"Alakumu alththakaru walahu alontha","english":"Is the male for you and for Him the female"},{"number":22,"arabic":"تِلۡكَ إِذٗا قِسۡمَةٞ ضِيزَىٰٓ","transliteration":"Tilka ithan qismatun deeza","english":"That, then, is an unjust division"},{"number":23,"arabic":"إِنۡ هِيَ إِلَّآ أَسۡمَآءٞ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَآءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰٓ","transliteration":"In hiya illa asmaon sammaytumooha antum waabaokum ma anzala Allahu biha min sultanin in yattabiAAoona illa alththanna wama tahwa alanfusu walaqad jaahum min rabbihimu alhuda","english":"They are not but [mere] names you have named them - you and your forefathers - for which Allah has sent down no authority. They follow not except assumption and what [their] souls desire, and there has already come to them from their Lord guidance"},{"number":24,"arabic":"أَمۡ لِلۡإِنسَٰنِ مَا تَمَنَّىٰ","transliteration":"Am lilinsani ma tamanna","english":"Or is there for man whatever he wishes"},{"number":25,"arabic":"فَلِلَّهِ ٱلۡأٓخِرَةُ وَٱلۡأُولَىٰ","transliteration":"Falillahi alakhiratu waaloola","english":"Rather, to Allah belongs the Hereafter and the first [life]"},{"number":26,"arabic":"۞وَكَم مِّن مَّلَكٖ فِي ٱلسَّمَٰوَٰتِ لَا تُغۡنِي شَفَٰعَتُهُمۡ شَيۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن يَأۡذَنَ ٱللَّهُ لِمَن يَشَآءُ وَيَرۡضَىٰٓ","transliteration":"Wakam min malakin fee alssamawati la tughnee shafaAAatuhum shayan illa min baAAdi an yathana Allahu liman yashao wayarda","english":"And how many angels there are in the heavens whose intercession will not avail at all except [only] after Allah has permitted [it] to whom He wills and approves"},{"number":27,"arabic":"إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ لَيُسَمُّونَ ٱلۡمَلَـٰٓئِكَةَ تَسۡمِيَةَ ٱلۡأُنثَىٰ","transliteration":"Inna allatheena la yuminoona bialakhirati layusammoona almalaikata tasmiyata alontha","english":"Indeed, those who do not believe in the Hereafter name the angels female names"},{"number":28,"arabic":"وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا يُغۡنِي مِنَ ٱلۡحَقِّ شَيۡـٔٗا","transliteration":"Wama lahum bihi min AAilmin in yattabiAAoona illa alththanna wainna alththanna la yughnee mina alhaqqi shayan","english":"And they have thereof no knowledge. They follow not except assumption, and indeed, assumption avails not against the truth at all"},{"number":29,"arabic":"فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ يُرِدۡ إِلَّا ٱلۡحَيَوٰةَ ٱلدُّنۡيَا","transliteration":"FaaAArid AAan man tawalla AAan thikrina walam yurid illa alhayata alddunya","english":"So turn away from whoever turns his back on Our message and desires not except the worldly life"},{"number":30,"arabic":"ذَٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ","transliteration":"Thalika mablaghuhum mina alAAilmi inna rabbaka huwa aAAlamu biman dalla AAan sabeelihi wahuwa aAAlamu bimani ihtada","english":"That is their sum of knowledge. Indeed, your Lord is most knowing of who strays from His way, and He is most knowing of who is guided"},{"number":31,"arabic":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ لِيَجۡزِيَ ٱلَّذِينَ أَسَـٰٓـُٔواْ بِمَا عَمِلُواْ وَيَجۡزِيَ ٱلَّذِينَ أَحۡسَنُواْ بِٱلۡحُسۡنَى","transliteration":"Walillahi ma fee alssamawati wama fee alardi liyajziya allatheena asaoo bima AAamiloo wayajziya allatheena ahsanoo bialhusna","english":"And to Allah belongs whatever is in the heavens and whatever is in the earth - that He may recompense those who do evil with [the penalty of] what they have done and recompense those who do good with the best [reward]"},{"number":32,"arabic":"ٱلَّذِينَ يَجۡتَنِبُونَ كَبَـٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةٞ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ","transliteration":"Allatheena yajtaniboona kabaira alithmi waalfawahisha illa allamama inna rabbaka wasiAAu almaghfirati huwa aAAlamu bikum ith anshaakum mina alardi waith antum ajinnatun fee butooni ommahatikum fala tuzakkoo anfusakum huwa aAAlamu bimani ittaqa","english":"Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him"},{"number":33,"arabic":"أَفَرَءَيۡتَ ٱلَّذِي تَوَلَّىٰ","transliteration":"Afaraayta allathee tawalla","english":"Have you seen the one who turned away"},{"number":34,"arabic":"وَأَعۡطَىٰ قَلِيلٗا وَأَكۡدَىٰٓ","transliteration":"WaaAAta qaleelan waakda","english":"And gave a little and [then] refrained"},{"number":35,"arabic":"أَعِندَهُۥ عِلۡمُ ٱلۡغَيۡبِ فَهُوَ يَرَىٰٓ","transliteration":"aAAindahu AAilmu alghaybi fahuwa yara","english":"Does he have knowledge of the unseen, so he sees"},{"number":36,"arabic":"أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِي صُحُفِ مُوسَىٰ","transliteration":"Am lam yunabba bima fee suhufi moosa","english":"Or has he not been informed of what was in the scriptures of Moses"},{"number":37,"arabic":"وَإِبۡرَٰهِيمَ ٱلَّذِي وَفَّىٰٓ","transliteration":"Waibraheema allathee waffa","english":"And [of] Abraham, who fulfilled [his obligations]"},{"number":38,"arabic":"أَلَّا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰ","transliteration":"Alla taziru waziratun wizra okhra","english":"That no bearer of burdens will bear the burden of another"},{"number":39,"arabic":"وَأَن لَّيۡسَ لِلۡإِنسَٰنِ إِلَّا مَا سَعَىٰ","transliteration":"Waan laysa lilinsani illa ma saAAa","english":"And that there is not for man except that [good] for which he strives"},{"number":40,"arabic":"وَأَنَّ سَعۡيَهُۥ سَوۡفَ يُرَىٰ","transliteration":"Waanna saAAyahu sawfa yura","english":"And that his effort is going to be seen"},{"number":41,"arabic":"ثُمَّ يُجۡزَىٰهُ ٱلۡجَزَآءَ ٱلۡأَوۡفَىٰ","transliteration":"Thumma yujzahu aljazaa alawfa","english":"Then he will be recompensed for it with the fullest recompense"},{"number":42,"arabic":"وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ","transliteration":"Waanna ila rabbika almuntaha","english":"And that to your Lord is the finality"},{"number":43,"arabic":"وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ","transliteration":"Waannahu huwa adhaka waabka","english":"And that it is He who makes [one] laugh and weep"},{"number":44,"arabic":"وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡيَا","transliteration":"Waannahu huwa amata waahya","english":"And that it is He who causes death and gives life"},{"number":45,"arabic":"وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ","transliteration":"Waannahu khalaqa alzzawjayni alththakara waalontha","english":"And that He creates the two mates - the male and female"},{"number":46,"arabic":"مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ","transliteration":"Min nutfatin itha tumna","english":"From a sperm-drop when it is emitted"},{"number":47,"arabic":"وَأَنَّ عَلَيۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ","transliteration":"Waanna AAalayhi alnnashata alokhra","english":"And that [incumbent] upon Him is the next creation"},{"number":48,"arabic":"وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ","transliteration":"Waannahu huwa aghna waaqna","english":"And that it is He who enriches and suffices"},{"number":49,"arabic":"وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ","transliteration":"Waannahu huwa rabbu alshshiAAra","english":"And that it is He who is the Lord of Sirius"},{"number":50,"arabic":"وَأَنَّهُۥٓ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ","transliteration":"Waannahu ahlaka AAadan aloola","english":"And that He destroyed the first [people of] 'Aad"},{"number":51,"arabic":"وَثَمُودَاْ فَمَآ أَبۡقَىٰ","transliteration":"Wathamooda fama abqa","english":"And Thamud - and He did not spare [them]"},{"number":52,"arabic":"وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ","transliteration":"Waqawma noohin min qablu innahum kanoo hum athlama waatgha","english":"And the people of Noah before. Indeed, it was they who were [even] more unjust and oppressing"},{"number":53,"arabic":"وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ","transliteration":"Waalmutafikata ahwa","english":"And the overturned towns He hurled down"},{"number":54,"arabic":"فَغَشَّىٰهَا مَا غَشَّىٰ","transliteration":"Faghashshaha ma ghashsha","english":"And covered them by that which He covered"},{"number":55,"arabic":"فَبِأَيِّ ءَالَآءِ رَبِّكَ تَتَمَارَىٰ","transliteration":"Fabiayyi alai rabbika tatamara","english":"Then which of the favors of your Lord do you doubt"},{"number":56,"arabic":"هَٰذَا نَذِيرٞ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰٓ","transliteration":"Hatha natheerun mina alnnuthuri aloola","english":"This [Prophet] is a warner like the former warners"},{"number":57,"arabic":"أَزِفَتِ ٱلۡأٓزِفَةُ","transliteration":"Azifati alazifatu","english":"The Approaching Day has approached"},{"number":58,"arabic":"لَيۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ","transliteration":"Laysa laha min dooni Allahi kashifatun","english":"Of it, [from those] besides Allah, there is no remover"},{"number":59,"arabic":"أَفَمِنۡ هَٰذَا ٱلۡحَدِيثِ تَعۡجَبُونَ","transliteration":"Afamin hatha alhadeethi taAAjaboona","english":"Then at this statement do you wonder"},{"number":60,"arabic":"وَتَضۡحَكُونَ وَلَا تَبۡكُونَ","transliteration":"Watadhakoona wala tabkoona","english":"And you laugh and do not weep"},{"number":61,"arabic":"وَأَنتُمۡ سَٰمِدُونَ","transliteration":"Waantum samidoona","english":"While you are proudly sporting"},{"number":62,"arabic":"فَٱسۡجُدُواْۤ لِلَّهِۤ وَٱعۡبُدُواْ۩","transliteration":"Faosjudoo lillahi waoAAbudoo","english":"So prostrate to Allah and worship [Him]"}]},{"number":52,"name":"At-Tur","arabicName":"الطور","meaning":"The Mount","minutes":6.9,"ayahs":[{"number":1,"arabic":"وَٱلطُّورِ","transliteration":"Waalttoori","english":"By the mount"},{"number":2,"arabic":"وَكِتَٰبٖ مَّسۡطُورٖ","transliteration":"Wakitabin mastoorin","english":"And [by] a Book inscribed"},{"number":3,"arabic":"فِي رَقّٖ مَّنشُورٖ","transliteration":"Fee raqqin manshoorin","english":"In parchment spread open"},{"number":4,"arabic":"وَٱلۡبَيۡتِ ٱلۡمَعۡمُورِ","transliteration":"Waalbayti almaAAmoori","english":"And [by] the frequented House"},{"number":5,"arabic":"وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ","transliteration":"Waalssaqfi almarfooAAi","english":"And [by] the heaven raised high"},{"number":6,"arabic":"وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ","transliteration":"Waalbahri almasjoori","english":"And [by] the sea filled [with fire]"},{"number":7,"arabic":"إِنَّ عَذَابَ رَبِّكَ لَوَٰقِعٞ","transliteration":"Inna AAathaba rabbika lawaqiAAun","english":"Indeed, the punishment of your Lord will occur"},{"number":8,"arabic":"مَّا لَهُۥ مِن دَافِعٖ","transliteration":"Ma lahu min dafiAAin","english":"Of it there is no preventer"},{"number":9,"arabic":"يَوۡمَ تَمُورُ ٱلسَّمَآءُ مَوۡرٗا","transliteration":"Yawma tamooru alssamao mawran","english":"On the Day the heaven will sway with circular motion"},{"number":10,"arabic":"وَتَسِيرُ ٱلۡجِبَالُ سَيۡرٗا","transliteration":"Wataseeru aljibalu sayran","english":"And the mountains will pass on, departing"},{"number":11,"arabic":"فَوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ","transliteration":"Fawaylun yawmaithin lilmukaththibeena","english":"Then woe, that Day, to the deniers"},{"number":12,"arabic":"ٱلَّذِينَ هُمۡ فِي خَوۡضٖ يَلۡعَبُونَ","transliteration":"Allatheena hum fee khawdin yalAAaboona","english":"Who are in [empty] discourse amusing themselves"},{"number":13,"arabic":"يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا","transliteration":"Yawma yudaAAAAoona ila nari jahannama daAAAAan","english":"The Day they are thrust toward the fire of Hell with a [violent] thrust, [its angels will say]"},{"number":14,"arabic":"هَٰذِهِ ٱلنَّارُ ٱلَّتِي كُنتُم بِهَا تُكَذِّبُونَ","transliteration":"Hathihi alnnaru allatee kuntum biha tukaththiboona","english":"This is the Fire which you used to deny"},{"number":15,"arabic":"أَفَسِحۡرٌ هَٰذَآ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ","transliteration":"Afasihrun hatha am antum la tubsiroona","english":"Then is this magic, or do you not see"},{"number":16,"arabic":"ٱصۡلَوۡهَا فَٱصۡبِرُوٓاْ أَوۡ لَا تَصۡبِرُواْ سَوَآءٌ عَلَيۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ","transliteration":"Islawha faisbiroo aw la tasbiroo sawaon AAalaykum innama tujzawna ma kuntum taAAmaloona","english":"[Enter to] burn therein; then be patient or impatient - it is all the same for you. You are only being recompensed [for] what you used to do"},{"number":17,"arabic":"إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَنَعِيمٖ","transliteration":"Inna almuttaqeena fee jannatin wanaAAeemin","english":"Indeed, the righteous will be in gardens and pleasure"},{"number":18,"arabic":"فَٰكِهِينَ بِمَآ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِيمِ","transliteration":"Fakiheena bima atahum rabbuhum wawaqahum rabbuhum AAathaba aljaheemi","english":"Enjoying what their Lord has given them, and their Lord protected them from the punishment of Hellfire"},{"number":19,"arabic":"كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ","transliteration":"Kuloo waishraboo haneean bima kuntum taAAmaloona","english":"[They will be told], \"Eat and drink in satisfaction for what you used to do"},{"number":20,"arabic":"مُتَّكِـِٔينَ عَلَىٰ سُرُرٖ مَّصۡفُوفَةٖۖ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ","transliteration":"Muttakieena AAala sururin masfoofatin wazawwajnahum bihoorin AAeenin","english":"They will be reclining on thrones lined up, and We will marry them to fair women with large, [beautiful] eyes"},{"number":21,"arabic":"وَٱلَّذِينَ ءَامَنُواْ وَٱتَّبَعَتۡهُمۡ ذُرِّيَّتُهُم بِإِيمَٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّيَّتَهُمۡ وَمَآ أَلَتۡنَٰهُم مِّنۡ عَمَلِهِم مِّن شَيۡءٖۚ كُلُّ ٱمۡرِيِٕۭ بِمَا كَسَبَ رَهِينٞ","transliteration":"Waallatheena amanoo waittabaAAathum thurriyyatuhum bieemanin alhaqna bihim thurriyyatahum wama alatnahum min AAamalihim min shayin kullu imriin bima kasaba raheenun","english":"And those who believed and whose descendants followed them in faith - We will join with them their descendants, and We will not deprive them of anything of their deeds. Every person, for what he earned, is retained"},{"number":22,"arabic":"وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ وَلَحۡمٖ مِّمَّا يَشۡتَهُونَ","transliteration":"Waamdadnahum bifakihatin walahmin mimma yashtahoona","english":"And We will provide them with fruit and meat from whatever they desire"},{"number":23,"arabic":"يَتَنَٰزَعُونَ فِيهَا كَأۡسٗا لَّا لَغۡوٞ فِيهَا وَلَا تَأۡثِيمٞ","transliteration":"YatanazaAAoona feeha kasan la laghwun feeha wala tatheemun","english":"They will exchange with one another a cup [of wine] wherein [results] no ill speech or commission of sin"},{"number":24,"arabic":"۞وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَانٞ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤٞ مَّكۡنُونٞ","transliteration":"Wayatoofu AAalayhim ghilmanun lahum kaannahum luluon maknoonun","english":"There will circulate among them [servant] boys [especially] for them, as if they were pearls well-protected"},{"number":25,"arabic":"وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ","transliteration":"Waaqbala baAAduhum AAala baAAdin yatasaaloona","english":"And they will approach one another, inquiring of each other"},{"number":26,"arabic":"قَالُوٓاْ إِنَّا كُنَّا قَبۡلُ فِيٓ أَهۡلِنَا مُشۡفِقِينَ","transliteration":"Qaloo inna kunna qablu fee ahlina mushfiqeena","english":"They will say, \"Indeed, we were previously among our people fearful [of displeasing Allah]"},{"number":27,"arabic":"فَمَنَّ ٱللَّهُ عَلَيۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ","transliteration":"Famanna Allahu AAalayna wawaqana AAathaba alssamoomi","english":"So Allah conferred favor upon us and protected us from the punishment of the Scorching Fire"},{"number":28,"arabic":"إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ","transliteration":"Inna kunna min qablu nadAAoohu innahu huwa albarru alrraheemu","english":"Indeed, we used to supplicate Him before. Indeed, it is He who is the Beneficent, the Merciful"},{"number":29,"arabic":"فَذَكِّرۡ فَمَآ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنٖ وَلَا مَجۡنُونٍ","transliteration":"Fathakkir fama anta biniAAmati rabbika bikahin wala majnoonin","english":"So remind [O Muhammad], for you are not, by the favor of your Lord, a soothsayer or a madman"},{"number":30,"arabic":"أَمۡ يَقُولُونَ شَاعِرٞ نَّتَرَبَّصُ بِهِۦ رَيۡبَ ٱلۡمَنُونِ","transliteration":"Am yaqooloona shaAAirun natarabbasu bihi rayba almanooni","english":"Or do they say [of you], \"A poet for whom we await a misfortune of time"},{"number":31,"arabic":"قُلۡ تَرَبَّصُواْ فَإِنِّي مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِينَ","transliteration":"Qul tarabbasoo fainnee maAAakum mina almutarabbiseena","english":"Say, \"Wait, for indeed I am, with you, among the waiters"},{"number":32,"arabic":"أَمۡ تَأۡمُرُهُمۡ أَحۡلَٰمُهُم بِهَٰذَآۚ أَمۡ هُمۡ قَوۡمٞ طَاغُونَ","transliteration":"Am tamuruhum ahlamuhum bihatha am hum qawmun taghoona","english":"Or do their minds command them to [say] this, or are they a transgressing people"},{"number":33,"arabic":"أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ","transliteration":"Am yaqooloona taqawwalahu bal la yuminoona","english":"Or do they say, \"He has made it up\"? Rather, they do not believe"},{"number":34,"arabic":"فَلۡيَأۡتُواْ بِحَدِيثٖ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ","transliteration":"Falyatoo bihadeethin mithlihi in kanoo sadiqeena","english":"Then let them produce a statement like it, if they should be truthful"},{"number":35,"arabic":"أَمۡ خُلِقُواْ مِنۡ غَيۡرِ شَيۡءٍ أَمۡ هُمُ ٱلۡخَٰلِقُونَ","transliteration":"Am khuliqoo min ghayri shayin am humu alkhaliqoona","english":"Or were they created by nothing, or were they the creators [of themselves]"},{"number":36,"arabic":"أَمۡ خَلَقُواْ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۚ بَل لَّا يُوقِنُونَ","transliteration":"Am khalaqoo alssamawati waalarda bal la yooqinoona","english":"Or did they create the heavens and the earth? Rather, they are not certain"},{"number":37,"arabic":"أَمۡ عِندَهُمۡ خَزَآئِنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۜيۡطِرُونَ","transliteration":"Am AAindahum khazainu rabbika am humu almusaytiroona","english":"Or have they the depositories [containing the provision] of your Lord? Or are they the controllers [of them]"},{"number":38,"arabic":"أَمۡ لَهُمۡ سُلَّمٞ يَسۡتَمِعُونَ فِيهِۖ فَلۡيَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَٰنٖ مُّبِينٍ","transliteration":"Am lahum sullamun yastamiAAoona feehi falyati mustamiAAuhum bisultanin mubeenin","english":"Or have they a stairway [into the heaven] upon which they listen? Then let their listener produce a clear authority"},{"number":39,"arabic":"أَمۡ لَهُ ٱلۡبَنَٰتُ وَلَكُمُ ٱلۡبَنُونَ","transliteration":"Am lahu albanatu walakumu albanoona","english":"Or has He daughters while you have sons"},{"number":40,"arabic":"أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ","transliteration":"Am tasaluhum ajran fahum min maghramin muthqaloona","english":"Or do you, [O Muhammad], ask of them a payment, so they are by debt burdened down"},{"number":41,"arabic":"أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ","transliteration":"Am AAindahumu alghaybu fahum yaktuboona","english":"Or have they [knowledge of] the unseen, so they write [it] down"},{"number":42,"arabic":"أَمۡ يُرِيدُونَ كَيۡدٗاۖ فَٱلَّذِينَ كَفَرُواْ هُمُ ٱلۡمَكِيدُونَ","transliteration":"Am yureedoona kaydan faallatheena kafaroo humu almakeedoona","english":"Or do they intend a plan? But those who disbelieve - they are the object of a plan"},{"number":43,"arabic":"أَمۡ لَهُمۡ إِلَٰهٌ غَيۡرُ ٱللَّهِۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ","transliteration":"Am lahum ilahun ghayru Allahi subhana Allahi AAamma yushrikoona","english":"Or have they a deity other than Allah? Exalted is Allah above whatever they associate with Him"},{"number":44,"arabic":"وَإِن يَرَوۡاْ كِسۡفٗا مِّنَ ٱلسَّمَآءِ سَاقِطٗا يَقُولُواْ سَحَابٞ مَّرۡكُومٞ","transliteration":"Wain yaraw kisfan mina alssamai saqitan yaqooloo sahabun markoomun","english":"And if they were to see a fragment from the sky falling, they would say, \"[It is merely] clouds heaped up"},{"number":45,"arabic":"فَذَرۡهُمۡ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي فِيهِ يُصۡعَقُونَ","transliteration":"Fatharhum hatta yulaqoo yawmahumu allathee feehi yusAAaqoona","english":"So leave them until they meet their Day in which they will be struck insensible"},{"number":46,"arabic":"يَوۡمَ لَا يُغۡنِي عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ","transliteration":"Yawma la yughnee AAanhum kayduhum shayan wala hum yunsaroona","english":"The Day their plan will not avail them at all, nor will they be helped"},{"number":47,"arabic":"وَإِنَّ لِلَّذِينَ ظَلَمُواْ عَذَابٗا دُونَ ذَٰلِكَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","transliteration":"Wainna lillatheena thalamoo AAathaban doona thalika walakinna aktharahum la yaAAlamoona","english":"And indeed, for those who have wronged is a punishment before that, but most of them do not know"},{"number":48,"arabic":"وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ","transliteration":"Waisbir lihukmi rabbika fainnaka biaAAyunina wasabbih bihamdi rabbika heena taqoomu","english":"And be patient, [O Muhammad], for the decision of your Lord, for indeed, you are in Our eyes. And exalt [Allah] with praise of your Lord when you arise"},{"number":49,"arabic":"وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَإِدۡبَٰرَ ٱلنُّجُومِ","transliteration":"Wamina allayli fasabbihhu waidbara alnnujoomi","english":"And in a part of the night exalt Him and after [the setting of] the stars"}]},{"number":51,"name":"Adh-Dhariyat","arabicName":"الذاريات","meaning":"The Winnowing Winds","minutes":8.1,"ayahs":[{"number":1,"arabic":"وَٱلذَّـٰرِيَٰتِ ذَرۡوٗا","transliteration":"Waalththariyati tharwan","english":"By those [winds] scattering [dust] dispersing"},{"number":2,"arabic":"فَٱلۡحَٰمِلَٰتِ وِقۡرٗا","transliteration":"Faalhamilati wiqran","english":"And those [clouds] carrying a load [of water]"},{"number":3,"arabic":"فَٱلۡجَٰرِيَٰتِ يُسۡرٗا","transliteration":"Faaljariyati yusran","english":"And those [ships] sailing with ease"},{"number":4,"arabic":"فَٱلۡمُقَسِّمَٰتِ أَمۡرًا","transliteration":"Faalmuqassimati amran","english":"And those [angels] apportioning [each] matter"},{"number":5,"arabic":"إِنَّمَا تُوعَدُونَ لَصَادِقٞ","transliteration":"Innama tooAAadoona lasadiqun","english":"Indeed, what you are promised is true"},{"number":6,"arabic":"وَإِنَّ ٱلدِّينَ لَوَٰقِعٞ","transliteration":"Wainna alddeena lawaqiAAun","english":"And indeed, the recompense is to occur"},{"number":7,"arabic":"وَٱلسَّمَآءِ ذَاتِ ٱلۡحُبُكِ","transliteration":"Waalssamai thati alhubuki","english":"By the heaven containing pathways"},{"number":8,"arabic":"إِنَّكُمۡ لَفِي قَوۡلٖ مُّخۡتَلِفٖ","transliteration":"Innakum lafee qawlin mukhtalifin","english":"Indeed, you are in differing speech"},{"number":9,"arabic":"يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ","transliteration":"Yufaku AAanhu man ofika","english":"Deluded away from the Qur'an is he who is deluded"},{"number":10,"arabic":"قُتِلَ ٱلۡخَرَّـٰصُونَ","transliteration":"Qutila alkharrasoona","english":"Destroyed are the falsifiers"},{"number":11,"arabic":"ٱلَّذِينَ هُمۡ فِي غَمۡرَةٖ سَاهُونَ","transliteration":"Allatheena hum fee ghamratin sahoona","english":"Who are within a flood [of confusion] and heedless"},{"number":12,"arabic":"يَسۡـَٔلُونَ أَيَّانَ يَوۡمُ ٱلدِّينِ","transliteration":"Yasaloona ayyana yawmu alddeeni","english":"They ask, \"When is the Day of Recompense"},{"number":13,"arabic":"يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ","transliteration":"Yawma hum AAala alnnari yuftanoona","english":"[It is] the Day they will be tormented over the Fire"},{"number":14,"arabic":"ذُوقُواْ فِتۡنَتَكُمۡ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ","transliteration":"Thooqoo fitnatakum hatha allathee kuntum bihi tastaAAjiloona","english":"[And will be told], \"Taste your torment. This is that for which you were impatient"},{"number":15,"arabic":"إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَعُيُونٍ","transliteration":"Inna almuttaqeena fee jannatin waAAuyoonin","english":"Indeed, the righteous will be among gardens and springs"},{"number":16,"arabic":"ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ","transliteration":"Akhitheena ma atahum rabbuhum innahum kanoo qabla thalika muhsineena","english":"Accepting what their Lord has given them. Indeed, they were before that doers of good"},{"number":17,"arabic":"كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ","transliteration":"Kanoo qaleelan mina allayli ma yahjaAAoona","english":"They used to sleep but little of the night"},{"number":18,"arabic":"وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ","transliteration":"Wabialashari hum yastaghfiroona","english":"And in the hours before dawn they would ask forgiveness"},{"number":19,"arabic":"وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","transliteration":"Wafee amwalihim haqqun lilssaili waalmahroomi","english":"And from their properties was [given] the right of the [needy] petitioner and the deprived"},{"number":20,"arabic":"وَفِي ٱلۡأَرۡضِ ءَايَٰتٞ لِّلۡمُوقِنِينَ","transliteration":"Wafee alardi ayatun lilmooqineena","english":"And on the earth are signs for the certain [in faith]"},{"number":21,"arabic":"وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ","transliteration":"Wafee anfusikum afala tubsiroona","english":"And in yourselves. Then will you not see"},{"number":22,"arabic":"وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ","transliteration":"Wafee alssamai rizqukum wama tooAAadoona","english":"And in the heaven is your provision and whatever you are promised"},{"number":23,"arabic":"فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقّٞ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ","transliteration":"Fawarabbi alssamai waalardi innahu lahaqqun mithla ma annakum tantiqoona","english":"Then by the Lord of the heaven and earth, indeed, it is truth - just as [sure as] it is that you are speaking"},{"number":24,"arabic":"هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ","transliteration":"Hal ataka hadeethu dayfi ibraheema almukrameena","english":"Has there reached you the story of the honored guests of Abraham"},{"number":25,"arabic":"إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ","transliteration":"Ith dakhaloo AAalayhi faqaloo salaman qala salamun qawmun munkaroona","english":"When they entered upon him and said, \"[We greet you with] peace.\" He answered, \"[And upon you] peace, [you are] a people unknown"},{"number":26,"arabic":"فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ","transliteration":"Faragha ila ahlihi fajaa biAAijlin sameenin","english":"Then he went to his family and came with a fat [roasted] calf"},{"number":27,"arabic":"فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ","transliteration":"Faqarrabahu ilayhim qala ala takuloona","english":"And placed it near them; he said, \"Will you not eat"},{"number":28,"arabic":"فَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٖ","transliteration":"Faawjasa minhum kheefatan qaloo la takhaf wabashsharoohu bighulamin AAaleemin","english":"And he felt from them apprehension. They said, \"Fear not,\" and gave him good tidings of a learned boy"},{"number":29,"arabic":"فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِي صَرَّةٖ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِيمٞ","transliteration":"Faaqbalati imraatuhu fee sarratin fasakkat wajhaha waqalat AAajoozun AAaqeemun","english":"And his wife approached with a cry [of alarm] and struck her face and said, \"[I am] a barren old woman"},{"number":30,"arabic":"قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ","transliteration":"Qaloo kathaliki qala rabbuki innahu huwa alhakeemu alAAaleemu","english":"They said, \"Thus has said your Lord; indeed, He is the Wise, the Knowing"},{"number":31,"arabic":"۞قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ","transliteration":"Qala fama khatbukum ayyuha almursaloona","english":"[Abraham] said, \"Then what is your business [here], O messengers"},{"number":32,"arabic":"قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ","transliteration":"Qaloo inna orsilna ila qawmin mujrimeena","english":"They said, \"Indeed, we have been sent to a people of criminals"},{"number":33,"arabic":"لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَةٗ مِّن طِينٖ","transliteration":"Linursila AAalayhim hijaratan min teenin","english":"To send down upon them stones of clay"},{"number":34,"arabic":"مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِينَ","transliteration":"Musawwamatan AAinda rabbika lilmusrifeena","english":"Marked in the presence of your Lord for the transgressors"},{"number":35,"arabic":"فَأَخۡرَجۡنَا مَن كَانَ فِيهَا مِنَ ٱلۡمُؤۡمِنِينَ","transliteration":"Faakhrajna man kana feeha mina almumineena","english":"So We brought out whoever was in the cities of the believers"},{"number":36,"arabic":"فَمَا وَجَدۡنَا فِيهَا غَيۡرَ بَيۡتٖ مِّنَ ٱلۡمُسۡلِمِينَ","transliteration":"Fama wajadna feeha ghayra baytin mina almuslimeena","english":"And We found not within them other than a [single] house of Muslims"},{"number":37,"arabic":"وَتَرَكۡنَا فِيهَآ ءَايَةٗ لِّلَّذِينَ يَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِيمَ","transliteration":"Watarakna feeha ayatan lillatheena yakhafoona alAAathaba alaleema","english":"And We left therein a sign for those who fear the painful punishment"},{"number":38,"arabic":"وَفِي مُوسَىٰٓ إِذۡ أَرۡسَلۡنَٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَٰنٖ مُّبِينٖ","transliteration":"Wafee moosa ith arsalnahu ila firAAawna bisultanin mubeenin","english":"And in Moses [was a sign], when We sent him to Pharaoh with clear authority"},{"number":39,"arabic":"فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَٰحِرٌ أَوۡ مَجۡنُونٞ","transliteration":"Fatawalla biruknihi waqala sahirun aw majnoonun","english":"But he turned away with his supporters and said,\" A magician or a madman"},{"number":40,"arabic":"فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ فِي ٱلۡيَمِّ وَهُوَ مُلِيمٞ","transliteration":"Faakhathnahu wajunoodahu fanabathnahum fee alyammi wahuwa muleemun","english":"So We took him and his soldiers and cast them into the sea, and he was blameworthy"},{"number":41,"arabic":"وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ ٱلۡعَقِيمَ","transliteration":"Wafee AAadin ith arsalna AAalayhimu alrreeha alAAaqeema","english":"And in 'Aad [was a sign], when We sent against them the barren wind"},{"number":42,"arabic":"مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ","transliteration":"Ma tatharu min shayin atat AAalayhi illa jaAAalathu kaalrrameemi","english":"It left nothing of what it came upon but that it made it like disintegrated ruins"},{"number":43,"arabic":"وَفِي ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُواْ حَتَّىٰ حِينٖ","transliteration":"Wafee thamooda ith qeela lahum tamattaAAoo hatta heenin","english":"And in Thamud, when it was said to them, \"Enjoy yourselves for a time"},{"number":44,"arabic":"فَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ وَهُمۡ يَنظُرُونَ","transliteration":"FaAAataw AAan amri rabbihim faakhathathumu alssaAAiqatu wahum yanthuroona","english":"But they were insolent toward the command of their Lord, so the thunderbolt seized them while they were looking on"},{"number":45,"arabic":"فَمَا ٱسۡتَطَٰعُواْ مِن قِيَامٖ وَمَا كَانُواْ مُنتَصِرِينَ","transliteration":"Fama istataAAoo min qiyamin wama kanoo muntasireena","english":"And they were unable to arise, nor could they defend themselves"},{"number":46,"arabic":"وَقَوۡمَ نُوحٖ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ","transliteration":"Waqawma noohin min qablu innahum kanoo qawman fasiqeena","english":"And [We destroyed] the people of Noah before; indeed, they were a people defiantly disobedient"},{"number":47,"arabic":"وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدٖ وَإِنَّا لَمُوسِعُونَ","transliteration":"Waalssamaa banaynaha biaydin wainna lamoosiAAoona","english":"And the heaven We constructed with strength, and indeed, We are [its] expander"},{"number":48,"arabic":"وَٱلۡأَرۡضَ فَرَشۡنَٰهَا فَنِعۡمَ ٱلۡمَٰهِدُونَ","transliteration":"Waalarda farashnaha faniAAma almahidoona","english":"And the earth We have spread out, and excellent is the preparer"},{"number":49,"arabic":"وَمِن كُلِّ شَيۡءٍ خَلَقۡنَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ","transliteration":"Wamin kulli shayin khalaqna zawjayni laAAallakum tathakkaroona","english":"And of all things We created two mates; perhaps you will remember"},{"number":50,"arabic":"فَفِرُّوٓاْ إِلَى ٱللَّهِۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ","transliteration":"Fafirroo ila Allahi innee lakum minhu natheerun mubeenun","english":"So flee to Allah. Indeed, I am to you from Him a clear warner"},{"number":51,"arabic":"وَلَا تَجۡعَلُواْ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۖ إِنِّي لَكُم مِّنۡهُ نَذِيرٞ مُّبِينٞ","transliteration":"Wala tajAAaloo maAAa Allahi ilahan akhara innee lakum minhu natheerun mubeenun","english":"And do not make [as equal] with Allah another deity. Indeed, I am to you from Him a clear warner"},{"number":52,"arabic":"كَذَٰلِكَ مَآ أَتَى ٱلَّذِينَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُواْ سَاحِرٌ أَوۡ مَجۡنُونٌ","transliteration":"Kathalika ma ata allatheena min qablihim min rasoolin illa qaloo sahirun aw majnoonun","english":"Similarly, there came not to those before them any messenger except that they said, \"A magician or a madman"},{"number":53,"arabic":"أَتَوَاصَوۡاْ بِهِۦۚ بَلۡ هُمۡ قَوۡمٞ طَاغُونَ","transliteration":"Atawasaw bihi bal hum qawmun taghoona","english":"Did they suggest it to them? Rather, they [themselves] are a transgressing people"},{"number":54,"arabic":"فَتَوَلَّ عَنۡهُمۡ فَمَآ أَنتَ بِمَلُومٖ","transliteration":"Fatawalla AAanhum fama anta bimaloomin","english":"So leave them, [O Muhammad], for you are not to be blamed"},{"number":55,"arabic":"وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِينَ","transliteration":"Wathakkir fainna alththikra tanfaAAu almumineena","english":"And remind, for indeed, the reminder benefits the believers"},{"number":56,"arabic":"وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِيَعۡبُدُونِ","transliteration":"Wama khalaqtu aljinna waalinsa illa liyaAAbudooni","english":"And I did not create the jinn and mankind except to worship Me"},{"number":57,"arabic":"مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ وَمَآ أُرِيدُ أَن يُطۡعِمُونِ","transliteration":"Ma oreedu minhum min rizqin wama oreedu an yutAAimooni","english":"I do not want from them any provision, nor do I want them to feed Me"},{"number":58,"arabic":"إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ","transliteration":"Inna Allaha huwa alrrazzaqu thoo alquwwati almateenu","english":"Indeed, it is Allah who is the [continual] Provider, the firm possessor of strength"},{"number":59,"arabic":"فَإِنَّ لِلَّذِينَ ظَلَمُواْ ذَنُوبٗا مِّثۡلَ ذَنُوبِ أَصۡحَٰبِهِمۡ فَلَا يَسۡتَعۡجِلُونِ","transliteration":"Fainna lillatheena thalamoo thanooban mithla thanoobi ashabihim fala yastaAAjiloona","english":"And indeed, for those who have wronged is a portion [of punishment] like the portion of their predecessors, so let them not impatiently urge Me"},{"number":60,"arabic":"فَوَيۡلٞ لِّلَّذِينَ كَفَرُواْ مِن يَوۡمِهِمُ ٱلَّذِي يُوعَدُونَ","transliteration":"Fawaylun lillatheena kafaroo min yawmihimu allathee yooAAadoona","english":"And woe to those who have disbelieved from their Day which they are promised"}]},{"number":50,"name":"Qaf","arabicName":"ق","meaning":"The Letter \"Qaf\"","minutes":7.9,"ayahs":[{"number":1,"arabic":"قٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ","transliteration":"Qaf waalqurani almajeedi","english":"Qaf. By the honored Qur'an"},{"number":2,"arabic":"بَلۡ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡ فَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا شَيۡءٌ عَجِيبٌ","transliteration":"Bal AAajiboo an jaahum munthirun minhum faqala alkafiroona hatha shayon AAajeebun","english":"But they wonder that there has come to them a warner from among themselves, and the disbelievers say, \"This is an amazing thing"},{"number":3,"arabic":"أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗاۖ ذَٰلِكَ رَجۡعُۢ بَعِيدٞ","transliteration":"Aitha mitna wakunna turaban thalika rajAAun baAAeedun","english":"When we have died and have become dust, [we will return to life]? That is a distant return"},{"number":4,"arabic":"قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَٰبٌ حَفِيظُۢ","transliteration":"Qad AAalimna ma tanqusu alardu minhum waAAindana kitabun hafeethun","english":"We know what the earth diminishes of them, and with Us is a retaining record"},{"number":5,"arabic":"بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ","transliteration":"Bal kaththaboo bialhaqqi lamma jaahum fahum fee amrin mareejin","english":"But they denied the truth when it came to them, so they are in a confused condition"},{"number":6,"arabic":"أَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٖ","transliteration":"Afalam yanthuroo ila alssamai fawqahum kayfa banaynaha wazayyannaha wama laha min furoojin","english":"Have they not looked at the heaven above them - how We structured it and adorned it and [how] it has no rifts"},{"number":7,"arabic":"وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجٖ","transliteration":"Waalarda madadnaha waalqayna feeha rawasiya waanbatna feeha min kulli zawjin baheejin","english":"And the earth - We spread it out and cast therein firmly set mountains and made grow therein [something] of every beautiful kind"},{"number":8,"arabic":"تَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ","transliteration":"Tabsiratan wathikra likulli AAabdin muneebin","english":"Giving insight and a reminder for every servant who turns [to Allah]"},{"number":9,"arabic":"وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّـٰتٖ وَحَبَّ ٱلۡحَصِيدِ","transliteration":"Wanazzalna mina alssamai maan mubarakan faanbatna bihi jannatin wahabba alhaseedi","english":"And We have sent down blessed rain from the sky and made grow thereby gardens and grain from the harvest"},{"number":10,"arabic":"وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ","transliteration":"Waalnnakhla basiqatin laha talAAun nadeedun","english":"And lofty palm trees having fruit arranged in layers"},{"number":11,"arabic":"رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ","transliteration":"Rizqan lilAAibadi waahyayna bihi baldatan maytan kathalika alkhurooju","english":"As provision for the servants, and We have given life thereby to a dead land. Thus is the resurrection"},{"number":12,"arabic":"كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ","transliteration":"Kaththabat qablahum qawmu noohin waashabu alrrassi wathamoodu","english":"The people of Noah denied before them, and the companions of the well and Thamud"},{"number":13,"arabic":"وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ","transliteration":"WaAAadun wafirAAawnu waikhwanu lootin","english":"And 'Aad and Pharaoh and the brothers of Lot"},{"number":14,"arabic":"وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ","transliteration":"Waashabu alaykati waqawmu tubbaAAin kullun kaththaba alrrusula fahaqqa waAAeedi","english":"And the companions of the thicket and the people of Tubba'. All denied the messengers, so My threat was justly fulfilled"},{"number":15,"arabic":"أَفَعَيِينَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِي لَبۡسٖ مِّنۡ خَلۡقٖ جَدِيدٖ","transliteration":"AfaAAayeena bialkhalqi alawwali bal hum fee labsin min khalqin jadeedin","english":"Did We fail in the first creation? But they are in confusion over a new creation"},{"number":16,"arabic":"وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ","transliteration":"Walaqad khalaqna alinsana wanaAAlamu ma tuwaswisu bihi nafsuhu wanahnu aqrabu ilayhi min habli alwareedi","english":"And We have already created man and know what his soul whispers to him, and We are closer to him than [his] jugular vein"},{"number":17,"arabic":"إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ","transliteration":"Ith yatalaqqa almutalaqqiyani AAani alyameeni waAAani alshshimali qaAAeedun","english":"When the two receivers receive, seated on the right and on the left"},{"number":18,"arabic":"مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدٞ","transliteration":"Ma yalfithu min qawlin illa ladayhi raqeebun AAateedun","english":"Man does not utter any word except that with him is an observer prepared [to record]"},{"number":19,"arabic":"وَجَآءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ","transliteration":"Wajaat sakratu almawti bialhaqqi thalika ma kunta minhu taheedu","english":"And the intoxication of death will bring the truth; that is what you were trying to avoid"},{"number":20,"arabic":"وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ ٱلۡوَعِيدِ","transliteration":"Wanufikha fee alssoori thalika yawmu alwaAAeedi","english":"And the Horn will be blown. That is the Day of [carrying out] the threat"},{"number":21,"arabic":"وَجَآءَتۡ كُلُّ نَفۡسٖ مَّعَهَا سَآئِقٞ وَشَهِيدٞ","transliteration":"Wajaat kullu nafsin maAAaha saiqun washaheedun","english":"And every soul will come, with it a driver and a witness"},{"number":22,"arabic":"لَّقَدۡ كُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ","transliteration":"Laqad kunta fee ghaflatin min hatha fakashafna AAanka ghitaaka fabasaruka alyawma hadeedun","english":"[It will be said], \"You were certainly in unmindfulness of this, and We have removed from you your cover, so your sight, this Day, is sharp"},{"number":23,"arabic":"وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ","transliteration":"Waqala qareenuhu hatha ma ladayya AAateedun","english":"And his companion, [the angel], will say, \"This [record] is what is with me, prepared"},{"number":24,"arabic":"أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٖ","transliteration":"Alqiya fee jahannama kulla kaffarin AAaneedin","english":"[Allah will say], \"Throw into Hell every obstinate disbeliever"},{"number":25,"arabic":"مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٖ مُّرِيبٍ","transliteration":"MannaAAin lilkhayri muAAtadin mureebin","english":"Preventer of good, aggressor, and doubter"},{"number":26,"arabic":"ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ","transliteration":"Allathee jaAAala maAAa Allahi ilahan akhara faalqiyahu fee alAAathabi alshshadeedi","english":"Who made [as equal] with Allah another deity; then throw him into the severe punishment"},{"number":27,"arabic":"۞قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ وَلَٰكِن كَانَ فِي ضَلَٰلِۭ بَعِيدٖ","transliteration":"Qala qareenuhu rabbana ma atghaytuhu walakin kana fee dalalin baAAeedin","english":"His [devil] companion will say, \"Our Lord, I did not make him transgress, but he [himself] was in extreme error"},{"number":28,"arabic":"قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ إِلَيۡكُم بِٱلۡوَعِيدِ","transliteration":"Qala la takhtasimoo ladayya waqad qaddamtu ilaykum bialwaAAeedi","english":"[Allah] will say, \"Do not dispute before Me, while I had already presented to you the warning"},{"number":29,"arabic":"مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّـٰمٖ لِّلۡعَبِيدِ","transliteration":"Ma yubaddalu alqawlu ladayya wama ana bithallamin lilAAabeedi","english":"The word will not be changed with Me, and never will I be unjust to the servants"},{"number":30,"arabic":"يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ","transliteration":"Yawma naqoolu lijahannama hali imtalati wataqoolu hal min mazeedin","english":"On the Day We will say to Hell, \"Have you been filled?\" and it will say, \"Are there some more"},{"number":31,"arabic":"وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ","transliteration":"Waozlifati aljannatu lilmuttaqeena ghayra baAAeedin","english":"And Paradise will be brought near to the righteous, not far"},{"number":32,"arabic":"هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٖ","transliteration":"Hatha ma tooAAadoona likulli awwabin hafeethin","english":"[It will be said], \"This is what you were promised - for every returner [to Allah] and keeper [of His covenant]"},{"number":33,"arabic":"مَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبٖ مُّنِيبٍ","transliteration":"Man khashiya alrrahmana bialghaybi wajaa biqalbin muneebin","english":"Who feared the Most Merciful unseen and came with a heart returning [in repentance]"},{"number":34,"arabic":"ٱدۡخُلُوهَا بِسَلَٰمٖۖ ذَٰلِكَ يَوۡمُ ٱلۡخُلُودِ","transliteration":"Odkhulooha bisalamin thalika yawmu alkhuloodi","english":"Enter it in peace. This is the Day of Eternity"},{"number":35,"arabic":"لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيۡنَا مَزِيدٞ","transliteration":"Lahum ma yashaoona feeha waladayna mazeedun","english":"They will have whatever they wish therein, and with Us is more"},{"number":36,"arabic":"وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشٗا فَنَقَّبُواْ فِي ٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ","transliteration":"Wakam ahlakna qablahum min qarnin hum ashaddu minhum batshan fanaqqaboo fee albiladi hal min maheesin","english":"And how many a generation before them did We destroy who were greater than them in [striking] power and had explored throughout the lands. Is there any place of escape"},{"number":37,"arabic":"إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ","transliteration":"Inna fee thalika lathikra liman kana lahu qalbun aw alqa alssamAAa wahuwa shaheedun","english":"Indeed in that is a reminder for whoever has a heart or who listens while he is present [in mind]"},{"number":38,"arabic":"وَلَقَدۡ خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ وَمَا مَسَّنَا مِن لُّغُوبٖ","transliteration":"Walaqad khalaqna alssamawati waalarda wama baynahuma fee sittati ayyamin wama massana min lughoobin","english":"And We did certainly create the heavens and earth and what is between them in six days, and there touched Us no weariness"},{"number":39,"arabic":"فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ","transliteration":"Faisbir AAala ma yaqooloona wasabbih bihamdi rabbika qabla tulooAAi alshshamsi waqabla alghuroobi","english":"So be patient, [O Muhammad], over what they say and exalt [Allah] with praise of your Lord before the rising of the sun and before its setting"},{"number":40,"arabic":"وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ","transliteration":"Wamina allayli fasabbihhu waadbara alssujoodi","english":"And [in part] of the night exalt Him and after prostration"},{"number":41,"arabic":"وَٱسۡتَمِعۡ يَوۡمَ يُنَادِ ٱلۡمُنَادِ مِن مَّكَانٖ قَرِيبٖ","transliteration":"WaistamiAA yawma yunadi almunadi min makanin qareebin","english":"And listen on the Day when the Caller will call out from a place that is near"},{"number":42,"arabic":"يَوۡمَ يَسۡمَعُونَ ٱلصَّيۡحَةَ بِٱلۡحَقِّۚ ذَٰلِكَ يَوۡمُ ٱلۡخُرُوجِ","transliteration":"Yawma yasmaAAoona alssayhata bialhaqqi thalika yawmu alkhurooji","english":"The Day they will hear the blast [of the Horn] in truth. That is the Day of Emergence [from the graves]"},{"number":43,"arabic":"إِنَّا نَحۡنُ نُحۡيِۦ وَنُمِيتُ وَإِلَيۡنَا ٱلۡمَصِيرُ","transliteration":"Inna nahnu nuhyee wanumeetu wailayna almaseeru","english":"Indeed, it is We who give life and cause death, and to Us is the destination"},{"number":44,"arabic":"يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعٗاۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرٞ","transliteration":"Yawma tashaqqaqu alardu AAanhum siraAAan thalika hashrun AAalayna yaseerun","english":"On the Day the earth breaks away from them [and they emerge] rapidly; that is a gathering easy for Us"},{"number":45,"arabic":"نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارٖۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ","transliteration":"Nahnu aAAlamu bima yaqooloona wama anta AAalayhim bijabbarin fathakkir bialqurani man yakhafu waAAeedi","english":"We are most knowing of what they say, and you are not over them a tyrant. But remind by the Qur'an whoever fears My threat"}]},{"number":49,"name":"Al-Hujurat","arabicName":"الحجرات","meaning":"The Rooms","minutes":8.1,"ayahs":[{"number":1,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","transliteration":"Ya ayyuha allatheena amanoo la tuqaddimoo bayna yadayi Allahi warasoolihi waittaqoo Allaha inna Allaha sameeAAun AAaleemun","english":"O you who have believed, do not put [yourselves] before Allah and His Messenger but fear Allah. Indeed, Allah is Hearing and Knowing"},{"number":2,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ","transliteration":"Ya ayyuha allatheena amanoo la tarfaAAoo aswatakum fawqa sawti alnnabiyyi wala tajharoo lahu bialqawli kajahri baAAdikum libaAAdin an tahbata aAAmalukum waantum la tashAAuroona","english":"O you who have believed, do not raise your voices above the voice of the Prophet or be loud to him in speech like the loudness of some of you to others, lest your deeds become worthless while you perceive not"},{"number":3,"arabic":"إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ","transliteration":"Inna allatheena yaghuddoona aswatahum AAinda rasooli Allahi olaika allatheena imtahana Allahu quloobahum lilttaqwa lahum maghfiratun waajrun AAatheemun","english":"Indeed, those who lower their voices before the Messenger of Allah - they are the ones whose hearts Allah has tested for righteousness. For them is forgiveness and great reward"},{"number":4,"arabic":"إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ","transliteration":"Inna allatheena yunadoonaka min warai alhujurati aktharuhum la yaAAqiloona","english":"Indeed, those who call you, [O Muhammad], from behind the chambers - most of them do not use reason"},{"number":5,"arabic":"وَلَوۡ أَنَّهُمۡ صَبَرُواْ حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡرٗا لَّهُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","transliteration":"Walaw annahum sabaroo hatta takhruja ilayhim lakana khayran lahum waAllahu ghafoorun raheemun","english":"And if they had been patient until you [could] come out to them, it would have been better for them. But Allah is Forgiving and Merciful"},{"number":6,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ","transliteration":"Ya ayyuha allatheena amanoo in jaakum fasiqun binabain fatabayyanoo an tuseeboo qawman bijahalatin fatusbihoo AAala ma faAAaltum nadimeena","english":"O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful"},{"number":7,"arabic":"وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَـٰٓئِكَ هُمُ ٱلرَّـٰشِدُونَ","transliteration":"WaiAAlamoo anna feekum rasoola Allahi law yuteeAAukum fee katheerin mina alamri laAAanittum walakinna Allaha habbaba ilaykumu aleemana wazayyanahu fee quloobikum wakarraha ilaykumu alkufra waalfusooqa waalAAisyana olaika humu alrrashidoona","english":"And know that among you is the Messenger of Allah. If he were to obey you in much of the matter, you would be in difficulty, but Allah has endeared to you the faith and has made it pleasing in your hearts and has made hateful to you disbelief, defiance and disobedience. Those are the [rightly] guided"},{"number":8,"arabic":"فَضۡلٗا مِّنَ ٱللَّهِ وَنِعۡمَةٗۚ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","transliteration":"Fadlan mina Allahi waniAAmatan waAllahu AAaleemun hakeemun","english":"[It is] as bounty from Allah and favor. And Allah is Knowing and Wise"},{"number":9,"arabic":"وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","transliteration":"Wain taifatani mina almumineena iqtataloo faaslihoo baynahuma fain baghat ihdahuma AAala alokhra faqatiloo allatee tabghee hatta tafeea ila amri Allahi fain faat faaslihoo baynahuma bialAAadli waaqsitoo inna Allaha yuhibbu almuqsiteena","english":"And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allah. And if it returns, then make settlement between them in justice and act justly. Indeed, Allah loves those who act justly"},{"number":10,"arabic":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","transliteration":"Innama almuminoona ikhwatun faaslihoo bayna akhawaykum waittaqoo Allaha laAAallakum turhamoona","english":"The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy"},{"number":11,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ","transliteration":"Ya ayyuha allatheena amanoo la yaskhar qawmun min qawmin AAasa an yakoonoo khayran minhum wala nisaon min nisain AAasa an yakunna khayran minhunna wala talmizoo anfusakum wala tanabazoo bialalqabi bisa alismu alfusooqu baAAda aleemani waman lam yatub faolaika humu alththalimoona","english":"O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name of disobedience after [one's] faith. And whoever does not repent - then it is those who are the wrongdoers"},{"number":12,"arabic":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ","transliteration":"Ya ayyuha allatheena amanoo ijtaniboo katheeran mina alththanni inna baAAda alththanni ithmun wala tajassasoo wala yaghtab baAAdukum baAAdan ayuhibbu ahadukum an yakula lahma akheehi maytan fakarihtumoohu waittaqoo Allaha inna Allaha tawwabun raheemun","english":"O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful"},{"number":13,"arabic":"يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ","transliteration":"Ya ayyuha alnnasu inna khalaqnakum min thakarin waontha wajaAAalnakum shuAAooban waqabaila litaAAarafoo inna akramakum AAinda Allahi atqakum inna Allaha AAaleemun khabeerun","english":"O mankind, indeed We have created you from male and female and made you peoples and tribes that you may know one another. Indeed, the most noble of you in the sight of Allah is the most righteous of you. Indeed, Allah is Knowing and Acquainted"},{"number":14,"arabic":"۞قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","transliteration":"Qalati alaAArabu amanna qul lam tuminoo walakin qooloo aslamna walamma yadkhuli aleemanu fee quloobikum wain tuteeAAoo Allaha warasoolahu la yalitkum min aAAmalikum shayan inna Allaha ghafoorun raheemun","english":"The bedouins say, \"We have believed.\" Say, \"You have not [yet] believed; but say [instead], 'We have submitted,' for faith has not yet entered your hearts. And if you obey Allah and His Messenger, He will not deprive you from your deeds of anything. Indeed, Allah is Forgiving and Merciful"},{"number":15,"arabic":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ","transliteration":"Innama almuminoona allatheena amanoo biAllahi warasoolihi thumma lam yartaboo wajahadoo biamwalihim waanfusihim fee sabeeli Allahi olaika humu alssadiqoona","english":"The believers are only the ones who have believed in Allah and His Messenger and then doubt not but strive with their properties and their lives in the cause of Allah. It is those who are the truthful"},{"number":16,"arabic":"قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","transliteration":"Qul atuAAallimoona Allaha bideenikum waAllahu yaAAlamu ma fee alssamawati wama fee alardi waAllahu bikulli shayin AAaleemun","english":"Say, \"Would you acquaint Allah with your religion while Allah knows whatever is in the heavens and whatever is on the earth, and Allah is Knowing of all things"},{"number":17,"arabic":"يَمُنُّونَ عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ","transliteration":"Yamunnoona AAalayka an aslamoo qul la tamunnoo AAalayya islamakum bali Allahu yamunnu AAalaykum an hadakum lileemani in kuntum sadiqeena","english":"They consider it a favor to you that they have accepted Islam. Say, \"Do not consider your Islam a favor to me. Rather, Allah has conferred favor upon you that He has guided you to the faith, if you should be truthful"},{"number":18,"arabic":"إِنَّ ٱللَّهَ يَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ","transliteration":"Inna Allaha yaAAlamu ghayba alssamawati waalardi waAllahu baseerun bima taAAmaloona","english":"Indeed, Allah knows the unseen [aspects] of the heavens and the earth. And Allah is Seeing of what you do"}]},{"number":44,"name":"Ad-Dukhan","arabicName":"الدخان","meaning":"The Smoke","minutes":7.7,"ayahs":[{"number":1,"arabic":"حمٓ","transliteration":"Hameem","english":"Ha, Meem"},{"number":2,"arabic":"وَٱلۡكِتَٰبِ ٱلۡمُبِينِ","transliteration":"Waalkitabi almubeeni","english":"By the clear Book"},{"number":3,"arabic":"إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ","transliteration":"Inna anzalnahu fee laylatin mubarakatin inna kunna munthireena","english":"Indeed, We sent it down during a blessed night. Indeed, We were to warn [mankind]"},{"number":4,"arabic":"فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ","transliteration":"Feeha yufraqu kullu amrin hakeemin","english":"On that night is made distinct every precise matter"},{"number":5,"arabic":"أَمۡرٗا مِّنۡ عِندِنَآۚ إِنَّا كُنَّا مُرۡسِلِينَ","transliteration":"Amran min AAindina inna kunna mursileena","english":"[Every] matter [proceeding] from Us. Indeed, We were to send [a messenger]"},{"number":6,"arabic":"رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","transliteration":"Rahmatan min rabbika innahu huwa alssameeAAu alAAaleemu","english":"As mercy from your Lord. Indeed, He is the Hearing, the Knowing"},{"number":7,"arabic":"رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ","transliteration":"Rabbi alssamawati waalardi wama baynahuma in kuntum mooqineena","english":"Lord of the heavens and the earth and that between them, if you would be certain"},{"number":8,"arabic":"لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ","transliteration":"La ilaha illa huwa yuhyee wayumeetu rabbukum warabbu abaikumu alawwaleena","english":"There is no deity except Him; He gives life and causes death. [He is] your Lord and the Lord of your first forefathers"},{"number":9,"arabic":"بَلۡ هُمۡ فِي شَكّٖ يَلۡعَبُونَ","transliteration":"Bal hum fee shakkin yalAAaboona","english":"But they are in doubt, amusing themselves"},{"number":10,"arabic":"فَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانٖ مُّبِينٖ","transliteration":"Fairtaqib yawma tatee alssamao bidukhanin mubeenin","english":"Then watch for the Day when the sky will bring a visible smoke"},{"number":11,"arabic":"يَغۡشَى ٱلنَّاسَۖ هَٰذَا عَذَابٌ أَلِيمٞ","transliteration":"Yaghsha alnnasa hatha AAathabun aleemun","english":"Covering the people; this is a painful torment"},{"number":12,"arabic":"رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ","transliteration":"Rabbana ikshif AAanna alAAathaba inna muminoona","english":"[They will say], \"Our Lord, remove from us the torment; indeed, we are believers"},{"number":13,"arabic":"أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَآءَهُمۡ رَسُولٞ مُّبِينٞ","transliteration":"Anna lahumu alththikra waqad jaahum rasoolun mubeenun","english":"How will there be for them a reminder [at that time]? And there had come to them a clear Messenger"},{"number":14,"arabic":"ثُمَّ تَوَلَّوۡاْ عَنۡهُ وَقَالُواْ مُعَلَّمٞ مَّجۡنُونٌ","transliteration":"Thumma tawallaw AAanhu waqaloo muAAallamun majnoonun","english":"Then they turned away from him and said, \"[He was] taught [and is] a madman"},{"number":15,"arabic":"إِنَّا كَاشِفُواْ ٱلۡعَذَابِ قَلِيلًاۚ إِنَّكُمۡ عَآئِدُونَ","transliteration":"Inna kashifoo alAAathabi qaleelan innakum AAaidoona","english":"Indeed, We will remove the torment for a little. Indeed, you [disbelievers] will return [to disbelief]"},{"number":16,"arabic":"يَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰٓ إِنَّا مُنتَقِمُونَ","transliteration":"Yawma nabtishu albatshata alkubra inna muntaqimoona","english":"The Day We will strike with the greatest assault, indeed, We will take retribution"},{"number":17,"arabic":"۞وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ كَرِيمٌ","transliteration":"Walaqad fatanna qablahum qawma firAAawna wajaahum rasoolun kareemun","english":"And We had already tried before them the people of Pharaoh, and there came to them a noble messenger"},{"number":18,"arabic":"أَنۡ أَدُّوٓاْ إِلَيَّ عِبَادَ ٱللَّهِۖ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","transliteration":"An addoo ilayya AAibada Allahi innee lakum rasoolun ameenun","english":"[Saying], \"Render to me the servants of Allah. Indeed, I am to you a trustworthy messenger"},{"number":19,"arabic":"وَأَن لَّا تَعۡلُواْ عَلَى ٱللَّهِۖ إِنِّيٓ ءَاتِيكُم بِسُلۡطَٰنٖ مُّبِينٖ","transliteration":"Waan la taAAloo AAala Allahi innee ateekum bisultanin mubeenin","english":"And [saying], \"Be not haughty with Allah. Indeed, I have come to you with clear authority"},{"number":20,"arabic":"وَإِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُمۡ أَن تَرۡجُمُونِ","transliteration":"Wainnee AAuthtu birabbee warabbikum an tarjumooni","english":"And indeed, I have sought refuge in my Lord and your Lord, lest you stone me"},{"number":21,"arabic":"وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ","transliteration":"Wain lam tuminoo lee faiAAtazilooni","english":"But if you do not believe me, then leave me alone"},{"number":22,"arabic":"فَدَعَا رَبَّهُۥٓ أَنَّ هَـٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ","transliteration":"FadaAAa rabbahu anna haolai qawmun mujrimoona","english":"And [finally] he called to his Lord that these were a criminal people"},{"number":23,"arabic":"فَأَسۡرِ بِعِبَادِي لَيۡلًا إِنَّكُم مُّتَّبَعُونَ","transliteration":"Faasri biAAibadee laylan innakum muttabaAAoona","english":"[Allah said], \"Then set out with My servants by night. Indeed, you are to be pursued"},{"number":24,"arabic":"وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندٞ مُّغۡرَقُونَ","transliteration":"Waotruki albahra rahwan innahum jundun mughraqoona","english":"And leave the sea in stillness. Indeed, they are an army to be drowned"},{"number":25,"arabic":"كَمۡ تَرَكُواْ مِن جَنَّـٰتٖ وَعُيُونٖ","transliteration":"Kam tarakoo min jannatin waAAuyoonin","english":"How much they left behind of gardens and springs"},{"number":26,"arabic":"وَزُرُوعٖ وَمَقَامٖ كَرِيمٖ","transliteration":"WazurooAAin wamaqamin kareemin","english":"And crops and noble sites"},{"number":27,"arabic":"وَنَعۡمَةٖ كَانُواْ فِيهَا فَٰكِهِينَ","transliteration":"WanaAAmatin kanoo feeha fakiheena","english":"And comfort wherein they were amused"},{"number":28,"arabic":"كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ","transliteration":"Kathalika waawrathnaha qawman akhareena","english":"Thus. And We caused to inherit it another people"},{"number":29,"arabic":"فَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ","transliteration":"Fama bakat AAalayhimu alssamao waalardu wama kanoo munthareena","english":"And the heaven and earth wept not for them, nor were they reprieved"},{"number":30,"arabic":"وَلَقَدۡ نَجَّيۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِينِ","transliteration":"Walaqad najjayna banee israeela mina alAAathabi almuheeni","english":"And We certainly saved the Children of Israel from the humiliating torment"},{"number":31,"arabic":"مِن فِرۡعَوۡنَۚ إِنَّهُۥ كَانَ عَالِيٗا مِّنَ ٱلۡمُسۡرِفِينَ","transliteration":"Min firAAawna innahu kana AAaliyan mina almusrifeena","english":"From Pharaoh. Indeed, he was a haughty one among the transgressors"},{"number":32,"arabic":"وَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ","transliteration":"Walaqadi ikhtarnahum AAala AAilmin AAala alAAalameena","english":"And We certainly chose them by knowledge over [all] the worlds"},{"number":33,"arabic":"وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَـٰٓؤٞاْ مُّبِينٌ","transliteration":"Waataynahum mina alayati ma feehi balaon mubeenun","english":"And We gave them of signs that in which there was a clear trial"},{"number":34,"arabic":"إِنَّ هَـٰٓؤُلَآءِ لَيَقُولُونَ","transliteration":"Inna haolai layaqooloona","english":"Indeed, these [disbelievers] are saying"},{"number":35,"arabic":"إِنۡ هِيَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُنشَرِينَ","transliteration":"In hiya illa mawtatuna aloola wama nahnu bimunshareena","english":"There is not but our first death, and we will not be resurrected"},{"number":36,"arabic":"فَأۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ","transliteration":"Fatoo biabaina in kuntum sadiqeena","english":"Then bring [back] our forefathers, if you should be truthful"},{"number":37,"arabic":"أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ","transliteration":"Ahum khayrun am qawmu tubbaAAin waallatheena min qablihim ahlaknahum innahum kanoo mujrimeena","english":"Are they better or the people of Tubba' and those before them? We destroyed them, [for] indeed, they were criminals"},{"number":38,"arabic":"وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ","transliteration":"Wama khalaqna alssamawati waalarda wama baynahuma laAAibeena","english":"And We did not create the heavens and earth and that between them in play"},{"number":39,"arabic":"مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","transliteration":"Ma khalaqnahuma illa bialhaqqi walakinna aktharahum la yaAAlamoona","english":"We did not create them except in truth, but most of them do not know"},{"number":40,"arabic":"إِنَّ يَوۡمَ ٱلۡفَصۡلِ مِيقَٰتُهُمۡ أَجۡمَعِينَ","transliteration":"Inna yawma alfasli meeqatuhum ajmaAAeena","english":"Indeed, the Day of Judgement is the appointed time for them all"},{"number":41,"arabic":"يَوۡمَ لَا يُغۡنِي مَوۡلًى عَن مَّوۡلٗى شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ","transliteration":"Yawma la yughnee mawlan AAan mawlan shayan wala hum yunsaroona","english":"The Day when no relation will avail a relation at all, nor will they be helped"},{"number":42,"arabic":"إِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","transliteration":"Illa man rahima Allahu innahu huwa alAAazeezu alrraheemu","english":"Except those [believers] on whom Allah has mercy. Indeed, He is the Exalted in Might, the Merciful"},{"number":43,"arabic":"إِنَّ شَجَرَتَ ٱلزَّقُّومِ","transliteration":"Inna shajarata alzzaqqoomi","english":"Indeed, the tree of zaqqum"},{"number":44,"arabic":"طَعَامُ ٱلۡأَثِيمِ","transliteration":"TaAAamu alatheemi","english":"Is food for the sinful"},{"number":45,"arabic":"كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ","transliteration":"Kaalmuhli yaghlee fee albutooni","english":"Like murky oil, it boils within bellies"},{"number":46,"arabic":"كَغَلۡيِ ٱلۡحَمِيمِ","transliteration":"Kaghalyi alhameemi","english":"Like the boiling of scalding water"},{"number":47,"arabic":"خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَآءِ ٱلۡجَحِيمِ","transliteration":"Khuthoohu faiAAtiloohu ila sawai aljaheemi","english":"[It will be commanded], \"Seize him and drag him into the midst of the Hellfire"},{"number":48,"arabic":"ثُمَّ صُبُّواْ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ ٱلۡحَمِيمِ","transliteration":"Thumma subboo fawqa rasihi min AAathabi alhameemi","english":"Then pour over his head from the torment of scalding water"},{"number":49,"arabic":"ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ","transliteration":"Thuq innaka anta alAAazeezu alkareemu","english":"[It will be said], \"Taste! Indeed, you are the honored, the noble"},{"number":50,"arabic":"إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ","transliteration":"Inna hatha ma kuntum bihi tamtaroona","english":"Indeed, this is what you used to dispute"},{"number":51,"arabic":"إِنَّ ٱلۡمُتَّقِينَ فِي مَقَامٍ أَمِينٖ","transliteration":"Inna almuttaqeena fee maqamin ameenin","english":"Indeed, the righteous will be in a secure place"},{"number":52,"arabic":"فِي جَنَّـٰتٖ وَعُيُونٖ","transliteration":"Fee jannatin waAAuyoonin","english":"Within gardens and springs"},{"number":53,"arabic":"يَلۡبَسُونَ مِن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَقَٰبِلِينَ","transliteration":"Yalbasoona min sundusin waistabraqin mutaqabileena","english":"Wearing [garments of] fine silk and brocade, facing each other"},{"number":54,"arabic":"كَذَٰلِكَ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ","transliteration":"Kathalika wazawwajnahum bihoorin AAeenin","english":"Thus. And We will marry them to fair women with large, [beautiful] eyes"},{"number":55,"arabic":"يَدۡعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ","transliteration":"YadAAoona feeha bikulli fakihatin amineena","english":"They will call therein for every [kind of] fruit - safe and secure"},{"number":56,"arabic":"لَا يَذُوقُونَ فِيهَا ٱلۡمَوۡتَ إِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِيمِ","transliteration":"La yathooqoona feeha almawta illa almawtata aloola wawaqahum AAathaba aljaheemi","english":"They will not taste death therein except the first death, and He will have protected them from the punishment of Hellfire"},{"number":57,"arabic":"فَضۡلٗا مِّن رَّبِّكَۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","transliteration":"Fadlan min rabbika thalika huwa alfawzu alAAatheemu","english":"As bounty from your Lord. That is what is the great attainment"},{"number":58,"arabic":"فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ","transliteration":"Fainnama yassarnahu bilisanika laAAallahum yatathakkaroona","english":"And indeed, We have eased the Qur'an in your tongue that they might be reminded"},{"number":59,"arabic":"فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ","transliteration":"Fairtaqib innahum murtaqiboona","english":"So watch, [O Muhammad]; indeed, they are watching [for your end]"}]},{"number":32,"name":"As-Sajdah","arabicName":"السجدة","meaning":"The Prostration","minutes":8.2,"ayahs":[{"number":1,"arabic":"الٓمٓ","transliteration":"Aliflammeem","english":"Alif, Lam, Meem"},{"number":2,"arabic":"تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ","transliteration":"Tanzeelu alkitabi la rayba feehi min rabbi alAAalameena","english":"[This is] the revelation of the Book about which there is no doubt from the Lord of the worlds"},{"number":3,"arabic":"أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمٗا مَّآ أَتَىٰهُم مِّن نَّذِيرٖ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ","transliteration":"Am yaqooloona iftarahu bal huwa alhaqqu min rabbika litunthira qawman ma atahum min natheerin min qablika laAAallahum yahtadoona","english":"Or do they say, \"He invented it\"? Rather, it is the truth from your Lord, [O Muhammad], that you may warn a people to whom no warner has come before you [so] perhaps they will be guided"},{"number":4,"arabic":"ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ","transliteration":"Allahu allathee khalaqa alssamawati waalarda wama baynahuma fee sittati ayyamin thumma istawa AAala alAAarshi ma lakum min doonihi min waliyyin wala shafeeAAin afala tatathakkaroona","english":"It is Allah who created the heavens and the earth and whatever is between them in six days; then He established Himself above the Throne. You have not besides Him any protector or any intercessor; so will you not be reminded"},{"number":5,"arabic":"يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةٖ مِّمَّا تَعُدُّونَ","transliteration":"Yudabbiru alamra mina alssamai ila alardi thumma yaAAruju ilayhi fee yawmin kana miqdaruhu alfa sanatin mimma taAAuddoona","english":"He arranges [each] matter from the heaven to the earth; then it will ascend to Him in a Day, the extent of which is a thousand years of those which you count"},{"number":6,"arabic":"ذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ","transliteration":"Thalika AAalimu alghaybi waalshshahadati alAAazeezu alrraheemu","english":"That is the Knower of the unseen and the witnessed, the Exalted in Might, the Merciful"},{"number":7,"arabic":"ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ مِن طِينٖ","transliteration":"Allathee ahsana kulla shayin khalaqahu wabadaa khalqa alinsani min teenin","english":"Who perfected everything which He created and began the creation of man from clay"},{"number":8,"arabic":"ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَٰلَةٖ مِّن مَّآءٖ مَّهِينٖ","transliteration":"Thumma jaAAala naslahu min sulalatin min main maheenin","english":"Then He made his posterity out of the extract of a liquid disdained"},{"number":9,"arabic":"ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ","transliteration":"Thumma sawwahu wanafakha feehi min roohihi wajaAAala lakumu alssamAAa waalabsara waalafidata qaleelan ma tashkuroona","english":"Then He proportioned him and breathed into him from His [created] soul and made for you hearing and vision and hearts; little are you grateful"},{"number":10,"arabic":"وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ أَءِنَّا لَفِي خَلۡقٖ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ","transliteration":"Waqaloo aitha dalalna fee alardi ainna lafee khalqin jadeedin bal hum biliqai rabbihim kafiroona","english":"And they say, \"When we are lost within the earth, will we indeed be [recreated] in a new creation?\" Rather, they are, in [the matter of] the meeting with their Lord, disbelievers"},{"number":11,"arabic":"۞قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ","transliteration":"Qul yatawaffakum malaku almawti allathee wukkila bikum thumma ila rabbikum turjaAAoona","english":"Say, \"The angel of death will take you who has been entrusted with you. Then to your Lord you will be returned"},{"number":12,"arabic":"وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ","transliteration":"Walaw tara ithi almujrimoona nakisoo ruoosihim AAinda rabbihim rabbana absarna wasamiAAna faarjiAAna naAAmal salihan inna mooqinoona","english":"If you could but see when the criminals are hanging their heads before their Lord, [saying], \"Our Lord, we have seen and heard, so return us [to the world]; we will work righteousness. Indeed, we are [now] certain"},{"number":13,"arabic":"وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ","transliteration":"Walaw shina laatayna kulla nafsin hudaha walakin haqqa alqawlu minnee laamlaanna jahannama mina aljinnati waalnnasi ajmaAAeena","english":"And if We had willed, We could have given every soul its guidance, but the word from Me will come into effect [that] \"I will surely fill Hell with jinn and people all together"},{"number":14,"arabic":"فَذُوقُواْ بِمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَآ إِنَّا نَسِينَٰكُمۡۖ وَذُوقُواْ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ","transliteration":"Fathooqoo bima naseetum liqaa yawmikum hatha inna naseenakum wathooqoo AAathaba alkhuldi bima kuntum taAAmaloona","english":"So taste [punishment] because you forgot the meeting of this, your Day; indeed, We have [accordingly] forgotten you. And taste the punishment of eternity for what you used to do"},{"number":15,"arabic":"إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدٗاۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩","transliteration":"Innama yuminu biayatina allatheena itha thukkiroo biha kharroo sujjadan wasabbahoo bihamdi rabbihim wahum la yastakbiroona","english":"Only those believe in Our verses who, when they are reminded by them, fall down in prostration and exalt [Allah] with praise of their Lord, and they are not arrogant"},{"number":16,"arabic":"تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفٗا وَطَمَعٗا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","transliteration":"Tatajafa junoobuhum AAani almadajiAAi yadAAoona rabbahum khawfan watamaAAan wamimma razaqnahum yunfiqoona","english":"They arise from [their] beds; they supplicate their Lord in fear and aspiration, and from what We have provided them, they spend"},{"number":17,"arabic":"فَلَا تَعۡلَمُ نَفۡسٞ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنٖ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ","transliteration":"Fala taAAlamu nafsun ma okhfiya lahum min qurrati aAAyunin jazaan bima kanoo yaAAmaloona","english":"And no soul knows what has been hidden for them of comfort for eyes as reward for what they used to do"},{"number":18,"arabic":"أَفَمَن كَانَ مُؤۡمِنٗا كَمَن كَانَ فَاسِقٗاۚ لَّا يَسۡتَوُۥنَ","transliteration":"Afaman kana muminan kaman kana fasiqan la yastawoona","english":"Then is one who was a believer like one who was defiantly disobedient? They are not equal"},{"number":19,"arabic":"أَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ جَنَّـٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُواْ يَعۡمَلُونَ","transliteration":"Amma allatheena amanoo waAAamiloo alssalihati falahum jannatu almawa nuzulan bima kanoo yaAAmaloona","english":"As for those who believed and did righteous deeds, for them will be the Gardens of Refuge as accommodation for what they used to do"},{"number":20,"arabic":"وَأَمَّا ٱلَّذِينَ فَسَقُواْ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ","transliteration":"Waamma allatheena fasaqoo famawahumu alnnaru kullama aradoo an yakhrujoo minha oAAeedoo feeha waqeela lahum thooqoo AAathaba alnnari allathee kuntum bihi tukaththiboona","english":"But as for those who defiantly disobeyed, their refuge is the Fire. Every time they wish to emerge from it, they will be returned to it while it is said to them, \"Taste the punishment of the Fire which you used to deny"},{"number":21,"arabic":"وَلَنُذِيقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ يَرۡجِعُونَ","transliteration":"Walanutheeqannahum mina alAAathabi aladna doona alAAathabi alakbari laAAallahum yarjiAAoona","english":"And we will surely let them taste the nearer punishment short of the greater punishment that perhaps they will repent"},{"number":22,"arabic":"وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ","transliteration":"Waman athlamu mimman thukkira biayati rabbihi thumma aAArada AAanha inna mina almujrimeena muntaqimoona","english":"And who is more unjust than one who is reminded of the verses of his Lord; then he turns away from them? Indeed We, from the criminals, will take retribution"},{"number":23,"arabic":"وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةٖ مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَـٰٓءِيلَ","transliteration":"Walaqad atayna moosa alkitaba fala takun fee miryatin min liqaihi wajaAAalnahu hudan libanee israeela","english":"And We certainly gave Moses the Scripture, so do not be in doubt over his meeting. And we made the Torah guidance for the Children of Israel"},{"number":24,"arabic":"وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ","transliteration":"WajaAAalna minhum aimmatan yahdoona biamrina lamma sabaroo wakanoo biayatina yooqinoona","english":"And We made from among them leaders guiding by Our command when they were patient and [when] they were certain of Our signs"},{"number":25,"arabic":"إِنَّ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ","transliteration":"Inna rabbaka huwa yafsilu baynahum yawma alqiyamati feema kanoo feehi yakhtalifoona","english":"Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ"},{"number":26,"arabic":"أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ","transliteration":"Awalam yahdi lahum kam ahlakna min qablihim mina alqurooni yamshoona fee masakinihim inna fee thalika laayatin afala yasmaAAoona","english":"Has it not become clear to them how many generations We destroyed before them, [as] they walk among their dwellings? Indeed in that are signs; then do they not hear"},{"number":27,"arabic":"أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعٗا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ","transliteration":"Awalam yaraw anna nasooqu almaa ila alardi aljuruzi fanukhriju bihi zarAAan takulu minhu anAAamuhum waanfusuhum afala yubsiroona","english":"Have they not seen that We drive the water [in clouds] to barren land and bring forth thereby crops from which their livestock eat and [they] themselves? Then do they not see"},{"number":28,"arabic":"وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَٰدِقِينَ","transliteration":"Wayaqooloona mata hatha alfathu in kuntum sadiqeena","english":"And they say, \"When will be this conquest, if you should be truthful"},{"number":29,"arabic":"قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ","transliteration":"Qul yawma alfathi la yanfaAAu allatheena kafaroo eemanuhum wala hum yuntharoona","english":"Say, [O Muhammad], \"On the Day of Conquest the belief of those who had disbelieved will not benefit them, nor will they be reprieved"},{"number":30,"arabic":"فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ","transliteration":"FaaAArid AAanhum waintathir innahum muntathiroona","english":"So turn away from them and wait. Indeed, they are waiting"}]}]
"""#
